css:
/* Re-theme with --msc-post-paper, -ink and -accent; reaction hues are the six below. */
.msc-post {
  --msc-post-paper: oklch(0.995 0.003 85);
  --msc-post-ink: oklch(0.24 0.014 55);
  --msc-post-accent: oklch(0.6 0.18 33);
  --msc-post-like: oklch(0.58 0.15 250);
  --msc-post-love: oklch(0.62 0.21 12);
  --msc-post-celebrate: oklch(0.74 0.15 72);
  --msc-post-insight: oklch(0.62 0.13 158);
  --msc-post-funny: oklch(0.7 0.16 50);
  --msc-post-curious: oklch(0.56 0.15 300);

  --msc-post-line: color-mix(in oklch, var(--msc-post-ink) 11%, transparent);
  --msc-post-muted: color-mix(in oklch, var(--msc-post-ink) 66%, var(--msc-post-paper));
  --msc-post-faint: color-mix(in oklch, var(--msc-post-ink) 46%, var(--msc-post-paper));
  --msc-post-hover: color-mix(in oklch, var(--msc-post-ink) 5.5%, transparent);
  --msc-post-ring: color-mix(in oklch, var(--msc-post-accent) 72%, transparent);
  --msc-post-ease: cubic-bezier(.22, 1, .36, 1);
  --msc-post-spring: linear(0, 0.08 4%, 0.33 9%, 0.71 17%, 0.98 25%, 1.09 32%, 1.08 39%, 1.02 50%, 0.99 62%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "text" "media" "stats" "bar" "reply";
  padding: 16px 14px 8px;
  border-radius: 18px;
  overflow: clip;
  color: var(--msc-post-ink);
  background: var(--msc-post-paper);
  box-shadow: 0 0 0 1px var(--msc-post-line), 0 1px 2px color-mix(in oklch, var(--msc-post-ink) 6%, transparent), 0 22px 44px -30px color-mix(in oklch, var(--msc-post-ink) 40%, transparent);
  font: 400 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .msc-post { --msc-post-spring: cubic-bezier(.34, 1.5, .5, 1); }
}
:where(.msc-post) *, :where(.msc-post) *::before, :where(.msc-post) *::after { box-sizing: border-box; }
:where(.msc-post) :is(button, input) { font: inherit; color: inherit; }
:where(.msc-post) button { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.msc-post) :focus-visible { outline: 2px solid var(--msc-post-ring); outline-offset: 2px; }
.msc-post svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.msc-post) :is(h3, h4, p, figure, ul) { margin: 0; }
.msc-post__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* reaction colour per glyph, wherever it appears */
.msc-post [data-r="like"] { --msc-post-r: var(--msc-post-like); }
.msc-post [data-r="love"] { --msc-post-r: var(--msc-post-love); }
.msc-post [data-r="celebrate"] { --msc-post-r: var(--msc-post-celebrate); }
.msc-post [data-r="insight"] { --msc-post-r: var(--msc-post-insight); }
.msc-post [data-r="funny"] { --msc-post-r: var(--msc-post-funny); }
.msc-post [data-r="curious"] { --msc-post-r: var(--msc-post-curious); }

/* ---------- header ---------- */
.msc-post__head {
  grid-area: head;
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; column-gap: 10px;
  margin-bottom: 10px;
}
.msc-post__av {
  display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%;
  font-size: 13px; font-weight: 700; letter-spacing: .02em;
  color: oklch(0.36 0.08 40); background: radial-gradient(circle at 30% 25%, oklch(0.93 0.05 60), oklch(0.84 0.08 45));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--msc-post-ink) 8%, transparent);
}
.msc-post__name {
  display: flex; align-items: center; gap: 5px;
  font-size: clamp(14px, 3.9cqi, 15.5px); font-weight: 680; letter-spacing: -.012em; line-height: 1.25;
  text-wrap: balance;
}
.msc-post__ok {
  width: 16px; height: 16px;
  & circle { fill: var(--msc-post-accent); stroke: none; }
  & path { stroke: var(--msc-post-paper); stroke-width: 2.4; }
}
.msc-post__meta {
  display: flex; flex-wrap: wrap; column-gap: 6px;
  font-size: 12.5px; color: var(--msc-post-faint); line-height: 1.35;
  & > * + *::before { content: "·"; margin-right: 6px; }
  & time { font-variant-numeric: tabular-nums; }
}

.msc-post__text {
  grid-area: text;
  font-size: clamp(13.5px, 3.9cqi, 15px); line-height: 1.5; text-wrap: pretty;
  & b { font-weight: 600; color: var(--msc-post-accent); }
}

/* ---------- media: three glaze test tiles ---------- */
.msc-post__media { grid-area: media; position: relative; margin-top: 12px; user-select: none; -webkit-user-select: none; }
.msc-post__tiles {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 4px;
  border-radius: 14px; overflow: hidden;
}
.msc-post__tile {
  --msc-post-clay: oklch(0.93 0.012 80);
  position: relative; aspect-ratio: 3 / 4;
  display: flex; align-items: flex-end; padding: 8px;
  background: var(--msc-post-g);
  & span {
    position: relative; z-index: 1;
    font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase;
    color: oklch(0.99 0 0); text-shadow: 0 1px 2px oklch(0 0 0 / .35);
  }
  &::before { /* unglazed foot of the tile */
    content: ""; position: absolute; inset: 0 0 auto; height: 19%;
    background: linear-gradient(var(--msc-post-clay), color-mix(in oklch, var(--msc-post-clay) 82%, oklch(0.7 0.03 70)));
    box-shadow: 0 1px 0 color-mix(in oklch, var(--msc-post-clay) 55%, oklch(0.45 0.04 60)), 0 3px 4px -2px oklch(0 0 0 / .18);
  }
  &::after { /* glassy highlight and crazing */
    content: ""; position: absolute; inset: 0;
    background:
      linear-gradient(115deg, transparent 30%, oklch(1 0 0 / .22) 42%, transparent 54%),
      repeating-linear-gradient(61deg, transparent 0 21px, oklch(1 0 0 / .045) 21px 22px),
      repeating-linear-gradient(-27deg, transparent 0 29px, oklch(0 0 0 / .035) 29px 30px),
      linear-gradient(transparent 60%, oklch(0 0 0 / .32));
  }
  &[data-g="celadon"] {
    --msc-post-g:
      radial-gradient(90% 40% at 50% 100%, oklch(0.52 0.08 188), transparent 70%),
      radial-gradient(60% 20% at 40% 22%, oklch(0.88 0.04 160), transparent),
      linear-gradient(oklch(0.83 0.055 165), oklch(0.69 0.07 182));
  }
  &[data-g="ash"] {
    --msc-post-g:
      radial-gradient(80% 34% at 55% 96%, oklch(0.5 0.12 245), transparent 72%),
      radial-gradient(5% 58% at 17% 44%, oklch(0.55 0.1 58 / .75), transparent),
      radial-gradient(4% 48% at 41% 52%, oklch(0.55 0.1 58 / .6), transparent),
      radial-gradient(6% 62% at 63% 40%, oklch(0.78 0.08 85 / .55), transparent),
      radial-gradient(5% 55% at 84% 47%, oklch(0.55 0.1 58 / .7), transparent),
      linear-gradient(oklch(0.72 0.09 80), oklch(0.6 0.1 66));
  }
  &[data-g="tenmoku"] {
    --msc-post-g:
      radial-gradient(140% 26% at 50% 21%, oklch(0.55 0.13 45), transparent 70%),
      radial-gradient(70% 50% at 70% 70%, oklch(0.3 0.05 40), transparent),
      linear-gradient(oklch(0.33 0.06 42), oklch(0.2 0.03 40));
  }
}
@media (hover: hover) {
  .msc-post__tile { transition: filter .3s var(--msc-post-ease); }
  .msc-post__tiles:hover .msc-post__tile:not(:hover) { filter: saturate(.75) brightness(.97); }
}

.msc-post__burst {
  position: absolute; left: var(--x, 50%); top: var(--y, 50%); z-index: 2;
  width: 88px; height: 88px; margin: -44px 0 0 -44px;
  display: grid; place-items: center; pointer-events: none;
  opacity: 0;
  & svg { width: 72px; height: 72px; fill: var(--msc-post-love); stroke: oklch(1 0 0); stroke-width: 1.2; filter: drop-shadow(0 6px 14px oklch(0.4 0.15 12 / .45)); }
  & i {
    position: absolute; left: 50%; top: 50%; width: 6px; height: 6px; margin: -3px; border-radius: 50%;
    background: var(--msc-post-love);
    rotate: calc(var(--k) * 60deg);
  }
  & i:nth-of-type(1) { --k: 0; } & i:nth-of-type(2) { --k: 1; } & i:nth-of-type(3) { --k: 2; }
  & i:nth-of-type(4) { --k: 3; } & i:nth-of-type(5) { --k: 4; } & i:nth-of-type(6) { --k: 5; }
  &.is-on { animation: msc-post-burst .9s var(--msc-post-ease) both; }
  &.is-on svg { animation: msc-post-heart .9s var(--msc-post-spring) both; }
  &.is-on i { animation: msc-post-spark .7s var(--msc-post-ease) .08s both; }
}

/* ---------- stats ---------- */
.msc-post__stats {
  grid-area: stats;
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  min-height: 40px; padding: 8px 2px 6px;
  border-bottom: 1px solid var(--msc-post-line);
}
.msc-post__sum {
  display: inline-flex; align-items: center; gap: 7px; min-width: 0;
  padding: 3px 6px 3px 2px; margin-left: -2px; border-radius: 8px;
  font-size: 12.5px; color: var(--msc-post-muted); text-align: left;
  transition: background-color .2s, color .2s;
  &:hover, &[aria-expanded="true"] { background: var(--msc-post-hover); color: var(--msc-post-ink); }
}
.msc-post__who-reacted { display: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.msc-post__total { font-weight: 560; font-variant-numeric: tabular-nums; }
@container (min-width: 500px) {
  .msc-post__who-reacted { display: block; }
  .msc-post__total { display: none; }
}
.msc-post__stack { display: inline-flex; flex: none; }
.msc-post__badge {
  display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%;
  color: oklch(1 0 0); background: var(--msc-post-r);
  box-shadow: 0 0 0 2px var(--msc-post-paper);
  & + & { margin-left: -5px; }
  & svg { width: 12px; height: 12px; stroke-width: 2.5; }
  &.is-in { animation: msc-post-in .45s var(--msc-post-spring) both; }
}
.msc-post__counts {
  display: flex; gap: 10px; flex: none;
  font-size: 12.5px; color: var(--msc-post-faint); font-variant-numeric: tabular-nums; white-space: nowrap;
}

/* ---------- action bar ---------- */
.msc-post__bar {
  grid-area: bar;
  display: grid; grid-template-columns: auto 1fr 1fr auto; align-items: center; gap: 2px;
  padding-top: 4px;
}
.msc-post__react { position: relative; display: flex; align-items: center; border-radius: 10px; }
.msc-post__like, .msc-post__act {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  height: 38px; padding: 0 10px; border-radius: 10px;
  font-size: 13px; font-weight: 600; color: var(--msc-post-muted);
  transition: background-color .2s, color .2s;
  & svg { width: 20px; height: 20px; }
  &:hover { background: var(--msc-post-hover); color: var(--msc-post-ink); }
  &:active { background: color-mix(in oklch, var(--msc-post-ink) 9%, transparent); }
}
.msc-post__like { padding-right: 6px; border-radius: 10px 4px 4px 10px; min-width: 76px; justify-content: flex-start; }
.msc-post__ico { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; }
.msc-post__like[aria-pressed="true"] {
  color: color-mix(in oklch, var(--msc-post-r) 78%, var(--msc-post-ink));
  & .msc-post__ico { color: oklch(1 0 0); background: var(--msc-post-r); }
  & .msc-post__ico svg { width: 14px; height: 14px; stroke-width: 2.4; }
  &.is-pop .msc-post__ico { animation: msc-post-pop .5s var(--msc-post-spring); }
}
.msc-post__more {
  display: grid; place-items: center; width: 26px; height: 38px; border-radius: 4px 10px 10px 4px;
  color: var(--msc-post-faint);
  transition: background-color .2s, color .2s;
  & svg { width: 16px; height: 16px; transition: rotate .3s var(--msc-post-ease); }
  &:hover, &[aria-expanded="true"] { background: var(--msc-post-hover); color: var(--msc-post-ink); }
  &[aria-expanded="true"] svg { rotate: 180deg; }
}
.msc-post__act[aria-pressed="true"][data-act="repost"] { color: oklch(0.55 0.13 155); }
.msc-post__act[aria-expanded="true"] { color: var(--msc-post-ink); background: var(--msc-post-hover); }
.msc-post__save {
  width: 38px; padding: 0; justify-self: end;
  &[aria-pressed="true"] { color: var(--msc-post-accent); }
  &[aria-pressed="true"] path { fill: currentColor; }
  &.is-pop svg { animation: msc-post-pop .5s var(--msc-post-spring); }
}

/* ---------- the dock ---------- */
.msc-post__dock {
  position: absolute; left: -4px; bottom: calc(100% + 6px); z-index: 5;
  display: flex; gap: 3px; padding: 5px;
  border-radius: 999px;
  background: var(--msc-post-paper);
  box-shadow: 0 0 0 1px var(--msc-post-line), 0 14px 32px -12px color-mix(in oklch, var(--msc-post-ink) 38%, transparent);
  transform-origin: 30px 100%;
  opacity: 0; scale: .7; translate: 0 6px; visibility: hidden; pointer-events: none;
  transition: opacity .16s, scale .3s var(--msc-post-ease), translate .3s var(--msc-post-ease), visibility 0s .3s;
  & button {
    --msc-post-s: 1;
    position: relative; display: grid; place-items: center;
    width: 36px; height: 36px; border-radius: 50%;
    transform-origin: 50% 100%;
    scale: var(--msc-post-s);
    transition: scale .2s cubic-bezier(.2, .9, .3, 1.2);
    &:focus-visible { outline: none; --msc-post-s: 1.32; }
    &:focus-visible .msc-post__glyph { box-shadow: 0 0 0 2px var(--msc-post-paper), 0 0 0 4px var(--msc-post-ring); }
  }
}
.msc-post__glyph {
  display: grid; place-items: center; width: 100%; height: 100%; border-radius: 50%;
  color: oklch(1 0 0);
  background: radial-gradient(circle at 35% 28%, color-mix(in oklch, var(--msc-post-r) 70%, oklch(1 0 0)), var(--msc-post-r) 62%);
  box-shadow: inset 0 -2px 0 color-mix(in oklch, var(--msc-post-r) 80%, oklch(0 0 0));
  & svg { width: 20px; height: 20px; stroke-width: 2.3; }
}
.msc-post__dock [aria-checked="true"]::after {
  content: ""; position: absolute; left: 50%; bottom: -5px; width: 4px; height: 4px; margin-left: -2px; border-radius: 50%;
  background: var(--msc-post-r);
}
.msc-post__tip {
  position: absolute; left: 50%; bottom: calc(100% + 6px);
  padding: 3px 7px; border-radius: 6px;
  font-size: 10.5px; font-weight: 650; letter-spacing: .02em; white-space: nowrap;
  color: var(--msc-post-paper); background: var(--msc-post-ink);
  translate: -50% 3px; scale: calc(1 / var(--msc-post-s));
  transform-origin: 50% 100%;
  opacity: 0; pointer-events: none;
  transition: opacity .15s, translate .2s var(--msc-post-ease);
}
.msc-post__dock button:is(:hover, :focus-visible) .msc-post__tip { opacity: 1; translate: -50% 0; }
.msc-post__react[data-open] .msc-post__dock {
  opacity: 1; scale: 1; translate: 0 0; visibility: visible; pointer-events: auto;
  transition: opacity .14s, scale .42s var(--msc-post-spring), translate .42s var(--msc-post-spring), visibility 0s;
  & .msc-post__glyph { animation: msc-post-rise .46s var(--msc-post-spring) both; animation-delay: calc(var(--i) * 26ms); }
}
.msc-post__fly {
  position: absolute; z-index: 9; pointer-events: none;
  display: grid; place-items: center; border-radius: 50%;
  color: oklch(1 0 0); background: var(--msc-post-r);
  & svg { width: 56%; height: 56%; stroke-width: 2.3; }
}

/* ---------- reply ---------- */
.msc-post__reply {
  grid-area: reply;
  position: relative;
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px;
  padding: 8px 0 6px;
  transition: opacity .3s var(--msc-post-ease), translate .4s var(--msc-post-ease), display .3s allow-discrete;
  &[hidden] { display: none; opacity: 0; translate: 0 -6px; }
}
@starting-style {
  .msc-post__reply { opacity: 0; translate: 0 -6px; }
}
.msc-post__me {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%;
  font-size: 10.5px; font-weight: 700; color: oklch(0.35 0.07 160); background: oklch(0.9 0.05 160);
}
.msc-post__input {
  width: 100%; min-width: 0; height: 36px; padding: 0 12px; border-radius: 18px;
  border: 0; background: var(--msc-post-hover);
  box-shadow: inset 0 0 0 1px transparent;
  transition: box-shadow .2s, background-color .2s;
  &::placeholder { color: var(--msc-post-faint); }
  &:focus { outline: none; background: var(--msc-post-paper); box-shadow: inset 0 0 0 1.5px var(--msc-post-ring); }
}
.msc-post__send {
  height: 32px; padding: 0 13px; border-radius: 16px;
  font-size: 12.5px; font-weight: 650; color: var(--msc-post-paper); background: var(--msc-post-ink);
  transition: opacity .2s, background-color .2s, scale .25s var(--msc-post-spring);
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--msc-post-ink) 82%, var(--msc-post-accent)); }
  &:active:not(:disabled) { scale: .95; }
  &:disabled { opacity: .32; cursor: not-allowed; }
}
.msc-post__posted {
  position: absolute; right: 0; top: calc(100% - 4px);
  display: inline-flex; align-items: center; gap: 4px;
  font-size: 11.5px; font-weight: 600; color: oklch(0.5 0.12 155);
  & svg { width: 14px; height: 14px; stroke-width: 2.4; }
  transition: opacity .25s, display .25s allow-discrete;
  &[hidden] { display: none; opacity: 0; }
}
.msc-post:has(.msc-post__posted:not([hidden])) .msc-post__reply { margin-bottom: 14px; }

/* ---------- breakdown panel ---------- */
.msc-post__panel {
  position: absolute; left: 10px; right: 10px; bottom: 54px; z-index: 6;
  padding: 10px 6px 8px 14px;
  border-radius: 14px;
  background: var(--msc-post-paper);
  box-shadow: 0 0 0 1px var(--msc-post-line), 0 18px 40px -14px color-mix(in oklch, var(--msc-post-ink) 40%, transparent);
  transform-origin: 20% 100%;
  transition: opacity .2s, scale .35s var(--msc-post-spring), translate .35s var(--msc-post-spring), display .35s allow-discrete;
  &[hidden] { display: none; opacity: 0; scale: .96; translate: 0 6px; }
}
@starting-style {
  .msc-post__panel { opacity: 0; scale: .96; translate: 0 6px; }
}
.msc-post__ph { display: flex; align-items: center; justify-content: space-between; padding-right: 2px; margin-bottom: 4px; }
.msc-post__pt {
  font-size: 13px; font-weight: 700; letter-spacing: -.01em;
  &:focus { outline: none; }
  & span { margin-left: 4px; font-weight: 500; color: var(--msc-post-faint); font-variant-numeric: tabular-nums; }
}
.msc-post__x {
  display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--msc-post-faint);
  &:hover { background: var(--msc-post-hover); color: var(--msc-post-ink); }
  & svg { width: 16px; height: 16px; }
}
.msc-post__rows { list-style: none; padding: 0 8px 0 0; display: grid; gap: 2px; }
.msc-post__row {
  display: grid; grid-template-columns: 20px minmax(0, 1fr) auto; grid-template-areas: "g name n" "g bar bar";
  column-gap: 9px; align-items: center; padding: 4px 0;
  font-size: 12.5px;
  & .msc-post__badge { grid-area: g; box-shadow: none; }
  & b { grid-area: name; font-weight: 560; }
  & em { margin-left: 5px; font-style: normal; font-size: 11px; color: var(--msc-post-faint); }
  & .msc-post__n { grid-area: n; font-variant-numeric: tabular-nums; color: var(--msc-post-muted); }
  & i {
    grid-area: bar; height: 3px; margin-top: 3px; border-radius: 2px;
    background: color-mix(in oklch, var(--msc-post-ink) 7%, transparent);
    overflow: hidden;
  }
  & i::before {
    content: ""; display: block; height: 100%; width: 100%; border-radius: inherit;
    background: var(--msc-post-r);
    transform-origin: 0 50%; scale: var(--msc-post-w, 0) 1;
    animation: msc-post-bar .7s var(--msc-post-ease) both; animation-delay: calc(var(--i) * 40ms + 80ms);
  }
}

/* ---------- container responses ---------- */
@container (max-width: 340px) {
  .msc-post { padding-inline: 12px; }
  .msc-post__act span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .msc-post__act { padding: 0; }
  .msc-post__counts [data-count="reposts"] { display: none; }
  .msc-post__meta span:nth-child(2) { display: none; }
}
@container (min-width: 440px) {
  .msc-post { padding: 18px 18px 10px; }
  .msc-post__head { grid-template-columns: auto minmax(0, 1fr); column-gap: 12px; }
  .msc-post__av { width: 44px; height: 44px; }
  .msc-post__tiles { gap: 6px; }
  .msc-post__tile span { font-size: 11px; }
}

@keyframes msc-post-rise { from { opacity: 0; translate: 0 12px; scale: .5; } }
@keyframes msc-post-pop { 0% { scale: .5; } 100% { scale: 1; } }
@keyframes msc-post-in { from { scale: 0; } }
@keyframes msc-post-bar { from { scale: 0 1; } }
@keyframes msc-post-burst { 0% { opacity: 0; } 12% { opacity: 1; } 70% { opacity: 1; } 100% { opacity: 0; } }
@keyframes msc-post-heart { 0% { scale: 0; rotate: -14deg; } 60% { scale: 1; rotate: 0deg; } 100% { scale: 1.08; translate: 0 -10px; } }
@keyframes msc-post-spark { 0% { translate: 0 0; scale: 1; opacity: 1; } 100% { translate: 0 -44px; scale: .2; opacity: 0; } }

@media (prefers-reduced-motion: reduce) {
  .msc-post__dock, .msc-post__react[data-open] .msc-post__dock { scale: 1; translate: 0 0; transition: opacity .15s linear, visibility 0s; }
  .msc-post__react[data-open] .msc-post__dock .msc-post__glyph,
  .msc-post__like[aria-pressed="true"].is-pop .msc-post__ico,
  .msc-post__save.is-pop svg,
  .msc-post__badge.is-in,
  .msc-post__row i::before { animation: none; }
  .msc-post__dock button { transition: none; }
  .msc-post__dock button:focus-visible { --msc-post-s: 1; }
  .msc-post__burst.is-on { animation: msc-post-burst 1s linear both; }
  .msc-post__burst.is-on svg, .msc-post__burst.is-on i { animation: none; }
  .msc-post__burst i { display: none; }
  .msc-post__reply, .msc-post__panel { transition: opacity .15s linear, display .15s allow-discrete; translate: 0 0; scale: 1; }
  .msc-post__more svg { transition: none; }
}

js:
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const fmt = (n) => n.toLocaleString('en-US');

/* Counts from everyone except you. Total 1,284 = 712 + 341 + 128 + 64 + 27 + 12. */
const ORDER = ['like', 'love', 'celebrate', 'insight', 'funny', 'curious'];
const BASE = { like: 712, love: 341, celebrate: 128, insight: 64, funny: 27, curious: 12 };
const LABEL = { like: 'Like', love: 'Love', celebrate: 'Celebrate', insight: 'Insightful', funny: 'Funny', curious: 'Curious' };
const NAMED = 'Tomás Reyes';
let mine = null, comments = 86, reposts = 24;

const react = $('.msc-post__react');
const like = $('.msc-post__like');
const more = $('.msc-post__more');
const dock = $('.msc-post__dock');
const items = $$('[role="menuitemradio"]', dock);
const sum = $('.msc-post__sum');
const panel = $('.msc-post__panel');
const live = root.querySelector('p.msc-post__sr[aria-live]');
const reply = $('.msc-post__reply');
const input = $('.msc-post__input');
const send = $('.msc-post__send');
const posted = $('.msc-post__posted');
const media = $('.msc-post__media');
const burst = $('.msc-post__burst');
const THUMB = $('.msc-post__ico').innerHTML;
const GLYPH = Object.fromEntries(items.map((b) => [b.dataset.r, $('svg', b).outerHTML]));

const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const count = (r) => BASE[r] + (mine === r ? 1 : 0);
const total = () => ORDER.reduce((a, r) => a + count(r), 0);
const ranked = () => ORDER.slice().sort((a, b) => count(b) - count(a) || ORDER.indexOf(a) - ORDER.indexOf(b));
const badge = (r) => '<span class="msc-post__badge" data-r="' + r + '">' + GLYPH[r] + '</span>';

/* ---------- summary + panel ---------- */
let lastTop = '';
const paintSummary = () => {
  const top = ranked().slice(0, 3);
  const key = top.join();
  const stack = $('.msc-post__stack');
  if (key !== lastTop) {
    const prev = lastTop.split(',');
    stack.innerHTML = top.map(badge).join('');
    $$('.msc-post__badge', stack).forEach((b, i) => { if (lastTop && prev[i] !== top[i]) b.classList.add('is-in'); });
    lastTop = key;
  }
  const others = total() - 1 - (mine ? 1 : 0);
  $('.msc-post__who-reacted').textContent = (mine ? 'You, ' : '') + NAMED + ' and ' + fmt(others) + ' others';
  $('.msc-post__total').textContent = mine ? 'You and ' + fmt(total() - 1) + ' others' : fmt(total());
  sum.setAttribute('aria-label', fmt(total()) + ' reactions. Show breakdown');
  $('[data-count="comments"]').textContent = fmt(comments) + ' comments';
  $('[data-count="reposts"]').textContent = fmt(reposts) + ' reposts';
  if (!panel.hidden) paintPanel();
};
const paintPanel = () => {
  const r = ranked(), max = count(r[0]);
  $('.msc-post__ptotal').textContent = fmt(total());
  $('.msc-post__rows').innerHTML = r.map((k, i) =>
    '<li class="msc-post__row" data-r="' + k + '" style="--i:' + i + ';--msc-post-w:' + (count(k) / max).toFixed(3) + '">' +
    badge(k) + '<b>' + LABEL[k] + (mine === k ? '<em>incl. you</em>' : '') + '</b><span class="msc-post__n">' + fmt(count(k)) + '</span><i aria-hidden="true"></i></li>').join('');
};

/* ---------- reacting ---------- */
const fly = (fromEl, r) => {
  if (RM.matches || !fromEl) return;
  const rr = root.getBoundingClientRect(), a = fromEl.getBoundingClientRect(), b = $('.msc-post__ico').getBoundingClientRect();
  if (!a.width) return;
  const g = document.createElement('span');
  g.className = 'msc-post__fly';
  g.dataset.r = r;
  g.innerHTML = GLYPH[r];
  Object.assign(g.style, { left: a.left - rr.left + 'px', top: a.top - rr.top + 'px', width: a.width + 'px', height: a.height + 'px' });
  root.append(g);
  const dx = b.left + b.width / 2 - (a.left + a.width / 2), dy = b.top + b.height / 2 - (a.top + a.height / 2);
  const s = b.width / a.width;
  const anim = g.animate([
    { transform: 'translate(0,0) scale(1)' },
    { transform: 'translate(' + dx * 0.45 + 'px,' + (dy * 0.45 - 34) + 'px) scale(' + (1 + s) * 0.62 + ') rotate(-10deg)', offset: 0.45 },
    { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(' + s + ')' }
  ], { duration: 560, easing: 'cubic-bezier(.35,.6,.2,1)' });
  const done = () => g.remove();
  anim.finished.then(done, done);
  return anim;
};

const setReaction = (r, fromEl) => {
  const was = mine;
  mine = r === mine ? null : r;
  const paintButton = () => {
    like.setAttribute('aria-pressed', String(!!mine));
    if (mine) like.dataset.r = mine; else delete like.dataset.r;
    $('.msc-post__ico').innerHTML = mine ? GLYPH[mine] : THUMB;
    $('.msc-post__lbl').textContent = mine ? LABEL[mine] : 'Like';
    like.classList.remove('is-pop');
    if (mine) { void like.offsetWidth; like.classList.add('is-pop'); }
  };
  items.forEach((b) => b.setAttribute('aria-checked', String(b.dataset.r === mine)));
  const anim = mine && fromEl ? fly(fromEl, mine) : null;
  if (anim) later(470, paintButton); else paintButton();
  paintSummary();
  say(mine ? 'You reacted ' + LABEL[mine] : 'Reaction removed' + (was ? ' (' + LABEL[was] + ')' : ''));
};

/* ---------- dock open / close ---------- */
let open = false, tOpen = 0, tClose = 0, suppress = false;
const focusItem = (i) => {
  const k = (i + items.length) % items.length;
  items.forEach((b, j) => { b.tabIndex = j === k ? 0 : -1; });
  items[k].focus();
};
const openDock = (withFocus) => {
  clearTimeout(tClose);
  if (!open) {
    open = true;
    react.toggleAttribute('data-open', true);
    more.setAttribute('aria-expanded', 'true');
    closePanel(false);
  }
  if (withFocus) focusItem(Math.max(0, ORDER.indexOf(mine)));
};
const closeDock = (refocus) => {
  clearTimeout(tOpen);
  if (!open) return;
  open = false;
  react.removeAttribute('data-open');
  more.setAttribute('aria-expanded', 'false');
  items.forEach((b) => b.style.setProperty('--msc-post-s', 1));
  if (refocus) more.focus();
};

react.addEventListener('pointerenter', (e) => {
  if (e.pointerType !== 'mouse') return;
  clearTimeout(tClose);
  if (!open) tOpen = later(420, () => openDock(false));
});
react.addEventListener('pointerleave', (e) => {
  if (e.pointerType !== 'mouse') return;
  clearTimeout(tOpen);
  if (open && !react.contains(document.activeElement)) tClose = later(360, () => closeDock(false));
});

/* touch: long-press the button to open the dock instead of toggling Like */
let press = 0;
like.addEventListener('pointerdown', (e) => {
  if (e.pointerType === 'mouse') return;
  press = later(430, () => { suppress = true; openDock(false); });
});
['pointerup', 'pointercancel', 'pointerleave'].forEach((t) => like.addEventListener(t, () => clearTimeout(press)));
like.addEventListener('contextmenu', (e) => { if (open) e.preventDefault(); });
like.addEventListener('click', () => {
  if (suppress) { suppress = false; return; }
  clearTimeout(tOpen);
  closeDock(false);
  setReaction(mine || 'like', null);
});
more.addEventListener('click', () => (open ? closeDock(true) : openDock(true)));
more.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowUp' || e.key === 'ArrowDown') { e.preventDefault(); openDock(true); }
});

/* magnification: each glyph scales by a gaussian of its distance to the pointer */
dock.addEventListener('pointermove', (e) => {
  if (RM.matches || e.pointerType !== 'mouse') return;
  for (const b of items) {
    const r = b.getBoundingClientRect();
    const d = e.clientX - (r.left + r.width / 2);
    b.style.setProperty('--msc-post-s', (1 + 0.42 * Math.exp(-(d * d) / (2 * 30 * 30))).toFixed(3));
  }
});
dock.addEventListener('pointerleave', () => items.forEach((b) => b.style.setProperty('--msc-post-s', 1)));
dock.addEventListener('click', (e) => {
  const b = e.target.closest('[role="menuitemradio"]');
  if (!b) return;
  const fromEl = $('.msc-post__glyph', b);
  const keyboard = e.detail === 0;
  setReaction(b.dataset.r, fromEl);
  later(RM.matches ? 0 : 160, () => closeDock(false));
  if (keyboard) like.focus();
});
dock.addEventListener('keydown', (e) => {
  const k = items.indexOf(document.activeElement);
  if (k < 0) return;
  const to = { ArrowRight: k + 1, ArrowLeft: k - 1, ArrowDown: k + 1, ArrowUp: k - 1, Home: 0, End: items.length - 1 }[e.key];
  if (to !== undefined) { e.preventDefault(); focusItem(to); }
  else if (e.key === 'Tab') closeDock(false);
});
react.addEventListener('focusout', (e) => {
  if (open && !react.contains(e.relatedTarget)) tClose = later(120, () => { if (!react.contains(document.activeElement)) closeDock(false); });
});

/* ---------- breakdown panel ---------- */
const openPanel = () => {
  closeDock(false);
  panel.hidden = false;
  sum.setAttribute('aria-expanded', 'true');
  paintPanel();
  $('.msc-post__pt').focus({ preventScroll: true });
};
function closePanel(refocus) {
  if (panel.hidden) return;
  panel.hidden = true;
  sum.setAttribute('aria-expanded', 'false');
  if (refocus) sum.focus();
}
sum.addEventListener('click', () => (panel.hidden ? openPanel() : closePanel(true)));
$('.msc-post__x').addEventListener('click', () => closePanel(true));

/* ---------- other actions ---------- */
root.addEventListener('click', (e) => {
  const b = e.target.closest('.msc-post__act');
  if (!b) return;
  const act = b.dataset.act;
  if (act === 'repost') {
    const on = b.getAttribute('aria-pressed') !== 'true';
    b.setAttribute('aria-pressed', String(on));
    reposts += on ? 1 : -1;
    paintSummary();
    say(on ? 'Reposted to your followers' : 'Repost removed');
  } else if (act === 'save') {
    const on = b.getAttribute('aria-pressed') !== 'true';
    b.setAttribute('aria-pressed', String(on));
    b.setAttribute('aria-label', on ? 'Saved' : 'Save post');
    b.classList.remove('is-pop');
    if (on) { void b.offsetWidth; b.classList.add('is-pop'); }
    say(on ? 'Saved to Collections' : 'Removed from Collections');
  } else if (act === 'comment') {
    const on = reply.hidden;
    reply.hidden = !on;
    b.setAttribute('aria-expanded', String(on));
    if (on) input.focus();
  }
});
input.addEventListener('input', () => { send.disabled = !input.value.trim(); });
reply.addEventListener('submit', (e) => {
  e.preventDefault();
  if (!input.value.trim()) return;
  comments += 1;
  input.value = '';
  send.disabled = true;
  paintSummary();
  posted.hidden = false;
  say('Reply posted. ' + comments + ' comments');
  later(2400, () => { posted.hidden = true; });
});

/* double-click the photos to love them */
media.addEventListener('dblclick', (e) => {
  const r = media.getBoundingClientRect();
  burst.style.setProperty('--x', e.clientX - r.left + 'px');
  burst.style.setProperty('--y', e.clientY - r.top + 'px');
  burst.classList.remove('is-on');
  void burst.offsetWidth;
  burst.classList.add('is-on');
  if (mine !== 'love') setReaction('love', $('svg', burst));
});

/* ---------- global keys + outside clicks, all on root ---------- */
root.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  if (open) { e.preventDefault(); closeDock(true); }
  else if (!panel.hidden) { e.preventDefault(); closePanel(true); }
  else if (!reply.hidden && reply.contains(document.activeElement)) {
    e.preventDefault(); reply.hidden = true;
    const c = $('[data-act="comment"]'); c.setAttribute('aria-expanded', 'false'); c.focus();
  }
});
root.addEventListener('pointerdown', (e) => {
  if (open && !react.contains(e.target)) closeDock(false);
  if (!panel.hidden && !panel.contains(e.target) && !sum.contains(e.target)) closePanel(false);
});

paintSummary();

css:
@property --msc-compose-p {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}
@property --msc-compose-tone {
  syntax: "<color>";
  inherits: true;
  initial-value: oklch(0.76 0.16 55);
}

/* Re-theme with --msc-compose-bg, -ink, -accent and -tag. */
.msc-compose {
  --msc-compose-bg: oklch(0.215 0.007 75);
  --msc-compose-ink: oklch(0.95 0.006 85);
  --msc-compose-accent: oklch(0.77 0.15 58);
  --msc-compose-tag: oklch(0.82 0.1 165);
  --msc-compose-bad: oklch(0.7 0.17 25);

  --msc-compose-raise: color-mix(in oklch, var(--msc-compose-ink) 6%, var(--msc-compose-bg));
  --msc-compose-pop: color-mix(in oklch, var(--msc-compose-ink) 9%, var(--msc-compose-bg));
  --msc-compose-line: color-mix(in oklch, var(--msc-compose-ink) 12%, transparent);
  --msc-compose-muted: color-mix(in oklch, var(--msc-compose-ink) 66%, var(--msc-compose-bg));
  --msc-compose-faint: color-mix(in oklch, var(--msc-compose-ink) 44%, var(--msc-compose-bg));
  --msc-compose-hover: color-mix(in oklch, var(--msc-compose-ink) 7%, transparent);
  --msc-compose-ring: color-mix(in oklch, var(--msc-compose-accent) 70%, transparent);
  --msc-compose-ease: cubic-bezier(.22, 1, .36, 1);
  --msc-compose-spring: linear(0, 0.09 4%, 0.35 9%, 0.73 17%, 1 25%, 1.08 32%, 1.06 40%, 1.01 52%, 0.995 64%, 1);
  --msc-compose-font: 400 15px/24px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 368px;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto 1fr auto auto;
  grid-template-areas: "head" "field" "err" "foot";
  border-radius: 18px;
  overflow: clip;
  color: var(--msc-compose-ink);
  background:
    radial-gradient(120% 60% at 100% 0%, color-mix(in oklch, var(--msc-compose-accent) 7%, transparent), transparent 60%),
    var(--msc-compose-bg);
  box-shadow: inset 0 0 0 1px var(--msc-compose-line), 0 24px 48px -28px oklch(0 0 0 / .6);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  color-scheme: dark;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .msc-compose { --msc-compose-spring: cubic-bezier(.34, 1.45, .5, 1); }
}
:where(.msc-compose) *, :where(.msc-compose) *::before, :where(.msc-compose) *::after { box-sizing: border-box; }
:where(.msc-compose) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.msc-compose) :focus-visible { outline: 2px solid var(--msc-compose-ring); outline-offset: 2px; }
.msc-compose svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.msc-compose) :is(p, ul) { margin: 0; }
.msc-compose__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- header + audience menu ---------- */
.msc-compose__head {
  grid-area: head;
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; column-gap: 10px;
  padding: 14px 16px 4px;
}
.msc-compose__av {
  display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%;
  font-size: 12.5px; font-weight: 700; letter-spacing: .02em;
  color: oklch(0.25 0.04 60); background: linear-gradient(140deg, oklch(0.88 0.09 75), var(--msc-compose-accent));
}
.msc-compose__name { font-size: 13.5px; font-weight: 650; letter-spacing: -.01em; line-height: 1.2; }
.msc-compose__aud { position: relative; justify-self: start; }
.msc-compose__audbtn {
  display: inline-flex; align-items: center; gap: 4px; margin: 4px 0 0; padding: 2px 7px 2px 6px; border-radius: 999px;
  font-size: 12px; font-weight: 600; color: var(--msc-compose-accent);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--msc-compose-accent) 35%, transparent);
  transition: background-color .2s;
  & svg { width: 14px; height: 14px; }
  & .msc-compose__chev { width: 13px; height: 13px; transition: rotate .3s var(--msc-compose-ease); }
  &:hover, &[aria-expanded="true"] { background: color-mix(in oklch, var(--msc-compose-accent) 12%, transparent); }
  &[aria-expanded="true"] .msc-compose__chev { rotate: 180deg; }
}
.msc-compose__menu {
  position: absolute; left: 0; top: calc(100% + 6px); z-index: 12;
  display: grid; width: max-content; min-width: 200px; padding: 5px; border-radius: 12px;
  background: var(--msc-compose-pop);
  box-shadow: inset 0 0 0 1px var(--msc-compose-line), 0 18px 36px -12px oklch(0 0 0 / .7);
  transform-origin: 20px 0;
  opacity: 0; scale: .94; translate: 0 -4px; visibility: hidden;
  transition: opacity .15s, scale .3s var(--msc-compose-ease), translate .3s var(--msc-compose-ease), visibility 0s .3s;
  & button {
    display: grid; grid-template-columns: 18px minmax(0, 1fr) 14px; align-items: center; gap: 10px;
    padding: 7px 9px; border-radius: 8px; text-align: left;
    &:hover, &:focus-visible { background: var(--msc-compose-hover); outline: none; }
    & svg { width: 18px; height: 18px; color: var(--msc-compose-muted); }
    & b { display: block; font-size: 13px; font-weight: 600; }
    & small { display: block; font-size: 11.5px; color: var(--msc-compose-faint); font-variant-numeric: tabular-nums; }
    &::after { content: ""; width: 8px; height: 8px; border-radius: 50%; justify-self: center; }
    &[aria-checked="true"]::after { background: var(--msc-compose-accent); }
  }
}
.msc-compose__aud[data-open] .msc-compose__menu {
  opacity: 1; scale: 1; translate: 0 0; visibility: visible;
  transition: opacity .12s, scale .38s var(--msc-compose-spring), translate .38s var(--msc-compose-spring), visibility 0s;
}

/* ---------- the field: textarea over a mirrored highlight layer ---------- */
.msc-compose__field {
  grid-area: field;
  position: relative;
  margin: 6px 10px 0;
  min-height: 0;
}
.msc-compose__mirror, .msc-compose__ta {
  margin: 0; border: 0;
  padding: 6px 8px 10px;
  font: var(--msc-compose-font);
  letter-spacing: 0; word-spacing: 0; tab-size: 4;
  white-space: pre-wrap; overflow-wrap: break-word; word-break: normal;
  scrollbar-width: none;
}
.msc-compose__mirror {
  position: absolute; inset: 0;
  overflow: hidden;
  color: var(--msc-compose-ink);
  pointer-events: none;
  & mark {
    color: inherit; background: none; border-radius: 4px;
    transition: background-color .25s, box-shadow .25s, color .25s;
  }
  & mark[data-k="ok"] {
    color: var(--msc-compose-accent);
    background: color-mix(in oklch, var(--msc-compose-accent) 15%, transparent);
    box-shadow: 0 0 0 2px color-mix(in oklch, var(--msc-compose-accent) 15%, transparent);
  }
  & mark[data-k="tag"] { color: var(--msc-compose-tag); }
  & mark[data-k="q"] {
    background: var(--msc-compose-hover);
    box-shadow: 0 0 0 2px var(--msc-compose-hover);
  }
  & mark[data-k="bad"] {
    text-decoration: underline wavy color-mix(in oklch, var(--msc-compose-bad) 85%, transparent);
    text-decoration-thickness: 1.5px; text-underline-offset: 4px; text-decoration-skip-ink: none;
  }
  & mark.is-new { animation: msc-compose-chip .6s var(--msc-compose-ease); }
}
.msc-compose__caret { display: inline-block; width: 0; height: 1lh; vertical-align: top; }
.msc-compose__ta {
  position: relative; z-index: 1; display: block;
  width: 100%; min-height: 112px; max-height: 216px;
  resize: none; overflow-y: auto;
  background: transparent;
  color: transparent;
  caret-color: var(--msc-compose-accent);
  border-radius: 10px;
  &::placeholder { color: var(--msc-compose-faint); }
  &::selection { color: transparent; background: color-mix(in oklch, var(--msc-compose-accent) 32%, transparent); }
  &:focus { outline: none; }
  &:focus-visible { outline: none; }
  &[readonly] { cursor: default; }
}
.msc-compose__field:has(.msc-compose__ta:focus-visible)::after {
  content: ""; position: absolute; inset: -2px; border-radius: 12px; pointer-events: none;
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--msc-compose-accent) 30%, transparent);
}
.msc-compose:has(.msc-compose__ta[readonly]) .msc-compose__mirror { opacity: .5; transition: opacity .3s; }

.msc-compose__err {
  grid-area: err;
  display: flex; align-items: flex-start; gap: 7px;
  margin: 2px 16px 6px; padding: 8px 10px; border-radius: 9px;
  font-size: 12.5px; line-height: 1.4; text-wrap: pretty;
  color: color-mix(in oklch, var(--msc-compose-bad) 80%, var(--msc-compose-ink));
  background: color-mix(in oklch, var(--msc-compose-bad) 13%, transparent);
