}
.msc-compose__ring:is([data-state="warn"], [data-state="over"]) .msc-compose__left { opacity: 1; scale: 1; }
.msc-compose__ring[data-state="over"] .msc-compose__left { color: var(--msc-compose-bad); }

.msc-compose__post {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  min-width: 76px; height: 36px; padding: 0 16px; border-radius: 999px;
