}
.msc-compose__ph {
  padding: 4px 8px 6px;
  font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase;
  color: var(--msc-compose-faint);
}
.msc-compose__list { list-style: none; padding: 0; display: grid; gap: 1px; max-height: 196px; overflow-y: auto; scrollbar-width: thin; overscroll-behavior: contain; }
.msc-compose__opt {
  display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; grid-template-areas: "av n meta" "av h meta";
  align-items: center; column-gap: 10px;
