    & u { color: var(--msc-compose-tag); }
  }
}
.msc-compose__none {
  padding: 10px 10px 12px; font-size: 12.5px; color: var(--msc-compose-muted); text-wrap: pretty;
  & b { color: var(--msc-compose-ink); font-weight: 600; }
}
.msc-compose__skel {
