.msc-compose__dt { font-size: 15px; font-weight: 650; letter-spacing: -.01em; text-wrap: balance; &:focus { outline: none; } }
.msc-compose__dd { max-width: 32ch; font-size: 12.5px; color: var(--msc-compose-muted); text-wrap: pretty; }
.msc-compose__again {
  margin-top: 10px; padding: 7px 14px; border-radius: 999px; font-size: 12.5px; font-weight: 600;
