}

@container (max-width: 330px) {
  .msc-compose__head { padding-inline: 12px; }
  .msc-compose__field { margin-inline: 6px; }
  .msc-compose { --msc-compose-font: 400 14.5px/23px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
}
@container (min-width: 460px) {
