  .msc-compose__field { margin-inline: 14px; }
  .msc-compose__foot { padding-inline: 14px 16px; }
  .msc-compose { --msc-compose-font: 400 16px/25px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
}

@keyframes msc-compose-spin { to { rotate: 1turn; } }
