@keyframes msc-compose-popin { from { scale: 0; } }
@keyframes msc-compose-draw { to { stroke-dashoffset: 0; } }

@media (prefers-reduced-motion: reduce) {
  .msc-compose__menu, .msc-compose__aud[data-open] .msc-compose__menu { scale: 1; translate: 0 0; transition: opacity .15s linear, visibility 0s; }
