  .msc-compose__opt, .msc-compose__mirror mark.is-new, .msc-compose__tick { animation: none; }
  .msc-compose__tick svg { animation: none; stroke-dashoffset: 0; }
  .msc-compose__skel i { animation: none; }
  .msc-compose__spin { animation-duration: 2s; }
  .msc-compose__ring { transition: --msc-compose-tone .2s linear, opacity .2s linear; }
}

