const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const UID = 'msc-compose-' + Math.random().toString(36).slice(2, 7);
const LIMIT = 280;

const PEOPLE = [
  { h: 'ines.k', n: 'Inês Carvalho', r: 'Design systems', hue: 30, you: true },
  { h: 'tomas.f', n: 'Tomás Ferreira', r: 'Payments', hue: 210 },
  { h: 'tove', n: 'Tove Lindqvist', r: 'Research', hue: 150, you: true },
  { h: 'tobi.a', n: 'Tobi Adeyemi', r: 'Growth', hue: 80 },
  { h: 'priya.r', n: 'Priya Raman', r: 'Infrastructure', hue: 330 },
  { h: 'kenji', n: 'Kenji Watanabe', r: 'Mobile', hue: 260 },
  { h: 'amaru.q', n: 'Amaru Quispe', r: 'Data', hue: 110, you: true },
  { h: 'noor', n: 'Noor Haddad', r: 'Product', hue: 0 }
];
const TAGS = [
  { t: 'launchweek', n: 1240 }, { t: 'pricing', n: 318 }, { t: 'designsystems', n: 906 },
  { t: 'accessibility', n: 512 }, { t: 'shipit', n: 2204 }, { t: 'research', n: 377 }, { t: 'perf', n: 145 }
];
const HANDLES = new Set(PEOPLE.map((p) => p.h));
const SEED = 'Pricing page v3 is live for 10% of traffic #launchweek. Huge thanks to @ines.k for the plan cards and @to';

const ta = $('.msc-compose__ta');
const mirror = $('.msc-compose__mirror');
const pop = $('.msc-compose__pop');
const list = $('.msc-compose__list');
const head = $('.msc-compose__ph');
const ring = $('.msc-compose__ring');
const left = $('.msc-compose__left');
const post = $('.msc-compose__post');
const err = $('.msc-compose__err');
const done = $('.msc-compose__done');
const live = $('.msc-compose__sr');
const aud = $('.msc-compose__aud');
const audBtn = $('.msc-compose__audbtn');
const audItems = $$('[role="menuitemradio"]', aud);
const tools = $$('.msc-compose__tools button');

list.id = UID + '-list';
ta.setAttribute('aria-controls', list.id);

let act = null, dismissed = -1, options = [], cur = 0, warmed = false, loading = false, busy = false, fresh = -1, audience = 'Everyone';
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const esc = (t) => t.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const len = () => [...ta.value].length;

/* ---------- tokens ---------- */
const TOKEN = /(^|[^\w@#])([@#])([A-Za-z0-9_]+(?:\.[A-Za-z0-9_]+)*)/g;
const tokens = (v) => {
  const out = [];
  for (const m of v.matchAll(TOKEN)) {
    const start = m.index + m[1].length, text = m[2] + m[3];
    out.push({ start, end: start + text.length, sigil: m[2], word: m[3], text });
  }
  return out;
};
const activeToken = () => {
  if (ta.selectionStart !== ta.selectionEnd) return null;
  const caret = ta.selectionEnd, before = ta.value.slice(0, caret);
  const m = /(^|[^\w@#])([@#])([A-Za-z0-9_.]*)$/.exec(before);
  if (!m || m[3].length > 24) return null;
  return { sigil: m[2], q: m[3], start: caret - m[3].length - 1, end: caret };
};
const kindOf = (t) => {
  if (t.sigil === '#') return 'tag';
  if (HANDLES.has(t.word.toLowerCase())) return 'ok';
  return act && act.start === t.start ? 'q' : 'bad';
};

/* ---------- the mirror: same box, same font, painted chips ---------- */
const MARK = '<span class="msc-compose__caret"></span>';
const render = () => {
  const v = ta.value;
  let html = '', pos = 0;
  const text = (to) => {
    if (act && act.start >= pos && act.start < to) html += esc(v.slice(pos, act.start)) + MARK + esc(v.slice(act.start, to));
    else html += esc(v.slice(pos, to));
    pos = to;
  };
  for (const t of tokens(v)) {
    text(t.start);
    if (act && act.start === t.start) html += MARK;
    html += '<mark data-k="' + kindOf(t) + '"' + (t.start === fresh ? ' class="is-new"' : '') + '>' + esc(t.text) + '</mark>';
    pos = t.end;
  }
  text(v.length);
  if (v.endsWith('\n') || !v) html += ' ';
  mirror.innerHTML = html;
  mirror.scrollTop = ta.scrollTop;
  fresh = -1;

  const n = len(), state = !n ? 'empty' : n > LIMIT ? 'over' : n >= LIMIT - 20 ? 'warn' : 'ok';
  ring.dataset.state = state;
  ring.style.setProperty('--msc-compose-p', (n / LIMIT * 100).toFixed(2));
  left.textContent = LIMIT - n;
  ring.setAttribute('aria-label', n > LIMIT ? (n - LIMIT) + ' characters over the 280 limit' : n + ' of 280 characters');
  post.disabled = busy || !ta.value.trim() || n > LIMIT;
  if (!err.hidden && !unknown().length) { err.hidden = true; ta.removeAttribute('aria-invalid'); }
};
const unknown = () => tokens(ta.value).filter((t) => t.sigil === '@' && !HANDLES.has(t.word.toLowerCase()));
const grow = () => {
  ta.style.height = 'auto';
  ta.style.height = Math.min(ta.scrollHeight, 216) + 'px';
  mirror.scrollTop = ta.scrollTop;
};

/* ---------- suggestions ---------- */
const rank = (q) => {
  q = q.toLowerCase().replace(/\.$/, '');
  if (!q) return PEOPLE.slice(0, 5);
  const score = (p) => p.h.startsWith(q) ? 0 : p.n.toLowerCase().split(' ').some((w) => w.startsWith(q)) ? 1 : (p.h + ' ' + p.n.toLowerCase()).includes(q) ? 2 : 9;
  return PEOPLE.map((p) => [score(p), p]).filter((x) => x[0] < 9).sort((a, b) => a[0] - b[0]).slice(0, 5).map((x) => x[1]);
};
const rankTags = (q) => {
  q = q.toLowerCase();
  const hits = TAGS.filter((t) => t.t.includes(q)).sort((a, b) => (b.t.startsWith(q) - a.t.startsWith(q)) || b.n - a.n).slice(0, 5);
  if (q && !TAGS.some((t) => t.t === q) && /^\w+$/.test(q)) hits.push({ t: q, n: 0, isNew: true });
  return hits;
};
const hl = (s, q) => {
  if (!q) return esc(s);
  const i = s.toLowerCase().indexOf(q.toLowerCase());
  return i < 0 ? esc(s) : esc(s.slice(0, i)) + '<u>' + esc(s.slice(i, i + q.length)) + '</u>' + esc(s.slice(i + q.length));
};
const paintOptions = () => {
  const q = act.q.replace(/\.$/, '');
  if (act.sigil === '@') {
    head.textContent = q ? 'People matching “' + q + '”' : 'Recent people';
    options = rank(act.q).map((p) => ({ value: p.h, label: p.n, html:
      '<span class="msc-compose__oav" style="--h:' + p.hue + '">' + p.n.split(' ').map((w) => w[0]).join('') + '</span>' +
      '<span class="msc-compose__on">' + hl(p.n, q) + '</span><span class="msc-compose__oh">@' + hl(p.h, q) + ' · ' + p.r + '</span>' +
      (p.you ? '<span class="msc-compose__om">Follows you</span>' : '') }));
  } else {
    head.textContent = 'Topics';
    options = rankTags(act.q).map((t) => ({ value: t.t, label: '#' + t.t, kind: 'tag', html:
      '<span class="msc-compose__oav" aria-hidden="true">#</span><span class="msc-compose__on">' + hl(t.t, q) + '</span>' +
      '<span class="msc-compose__oh">' + (t.isNew ? 'New topic' : t.n.toLocaleString('en-US') + ' posts') + '</span>' }));
  }
  cur = Math.min(cur, Math.max(0, options.length - 1));
  if (!options.length) {
    list.innerHTML = '<li class="msc-compose__none" role="presentation">No one matches <b>@' + esc(act.q) + '</b> in Fieldnote. Mentions only reach people in your workspace.</li>';
    ta.removeAttribute('aria-activedescendant');
  } else {
    list.innerHTML = options.map((o, i) => '<li class="msc-compose__opt" role="option" id="' + UID + '-o' + i + '" data-i="' + i + '"' +
      (o.kind ? ' data-kind="tag"' : '') + ' aria-selected="' + (i === cur) + '" style="--i:' + i + '">' + o.html + '</li>').join('');
    ta.setAttribute('aria-activedescendant', UID + '-o' + cur);
  }
  if (document.activeElement === ta) say(options.length ? options.length + (act.sigil === '@' ? ' people' : ' topics') + ' found. Up and down to choose, Enter to insert.' : 'No matches');
};
const skeleton = () => {
  head.textContent = 'Searching people…';
  list.innerHTML = '<li class="msc-compose__skel" role="presentation"><i></i><span><i></i><i></i></span></li>'.repeat(3);
  ta.removeAttribute('aria-activedescendant');
};
const place = () => {
  const m = $('.msc-compose__caret', mirror);
  if (!m || pop.hidden) return;
  const rr = root.getBoundingClientRect(), mr = m.getBoundingClientRect();
  const pw = pop.offsetWidth, ph = pop.offsetHeight;
  const x = Math.max(10, Math.min(mr.left - rr.left - 16, rr.width - pw - 10));
  let y = mr.bottom - rr.top + 6, above = false;
  if (y + ph > rr.height - 8 && mr.top - rr.top - ph - 6 > 8) { y = mr.top - rr.top - ph - 6; above = true; }
  pop.style.setProperty('--x', x + 'px');
  pop.style.setProperty('--y', y + 'px');
  pop.toggleAttribute('data-above', above);
};
const showList = () => {
  const opening = pop.hidden;
  pop.hidden = false;
  if (act.sigil === '@' && !warmed) {
    warmed = true; loading = true; skeleton();
    later(320, () => { loading = false; if (act && !pop.hidden) { paintOptions(); place(); } });
  } else if (!loading) paintOptions();
  if (opening) cur = 0;
  place();
};
const hideList = () => {
  if (pop.hidden) return;
  pop.hidden = true;
  ta.removeAttribute('aria-activedescendant');
};
const move = (d) => {
  if (!options.length || loading) return;
  cur = (cur + d + options.length) % options.length;
  $$('[role="option"]', list).forEach((li, i) => li.setAttribute('aria-selected', String(i === cur)));
  ta.setAttribute('aria-activedescendant', UID + '-o' + cur);
  const li = list.children[cur];
  if (li) li.scrollIntoView({ block: 'nearest' });
};
const choose = (i) => {
  const o = options[i];
  if (!o || !act) return;
  const caret = act.end, after = ta.value[caret];
  const ins = act.sigil + o.value + (after === ' ' || after === '\n' ? '' : ' ');
  fresh = act.start;
  ta.setRangeText(ins, act.start, caret, 'end');
  if (after === ' ') ta.setSelectionRange(ta.selectionEnd + 1, ta.selectionEnd + 1);
  dismissed = -1;
  ta.focus();
  sync();
  grow();
  say('Inserted ' + o.label);
};

const sync = () => {
  act = activeToken();
  if (act && dismissed === act.start) act = null;
  if (act && (busy || ta.readOnly)) act = null;
  render();
  if (act) showList(); else hideList();
};

/* ---------- textarea events ---------- */
ta.addEventListener('input', () => { if (dismissed > -1 && !activeToken()) dismissed = -1; cur = 0; grow(); sync(); });
ta.addEventListener('scroll', () => { mirror.scrollTop = ta.scrollTop; place(); });
ta.addEventListener('pointerup', () => later(0, sync));
ta.addEventListener('focus', () => later(0, sync));
ta.addEventListener('blur', () => later(0, () => { if (document.activeElement !== ta) hideList(); }));
ta.addEventListener('keyup', (e) => {
  if (['ArrowLeft', 'ArrowRight', 'Home', 'End', 'PageUp', 'PageDown'].includes(e.key) ||
      (pop.hidden && (e.key === 'ArrowUp' || e.key === 'ArrowDown'))) sync();
});
ta.addEventListener('keydown', (e) => {
  if (!pop.hidden && act) {
    if (e.key === 'ArrowDown') { e.preventDefault(); move(1); return; }
    if (e.key === 'ArrowUp') { e.preventDefault(); move(-1); return; }
    if ((e.key === 'Enter' || e.key === 'Tab') && options.length && !loading && !e.shiftKey) { e.preventDefault(); choose(cur); return; }
    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); dismissed = act.start; act = null; render(); hideList(); return; }
  }
  if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); if (!post.disabled) submit(); }
});
list.addEventListener('pointerdown', (e) => e.preventDefault());
list.addEventListener('pointermove', (e) => {
  const li = e.target.closest('[role="option"]');
  if (li && +li.dataset.i !== cur) move(+li.dataset.i - cur);
});
list.addEventListener('click', (e) => {
  const li = e.target.closest('[role="option"]');
  if (li) choose(+li.dataset.i);
});

/* toolbar: insert a sigil at the caret and open its list */
$('.msc-compose__tools').addEventListener('click', (e) => {
  const b = e.target.closest('[data-ins]');
  if (!b || busy) return;
  const v = ta.value, s = ta.selectionStart, end = ta.selectionEnd;
  const pad = s > 0 && !/\s/.test(v[s - 1]) ? ' ' : '';
  ta.focus();
  ta.setRangeText(pad + b.dataset.ins, s, end, 'end');
  dismissed = -1; cur = 0;
  grow();
  sync();
});

/* ---------- posting ---------- */
const submit = () => {
  const bad = unknown();
  if (bad.length) {
    const names = [...new Set(bad.map((t) => t.text))];
    err.querySelector('span').innerHTML = '<b>' + esc(names.join(', ')) + '</b> ' + (names.length > 1 ? "aren't" : "isn't") + ' on Fieldnote. Pick someone from the list or remove the @.';
    err.hidden = false;
    ta.setAttribute('aria-invalid', 'true');
    return;
  }
  busy = true;
  hideList();
  ta.readOnly = true;
  tools.forEach((b) => { b.disabled = true; });
  post.setAttribute('aria-busy', 'true');
  $('.msc-compose__plbl').textContent = 'Posting';
  render();
  later(950, () => {
    const named = tokens(ta.value).filter((t) => t.sigil === '@').map((t) => PEOPLE.find((p) => p.h === t.word.toLowerCase())).filter(Boolean);
    const uniq = [...new Set(named)].map((p) => p.n.split(' ')[0]);
    $('.msc-compose__dt').innerHTML = 'Posted to <b>' + esc(audience) + '</b>';
    $('.msc-compose__dd').textContent = uniq.length
      ? (uniq.length === 1 ? uniq[0] : uniq.slice(0, -1).join(', ') + ' and ' + uniq[uniq.length - 1]) + (uniq.length === 1 ? ' was' : ' were') + ' notified about the mention.'
      : audience === 'Everyone' ? 'It’s live on your profile and in followers’ feeds.' : 'Only ' + audience.toLowerCase() + ' can see it.';
    busy = false;
    post.removeAttribute('aria-busy');
    $('.msc-compose__plbl').textContent = 'Post';
    done.hidden = false;
    post.disabled = true;
    $('.msc-compose__dt').focus({ preventScroll: true });
    say('Posted');
  });
};
post.addEventListener('click', submit);
$('.msc-compose__again').addEventListener('click', () => {
  done.hidden = true;
  ta.readOnly = false;
  tools.forEach((b) => { b.disabled = false; });
  ta.value = '';
  dismissed = -1;
  grow();
  sync();
  ta.focus();
});

/* ---------- audience menu ---------- */
const openAud = (focus) => {
  hideList();
  aud.toggleAttribute('data-open', true);
  audBtn.setAttribute('aria-expanded', 'true');
  const k = Math.max(0, audItems.findIndex((b) => b.getAttribute('aria-checked') === 'true'));
  audItems.forEach((b, i) => { b.tabIndex = i === k ? 0 : -1; });
  if (focus) audItems[k].focus();
};
const closeAud = (refocus) => {
  if (!aud.hasAttribute('data-open')) return;
  aud.removeAttribute('data-open');
  audBtn.setAttribute('aria-expanded', 'false');
  if (refocus) audBtn.focus();
};
audBtn.addEventListener('click', (e) => (aud.hasAttribute('data-open') ? closeAud(false) : openAud(e.detail === 0)));
audBtn.addEventListener('keydown', (e) => { if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); openAud(true); } });
$('.msc-compose__menu').addEventListener('keydown', (e) => {
  const k = audItems.indexOf(document.activeElement);
  const to = { ArrowDown: k + 1, ArrowUp: k - 1, Home: 0, End: audItems.length - 1 }[e.key];
  if (to !== undefined) {
    e.preventDefault();
    const j = (to + audItems.length) % audItems.length;
    audItems.forEach((b, i) => { b.tabIndex = i === j ? 0 : -1; });
    audItems[j].focus();
  } else if (e.key === 'Tab') closeAud(false);
});
$('.msc-compose__menu').addEventListener('click', (e) => {
  const b = e.target.closest('[role="menuitemradio"]');
  if (!b) return;
  audience = b.dataset.aud;
  audItems.forEach((x) => x.setAttribute('aria-checked', String(x === b)));
  $('.msc-compose__audlbl').textContent = audience;
  $('.msc-compose__audico').innerHTML = $('svg', b).innerHTML;
  closeAud(true);
  say('Audience: ' + audience);
});

root.addEventListener('keydown', (e) => { if (e.key === 'Escape' && aud.hasAttribute('data-open')) { e.preventDefault(); closeAud(true); } });
root.addEventListener('pointerdown', (e) => {
  if (!aud.contains(e.target)) closeAud(false);
  if (!pop.hidden && !pop.contains(e.target) && e.target !== ta) hideList();
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  place();
});
ro.observe(root);

ta.value = SEED;
grow();
sync();

css:
/* Re-theme with --msc-thread-paper, -ink, -accent and -up. */
.msc-thread {
  --msc-thread-paper: oklch(0.975 0.013 88);
  --msc-thread-ink: oklch(0.28 0.025 62);
  --msc-thread-accent: oklch(0.5 0.1 158);
  --msc-thread-up: oklch(0.62 0.17 42);
  --msc-thread-down: oklch(0.55 0.1 300);

  --msc-thread-card: color-mix(in oklch, var(--msc-thread-paper) 55%, oklch(1 0 0));
  --msc-thread-line: color-mix(in oklch, var(--msc-thread-ink) 12%, transparent);
  --msc-thread-wire: color-mix(in oklch, var(--msc-thread-ink) 17%, var(--msc-thread-paper));
  --msc-thread-muted: color-mix(in oklch, var(--msc-thread-ink) 70%, var(--msc-thread-paper));
  --msc-thread-faint: color-mix(in oklch, var(--msc-thread-ink) 48%, var(--msc-thread-paper));
  --msc-thread-hover: color-mix(in oklch, var(--msc-thread-ink) 5.5%, transparent);
  --msc-thread-ring: color-mix(in oklch, var(--msc-thread-accent) 70%, transparent);
  --msc-thread-ease: cubic-bezier(.22, 1, .36, 1);
  --msc-thread-spring: linear(0, 0.09 4%, 0.35 9%, 0.73 17%, 1 25%, 1.07 32%, 1.05 40%, 1.01 52%, 1);
  --msc-thread-a: 28px;
  --msc-thread-g: 8px;

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: 520px;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  border-radius: 16px;
  overflow: clip;
  color: var(--msc-thread-ink);
  background: var(--msc-thread-paper);
  box-shadow: 0 0 0 1px var(--msc-thread-line), 0 20px 40px -30px color-mix(in oklch, var(--msc-thread-ink) 50%, transparent);
  font: 400 13.5px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  timeline-scope: --msc-thread-sc;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .msc-thread { --msc-thread-spring: cubic-bezier(.34, 1.4, .5, 1); }
}
:where(.msc-thread) *, :where(.msc-thread) *::before, :where(.msc-thread) *::after { box-sizing: border-box; }
:where(.msc-thread) :is(button, textarea) { font: inherit; color: inherit; }
:where(.msc-thread) button { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.msc-thread) :focus-visible { outline: 2px solid var(--msc-thread-ring); outline-offset: 2px; }
:where(.msc-thread) :is(p, h3, ul, form) { margin: 0; }
.msc-thread svg { fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.msc-thread__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- header ---------- */
.msc-thread__head {
  position: relative; z-index: 3;
  padding: 14px 16px 0;
  background: var(--msc-thread-paper);
}
.msc-thread__kicker {
  font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase;
  color: var(--msc-thread-accent);
}
.msc-thread__title {
  margin-top: 3px;
  font-size: clamp(15px, 4.6cqi, 18px); font-weight: 720; letter-spacing: -.02em; line-height: 1.22;
  text-wrap: balance;
}
.msc-thread__bar {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  margin-top: 10px; padding-bottom: 10px;
  border-bottom: 1px solid var(--msc-thread-line);
}
.msc-thread__count {
  font-size: 12.5px; color: var(--msc-thread-muted); font-variant-numeric: tabular-nums;
  & b { color: var(--msc-thread-ink); font-weight: 650; }
}
.msc-thread__sort {
  position: relative; display: grid; grid-template-columns: 1fr 1fr; padding: 2px; border-radius: 9px;
  background: color-mix(in oklch, var(--msc-thread-ink) 7%, transparent);
  & button {
    position: relative; z-index: 1; padding: 4px 12px; border-radius: 7px;
    font-size: 12px; font-weight: 600; color: var(--msc-thread-muted);
    transition: color .2s;
    &[aria-checked="true"] { color: var(--msc-thread-ink); }
  }
}
.msc-thread__thumb {
  position: absolute; top: 2px; bottom: 2px; left: 2px; width: calc(50% - 2px); border-radius: 7px;
  background: var(--msc-thread-card);
  box-shadow: 0 1px 2px color-mix(in oklch, var(--msc-thread-ink) 14%, transparent), 0 0 0 .5px var(--msc-thread-line);
  transition: translate .45s var(--msc-thread-spring);
}
.msc-thread__sort:has([data-sort="new"][aria-checked="true"]) .msc-thread__thumb { translate: 100% 0; }

@supports (animation-timeline: scroll()) {
  .msc-thread__head { animation: msc-thread-lift linear both; animation-timeline: --msc-thread-sc; animation-range: 0 36px; }
}

/* ---------- scroller ---------- */
.msc-thread__scroll {
  overflow-y: auto; overscroll-behavior: contain;
  scroll-timeline: --msc-thread-sc block;
  scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--msc-thread-ink) 20%, transparent) transparent;
  padding: 4px 12px 18px 14px;
}
.msc-thread__tree { list-style: none; padding: 0; }
.msc-thread__tree > .msc-thread__node { padding-top: 14px; }
.msc-thread__tree > .msc-thread__node + .msc-thread__node { margin-top: 4px; border-top: 1px dashed var(--msc-thread-line); }

/* ---------- a node: comment on top, replies below, both on one subgrid ---------- */
.msc-thread__node {
  position: relative;
  display: grid; grid-template-columns: var(--msc-thread-a) minmax(0, 1fr); column-gap: var(--msc-thread-g);
  list-style: none;
  outline: none;
}
.msc-thread__c {
  grid-column: 1 / -1;
  display: grid; grid-template-columns: subgrid;
  grid-template-areas: "av meta" "line body" "line acts" "line form";
  position: relative;
  padding-bottom: 2px;
  border-radius: 10px;
  &::before { /* the stem from this avatar down to its replies */
    content: ""; grid-area: line; justify-self: center;
    width: 2px; margin: 3px 0 -4px; border-radius: 1px;
    background: var(--msc-thread-wire);
    transition: background-color .2s, opacity .3s;
  }
}
.msc-thread__node:not([aria-expanded="true"]) > .msc-thread__c::before { opacity: 0; }
.msc-thread__node:focus-visible > .msc-thread__c { box-shadow: 0 0 0 2px var(--msc-thread-paper), 0 0 0 4px var(--msc-thread-ring); }

.msc-thread__av {
  grid-area: av; position: relative; z-index: 1;
  display: grid; place-items: center; width: var(--msc-thread-a); height: var(--msc-thread-a); border-radius: 50%;
  font-size: 10.5px; font-weight: 700; letter-spacing: .01em;
  color: oklch(0.33 0.07 var(--h)); background: oklch(0.88 0.06 var(--h));
  transition: box-shadow .2s;
}
.msc-thread__meta {
  grid-area: meta; align-self: center;
  display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 6px;
  font-size: 12.5px; line-height: 1.3; color: var(--msc-thread-faint);
  & b { color: var(--msc-thread-ink); font-weight: 650; }
  & time { font-variant-numeric: tabular-nums; }
  & time::before { content: "·"; margin-right: 6px; }
}
.msc-thread__badge {
  align-self: center;
  padding: 1px 6px; border-radius: 5px;
  font-size: 10px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;
  color: var(--msc-thread-accent); background: color-mix(in oklch, var(--msc-thread-accent) 12%, transparent);
}
.msc-thread__body { grid-area: body; margin-top: 2px; text-wrap: pretty; overflow-wrap: anywhere; }
.msc-thread__acts {
  grid-area: acts;
  display: flex; align-items: center; gap: 4px; margin: 4px 0 0 -6px;
}
.msc-thread__vote {
  display: inline-flex; align-items: center;
  & button {
    display: grid; place-items: center; width: 26px; height: 26px; border-radius: 7px; color: var(--msc-thread-faint);
    transition: color .2s, background-color .2s, scale .3s var(--msc-thread-spring);
    &:hover { color: var(--msc-thread-ink); background: var(--msc-thread-hover); }
    &:active { scale: .88; }
    & svg { width: 16px; height: 16px; }
    &[data-v="up"][aria-pressed="true"] { color: var(--msc-thread-up); }
    &[data-v="down"][aria-pressed="true"] { color: var(--msc-thread-down); }
    &[aria-pressed="true"] svg { fill: currentColor; }
  }
}
.msc-thread__score {
  min-width: 2.2ch; overflow: hidden; height: 18px;
  font-size: 12px; font-weight: 700; line-height: 18px; text-align: center; font-variant-numeric: tabular-nums;
  color: var(--msc-thread-muted);
  & span { display: block; }
  &.is-up span { animation: msc-thread-roll-up .32s var(--msc-thread-ease); }
  &.is-down span { animation: msc-thread-roll-down .32s var(--msc-thread-ease); }
}
.msc-thread__vote:has([data-v="up"][aria-pressed="true"]) .msc-thread__score { color: var(--msc-thread-up); }
.msc-thread__vote:has([data-v="down"][aria-pressed="true"]) .msc-thread__score { color: var(--msc-thread-down); }
.msc-thread__act {
  display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 8px; border-radius: 7px;
  font-size: 12px; font-weight: 600; color: var(--msc-thread-faint);
  transition: color .2s, background-color .2s;
  & svg { width: 15px; height: 15px; }
  &:hover, &[aria-expanded="true"] { color: var(--msc-thread-ink); background: var(--msc-thread-hover); }
}

/* ---------- the rail: a real button over the connector column ---------- */
.msc-thread__rail {
  position: absolute; left: 0; top: calc(var(--msc-thread-a) + 2px); bottom: 0; z-index: 2;
  width: var(--msc-thread-a); border-radius: 6px;
  &:focus-visible { outline-offset: -2px; }
}
.msc-thread__node:not([aria-expanded="true"]) > .msc-thread__rail { display: none; }

.msc-thread__kids {
  grid-column: 1 / -1;
  display: grid; grid-template-rows: 1fr;
  transition: grid-template-rows .45s var(--msc-thread-ease), visibility 0s;
  & > ul {
    min-height: 0; overflow: hidden;
    list-style: none; padding: 0 0 0 calc(var(--msc-thread-a) + var(--msc-thread-g));
  }
  & > ul > li { padding-top: 12px; }
  & > ul > li::before, & > ul > li::after {
    content: ""; position: absolute; pointer-events: none;
    left: calc(-1 * (var(--msc-thread-g) + var(--msc-thread-a) / 2) - 1px);
    border: 0 solid var(--msc-thread-wire);
    transition: border-color .2s;
  }
  & > ul > li::before { /* elbow into the reply's avatar */
    top: 0; height: calc(12px + var(--msc-thread-a) / 2 + 1px);
    width: calc(var(--msc-thread-g) + var(--msc-thread-a) / 2 - 2px);
    border-left-width: 2px; border-bottom-width: 2px; border-bottom-left-radius: 11px;
  }
  & > ul > li:not(:last-child)::after { top: 0; bottom: 0; border-left-width: 2px; }
}
.msc-thread__node[aria-expanded="false"] > .msc-thread__kids {
  grid-template-rows: 0fr; visibility: hidden;
  transition: grid-template-rows .4s var(--msc-thread-ease), visibility 0s .4s;
}

/* hover a rail: its whole branch lights up */
.msc-thread__node:has(> .msc-thread__rail:is(:hover, :focus-visible)) {
  & > .msc-thread__c::before { background: var(--msc-thread-accent); }
  & > .msc-thread__c .msc-thread__av { box-shadow: 0 0 0 2px var(--msc-thread-paper), 0 0 0 4px color-mix(in oklch, var(--msc-thread-accent) 55%, transparent); }
  & > .msc-thread__kids > ul > li::before, & > .msc-thread__kids > ul > li::after { border-color: var(--msc-thread-accent); }
}

/* collapsed: a pill with who replied */
.msc-thread__pill {
  grid-column: 2; justify-self: start;
  display: none; align-items: center; gap: 7px; margin: 6px 0 2px -2px; padding: 3px 10px 3px 4px; border-radius: 999px;
  font-size: 12px; font-weight: 600; color: var(--msc-thread-accent);
  background: color-mix(in oklch, var(--msc-thread-accent) 9%, transparent);
  transition: background-color .2s, opacity .3s, translate .35s var(--msc-thread-ease);
  &:hover { background: color-mix(in oklch, var(--msc-thread-accent) 15%, transparent); }
  & .msc-thread__mini { display: inline-flex; }
  & .msc-thread__mini i {
    width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center;
    font-size: 8px; font-weight: 700; font-style: normal;
    color: oklch(0.33 0.07 var(--h)); background: oklch(0.88 0.06 var(--h));
    box-shadow: 0 0 0 2px var(--msc-thread-paper);
  }
  & .msc-thread__mini i + i { margin-left: -5px; }
}
.msc-thread__node[aria-expanded="false"] > .msc-thread__pill { display: inline-flex; }
@starting-style {
  .msc-thread__node[aria-expanded="false"] > .msc-thread__pill { opacity: 0; translate: 0 -4px; }
}

/* reply form */
.msc-thread__form {
  grid-area: form;
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; grid-template-areas: "ta ta ta" ". no yes"; gap: 6px;
  margin: 8px 0 4px;
  transition: opacity .25s, translate .35s var(--msc-thread-ease);
  & textarea {
    grid-area: ta; width: 100%; min-height: 58px; padding: 8px 10px; border-radius: 10px; resize: none;
    border: 0; background: var(--msc-thread-card); font-size: 13px; line-height: 1.45;
    box-shadow: 0 0 0 1px var(--msc-thread-line);
    transition: box-shadow .2s;
    &::placeholder { color: var(--msc-thread-faint); }
    &:focus { outline: none; box-shadow: 0 0 0 1.5px var(--msc-thread-ring), 0 0 0 4px color-mix(in oklch, var(--msc-thread-accent) 12%, transparent); }
  }
  & button { height: 28px; padding: 0 12px; border-radius: 8px; font-size: 12px; font-weight: 650; }
  & [data-f="no"] { grid-area: no; color: var(--msc-thread-muted); &:hover { background: var(--msc-thread-hover); } }
  & [data-f="yes"] {
    grid-area: yes; color: var(--msc-thread-paper); background: var(--msc-thread-accent);
    transition: opacity .2s, background-color .2s;
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--msc-thread-accent) 85%, var(--msc-thread-ink)); }
    &:disabled { opacity: .38; cursor: not-allowed; }
  }
}
@starting-style {
  .msc-thread__form { opacity: 0; translate: 0 -4px; }
}

.msc-thread__node.is-new > .msc-thread__c { animation: msc-thread-flash 2.4s var(--msc-thread-ease); }
.msc-thread__node.is-new { animation: msc-thread-in .5s var(--msc-thread-ease) both; }

/* lazy replies */
.msc-thread__load {
  position: relative;
  & button {
    display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px 0 8px; margin-left: -2px; border-radius: 8px;
    font-size: 12px; font-weight: 650; color: var(--msc-thread-accent);
    &:hover { background: color-mix(in oklch, var(--msc-thread-accent) 9%, transparent); }
    & svg { width: 15px; height: 15px; }
  }
}
.msc-thread__kids > ul > .msc-thread__load::before { border-style: dashed; height: calc(12px + 14px + 1px); }
.msc-thread__skel {
  display: grid; grid-template-columns: var(--msc-thread-a) 1fr; gap: 8px; padding-top: 12px;
  & i { display: block; height: 9px; border-radius: 5px; background: linear-gradient(90deg, var(--msc-thread-hover) 25%, color-mix(in oklch, var(--msc-thread-ink) 11%, transparent) 50%, var(--msc-thread-hover) 75%) 0 0 / 300% 100%; animation: msc-thread-shimmer 1.1s linear infinite; }
  & > i { width: var(--msc-thread-a); height: var(--msc-thread-a); border-radius: 50%; }
  & span { display: grid; gap: 7px; align-content: center; }
  & span i:first-child { width: 40%; }
}

@container (max-width: 340px) {
  .msc-thread { --msc-thread-a: 24px; --msc-thread-g: 6px; }
  .msc-thread__scroll { padding-inline: 10px 8px; }
  .msc-thread__head { padding-inline: 14px; }
  .msc-thread__av { font-size: 9px; }
  .msc-thread__act span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
@container (min-width: 460px) {
  .msc-thread { --msc-thread-a: 32px; --msc-thread-g: 10px; font-size: 14px; }
  .msc-thread__head { padding: 18px 20px 0; }
  .msc-thread__scroll { padding-inline: 18px 16px; }
}

@keyframes msc-thread-lift {
  to { box-shadow: 0 10px 14px -12px color-mix(in oklch, var(--msc-thread-ink) 35%, transparent); }
}
@keyframes msc-thread-roll-up { from { translate: 0 100%; opacity: 0; } }
@keyframes msc-thread-roll-down { from { translate: 0 -100%; opacity: 0; } }
@keyframes msc-thread-flash { 0%, 35% { background-color: color-mix(in oklch, var(--msc-thread-accent) 12%, transparent); } 100% { background-color: transparent; } }
@keyframes msc-thread-in { from { opacity: 0; translate: 0 -6px; } }
@keyframes msc-thread-shimmer { to { background-position: -150% 0; } }

@media (prefers-reduced-motion: reduce) {
  .msc-thread__kids, .msc-thread__node[aria-expanded="false"] > .msc-thread__kids { transition: none; }
  .msc-thread__thumb { transition: none; }
  .msc-thread__score span, .msc-thread__node.is-new { animation: none !important; }
  .msc-thread__node.is-new > .msc-thread__c { animation: msc-thread-flash 2.4s linear; }
  .msc-thread__skel i { animation: none; }
  .msc-thread__form { transition: none; }
}

js:
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const UID = 'msc-thread-' + Math.random().toString(36).slice(2, 7);

const WHO = {
  wz: ['Wen Zhao', 20], hg: ['Hollis Grant', 158], dv: ['Dmitri Volkov', 250], ao: ['Amara Osei', 70],
  lp: ['Lucía Paredes', 330], jb: ['Jonas Becker', 215], mt: ['Mei Tanaka', 0], km: ['Kofi Mensah', 110],
  sa: ['Sven Aaltonen', 190], me: ['You', 45]
};
const AUTHOR = 'hg';
/* 11 comments are loaded; Kofi's thread has 2 more on the server, so the header says 13. */
const DATA = [
  { id: 'c1', who: 'wz', ago: 180, score: 48, text: 'We tried the same move last spring. Cold starts dropped, but cache invalidation across 14 regions became the new on-call favourite. How are you handling purge fan-out?', kids: [
    { id: 'c1a', who: 'hg', ago: 150, score: 31, text: 'Purges go through a single queue with a 90-second coalescing window. Most deploys touch fewer than 40 keys, so fan-out stays boring.', kids: [
      { id: 'c1a1', who: 'wz', ago: 128, score: 12, collapsed: true, text: 'Boring is the goal. Does the window ever delay a hotfix?', kids: [
        { id: 'c1a1a', who: 'hg', ago: 70, score: 9, text: 'Hotfixes skip the window with a priority flag. It has been used twice since March.' }
      ] }
    ] },
    { id: 'c1b', who: 'dv', ago: 118, score: 7, text: 'We hit the same wall and moved to tag-based purges. Queue depth halved overnight.' }
  ] },
  { id: 'c2', who: 'ao', ago: 125, score: 25, vote: 1, text: 'The p95 chart is the most honest thing in the post. Most write-ups only show the median.', kids: [
    { id: 'c2a', who: 'lp', ago: 65, score: 5, text: 'Agreed. The tail is where people actually feel it.' }
  ] },
  { id: 'c3', who: 'jb', ago: 54, score: 14, text: 'Any numbers on egress cost before and after? That is what my finance team will ask first.', kids: [
    { id: 'c3a', who: 'hg', ago: 40, score: 11, text: 'Egress went from $18.4k to $11.9k a month, mostly from fewer origin round-trips.' },
    { id: 'c3b', who: 'mt', ago: 22, score: 3, text: 'Same pattern here. Origin traffic was the hidden cost.' }
  ] },
  { id: 'c4', who: 'km', ago: 12, score: 2, text: 'Bookmarking this for our Q3 planning doc.', kids: [], more: [
    { id: 'c4a', who: 'sa', ago: 8, score: 1, text: 'Same. The rollback section alone is worth it.' },
    { id: 'c4b', who: 'hg', ago: 5, score: 1, text: 'Thanks both. The rollback runbook is linked in the appendix.' }
  ] }
];

const tree = $('.msc-thread__tree');
const scroller = $('.msc-thread__scroll');
const live = $('.msc-thread__sr');
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const esc = (t) => t.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const ago = (m) => (m < 1 ? 'just now' : m < 60 ? m + 'm' : Math.round(m / 60) + 'h');
const initials = (k) => WHO[k][0] === 'You' ? 'YO' : WHO[k][0].split(' ').map((w) => w[0]).join('');
const byId = new Map();
let pending = DATA.reduce(function n(a, c) { return a + (c.more ? c.more.length : 0) + (c.kids || []).reduce(n, 0); }, 0);
let seq = 0;

const UP = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5.5 5.5 13h4v5.5h5V13h4Z"/></svg>';
const DOWN = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 18.5 18.5 11h-4V5.5h-5V11h-4Z"/></svg>';
const REPLY = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9.5 7.5 5 12l4.5 4.5M5 12h9.5a4.5 4.5 0 0 1 4.5 4.5V18"/></svg>';
const MORE = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5.5v13M5.5 12h13"/></svg>';

/* ---------- rendering ---------- */
const descendants = (c) => (c.kids || []).reduce((a, k) => a + 1 + descendants(k), 0);
const node = (c, level) => {
  byId.set(c.id, c);
  c.level = level;
  const li = document.createElement('li');
  li.className = 'msc-thread__node';
  li.setAttribute('role', 'treeitem');
  li.setAttribute('aria-level', level);
  li.tabIndex = -1;
  li.dataset.id = c.id;
  li.id = UID + '-' + c.id;
  const who = WHO[c.who], v = c.vote || 0;
  li.setAttribute('aria-label', who[0] + ', ' + ago(c.ago) + (c.ago < 1 ? '' : ' ago') + ': ' + c.text);
  li.innerHTML =
    '<article class="msc-thread__c">' +
      '<span class="msc-thread__av" style="--h:' + who[1] + '" aria-hidden="true">' + initials(c.who) + '</span>' +
      '<p class="msc-thread__meta"><b>' + esc(who[0]) + '</b>' + (c.who === AUTHOR ? '<span class="msc-thread__badge">Author</span>' : '') +
        '<time>' + ago(c.ago) + '</time></p>' +
      '<p class="msc-thread__body">' + esc(c.text) + '</p>' +
      '<div class="msc-thread__acts">' +
        '<div class="msc-thread__vote" role="group" aria-label="Votes">' +
          '<button type="button" data-v="up" aria-pressed="' + (v > 0) + '" aria-label="Upvote">' + UP + '</button>' +
          '<span class="msc-thread__score" aria-live="off"><span>' + (c.score + v) + '</span></span>' +
          '<button type="button" data-v="down" aria-pressed="' + (v < 0) + '" aria-label="Downvote">' + DOWN + '</button>' +
        '</div>' +
        '<button type="button" class="msc-thread__act" data-do="reply" aria-expanded="false">' + REPLY + '<span>Reply</span></button>' +
      '</div>' +
    '</article>';
  const hasKids = (c.kids && c.kids.length) || (c.more && c.more.length);
  if (hasKids) wireKids(li, c);
  return li;
};
const wireKids = (li, c) => {
  li.setAttribute('aria-expanded', String(!c.collapsed));
  const rail = document.createElement('button');
  rail.type = 'button';
  rail.className = 'msc-thread__rail';
  rail.tabIndex = -1;
  li.append(rail);
  const kids = document.createElement('div');
  kids.className = 'msc-thread__kids';
  const ul = document.createElement('ul');
  ul.setAttribute('role', 'group');
  (c.kids || []).forEach((k) => ul.append(node(k, c.level + 1)));
  if (c.more && c.more.length) {
    const ld = document.createElement('li');
    ld.className = 'msc-thread__load';
    ld.setAttribute('role', 'none');
    ld.innerHTML = '<button type="button" data-do="load">' + MORE + 'Load ' + c.more.length + ' more ' + (c.more.length === 1 ? 'reply' : 'replies') + '</button>';
    ul.append(ld);
  }
  kids.append(ul);
  li.append(kids);
  const pill = document.createElement('button');
  pill.type = 'button';
  pill.className = 'msc-thread__pill';
  pill.dataset.do = 'expand';
  li.append(pill);
  labelBranch(li, c);
};
const labelBranch = (li, c) => {
  const n = descendants(c) + (c.more ? c.more.length : 0);
  const name = WHO[c.who][0];
  const rail = $(':scope > .msc-thread__rail', li), pill = $(':scope > .msc-thread__pill', li);
  if (rail) rail.setAttribute('aria-label', 'Collapse ' + n + (n === 1 ? ' reply' : ' replies') + ' to ' + name);
  if (pill) {
    const faces = [...new Set((c.kids || []).map((k) => k.who))].slice(0, 3);
    pill.innerHTML = '<span class="msc-thread__mini" aria-hidden="true">' + faces.map((k) => '<i style="--h:' + WHO[k][1] + '">' + initials(k)[0] + '</i>').join('') + '</span>' +
      n + (n === 1 ? ' reply' : ' replies');
    pill.setAttribute('aria-label', 'Show ' + n + (n === 1 ? ' reply' : ' replies') + ' to ' + name);
  }
};
const total = () => byId.size + pending;
const paintCount = () => { $('.msc-thread__count b').textContent = total(); };

DATA.forEach((c) => tree.append(node(c, 1)));
paintCount();

/* ---------- roving focus over visible treeitems ---------- */
const visible = () => $$('[role="treeitem"]', tree).filter((li) => !li.parentElement.closest('[role="treeitem"][aria-expanded="false"]'));
let current = tree.firstElementChild;
const setCurrent = (li, focus) => {
  if (!li) return;
  if (current) current.tabIndex = -1;
  current = li;
  li.tabIndex = 0;
  if (focus) li.focus();
};
setCurrent(current, false);
tree.addEventListener('focusin', (e) => {
  const li = e.target.closest('[role="treeitem"]');
  if (li && li !== current) setCurrent(li, false);
});

const toggle = (li, open) => {
  const c = byId.get(li.dataset.id);
  const want = open === undefined ? li.getAttribute('aria-expanded') !== 'true' : open;
  if (!li.hasAttribute('aria-expanded') || (li.getAttribute('aria-expanded') === 'true') === want) return;
  li.setAttribute('aria-expanded', String(want));
  c.collapsed = !want;
  const n = descendants(c) + (c.more ? c.more.length : 0);
  say((want ? 'Expanded ' : 'Collapsed ') + n + (n === 1 ? ' reply' : ' replies'));
};

tree.addEventListener('keydown', (e) => {
  const li = e.target;
  if (!li.matches || !li.matches('[role="treeitem"]')) return;
  const vis = visible(), k = vis.indexOf(li);
  const exp = li.getAttribute('aria-expanded');
  let to = null;
  switch (e.key) {
    case 'ArrowDown': to = vis[k + 1]; break;
    case 'ArrowUp': to = vis[k - 1]; break;
    case 'Home': to = vis[0]; break;
    case 'End': to = vis[vis.length - 1]; break;
    case 'ArrowRight':
      if (exp === 'false') { toggle(li, true); e.preventDefault(); return; }
      if (exp === 'true') to = $('[role="treeitem"]', $(':scope > .msc-thread__kids', li));
      break;
    case 'ArrowLeft':
      if (exp === 'true') { toggle(li, false); e.preventDefault(); return; }
      to = li.parentElement.closest('[role="treeitem"]');
      break;
    case 'Enter': case 'r':
      e.preventDefault(); openReply(li); return;
    case '*': {
      const sibs = [...li.parentElement.children].filter((x) => x.matches('[role="treeitem"]'));
      sibs.forEach((x) => toggle(x, true)); e.preventDefault(); return;
    }
    default: return;
  }
  e.preventDefault();
  if (to) setCurrent(to, true);
});

/* ---------- votes ---------- */
const vote = (btn) => {
  const li = btn.closest('[role="treeitem"]'), c = byId.get(li.dataset.id);
  const dir = btn.dataset.v === 'up' ? 1 : -1;
  const before = c.vote || 0;
  c.vote = before === dir ? 0 : dir;
  const art = $(':scope > .msc-thread__c', li);
  $('[data-v="up"]', art).setAttribute('aria-pressed', String(c.vote > 0));
  $('[data-v="down"]', art).setAttribute('aria-pressed', String(c.vote < 0));
  const sc = $('.msc-thread__score', art);
  sc.classList.remove('is-up', 'is-down');
  void sc.offsetWidth;
  sc.classList.add(c.vote > before ? 'is-up' : 'is-down');
  sc.firstElementChild.textContent = c.score + c.vote;
  say((c.score + c.vote) + ' points');
};

/* ---------- replies ---------- */
const closeForms = (except) => $$('.msc-thread__form', tree).forEach((f) => {
  if (f === except) return;
  const li = f.closest('[role="treeitem"]');
  $(':scope > .msc-thread__c [data-do="reply"]', li).setAttribute('aria-expanded', 'false');
  f.remove();
});
const openReply = (li) => {
  const art = $(':scope > .msc-thread__c', li);
  const existing = $(':scope > .msc-thread__form', art);
  if (existing) { $('textarea', existing).focus(); return; }
  closeForms();
  const c = byId.get(li.dataset.id);
  const f = document.createElement('form');
  f.className = 'msc-thread__form';
  f.innerHTML = '<textarea rows="2" maxlength="500" aria-label="Reply to ' + esc(WHO[c.who][0]) + '" placeholder="Reply to ' + esc(WHO[c.who][0].split(' ')[0]) + '…"></textarea>' +
    '<button type="button" data-f="no">Cancel</button><button type="submit" data-f="yes" disabled>Reply</button>';
  art.append(f);
  $('[data-do="reply"]', art).setAttribute('aria-expanded', 'true');
  const ta = $('textarea', f);
  ta.addEventListener('input', () => { $('[data-f="yes"]', f).disabled = !ta.value.trim(); });
  ta.addEventListener('keydown', (e) => {
    e.stopPropagation();
    if (e.key === 'Escape') { e.preventDefault(); cancel(f); }
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); f.requestSubmit(); }
  });
  f.addEventListener('submit', (e) => { e.preventDefault(); post(li, ta.value.trim()); });
  $('[data-f="no"]', f).addEventListener('click', () => cancel(f));
  ta.focus({ preventScroll: true });
  f.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
};
const cancel = (f) => {
  const li = f.closest('[role="treeitem"]');
  const btn = $(':scope > .msc-thread__c [data-do="reply"]', li);
  btn.setAttribute('aria-expanded', 'false');
  f.remove();
  btn.focus();
};
const post = (li, text) => {
  if (!text) return;
  const c = byId.get(li.dataset.id);
  const mine = { id: 'n' + (++seq), who: 'me', ago: 0, score: 0, vote: 1, text };
  c.kids = c.kids || [];
  c.kids.unshift(mine);
  if (!li.hasAttribute('aria-expanded')) { c.collapsed = false; wireKids(li, { ...c, kids: [] }); }
  const ul = $(':scope > .msc-thread__kids > ul', li);
  const el = node(mine, c.level + 1);
  el.classList.add('is-new');
  ul.prepend(el);
  toggle(li, true);
  labelBranch(li, c);
  $(':scope > .msc-thread__c .msc-thread__form', li).remove();
  $(':scope > .msc-thread__c [data-do="reply"]', li).setAttribute('aria-expanded', 'false');
  paintCount();
  setCurrent(el, true);
  el.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
  say('Reply posted. ' + total() + ' comments');
};

/* ---------- lazy replies ---------- */
const load = (btn) => {
  const ld = btn.closest('.msc-thread__load'), li = ld.closest('[role="treeitem"]'), c = byId.get(li.dataset.id);
  btn.disabled = true;
  ld.setAttribute('aria-busy', 'true');
  ld.innerHTML = '<div class="msc-thread__skel" aria-label="Loading replies"><i></i><span><i></i><i></i></span></div>'.repeat(Math.min(2, c.more.length));
  later(RM.matches ? 300 : 750, () => {
    const more = c.more.splice(0);
    pending -= more.length;
    const els = more.map((k) => { c.kids.push(k); const el = node(k, c.level + 1); el.style.setProperty('animation-delay', '0ms'); el.classList.add('is-new'); return el; });
    ld.replaceWith(...els);
    labelBranch(li, c);
    paintCount();
    setCurrent(els[0], true);
    say(more.length + ' replies loaded');
  });
};

/* ---------- sort with FLIP ---------- */
const sortBy = (mode) => {
  const tops = [...tree.children];
  const first = new Map(tops.map((el) => [el, el.getBoundingClientRect().top]));
  const key = (el) => { const c = byId.get(el.dataset.id); return mode === 'new' ? c.ago : -(c.score + (c.vote || 0)); };
  tops.slice().sort((a, b) => key(a) - key(b)).forEach((el) => tree.append(el));
  if (!RM.matches) {
    tops.forEach((el, i) => {
      const dy = first.get(el) - el.getBoundingClientRect().top;
      if (Math.abs(dy) > 1) el.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 560, easing: 'cubic-bezier(.22,1,.36,1)', delay: i * 18, fill: 'backwards' });
    });
  }
  say('Sorted by ' + (mode === 'new' ? 'newest' : 'top'));
};
const sortBtns = $$('.msc-thread__sort button');
const pickSort = (b, focus) => {
  /* picking the active sort again re-ranks, so fresh votes take effect */
  sortBtns.forEach((x) => { x.setAttribute('aria-checked', String(x === b)); x.tabIndex = x === b ? 0 : -1; });
  if (focus) b.focus();
  sortBy(b.dataset.sort);
};
$('.msc-thread__sort').addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) pickSort(b, false); });
$('.msc-thread__sort').addEventListener('keydown', (e) => {
  if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
  e.preventDefault();
  const k = sortBtns.indexOf(document.activeElement);
  pickSort(sortBtns[(k + 1) % 2], true);
});

/* ---------- clicks ---------- */
tree.addEventListener('click', (e) => {
  const t = e.target.closest('button');
  if (!t) return;
  const li = t.closest('[role="treeitem"]');
  if (t.matches('[data-v]')) vote(t);
  else if (t.classList.contains('msc-thread__rail')) { toggle(li, false); setCurrent(li, e.detail === 0); }
  else if (t.dataset.do === 'expand') { toggle(li, true); setCurrent(li, true); }
  else if (t.dataset.do === 'reply') { if (t.getAttribute('aria-expanded') === 'true') cancel($(':scope > .msc-thread__c .msc-thread__form', li)); else openReply(li); }
  else if (t.dataset.do === 'load') load(t);
});

css:
/* Re-theme with --msc-profile-bg, -ink, -accent and -danger. */
.msc-profile {
  --msc-profile-bg: oklch(0.225 0.018 48);
  --msc-profile-ink: oklch(0.95 0.012 75);
  --msc-profile-accent: oklch(0.81 0.11 58);
  --msc-profile-danger: oklch(0.69 0.17 26);

  --msc-profile-raise: color-mix(in oklch, var(--msc-profile-ink) 7%, var(--msc-profile-bg));
  --msc-profile-line: color-mix(in oklch, var(--msc-profile-ink) 13%, transparent);
  --msc-profile-muted: color-mix(in oklch, var(--msc-profile-ink) 68%, var(--msc-profile-bg));
  --msc-profile-faint: color-mix(in oklch, var(--msc-profile-ink) 46%, var(--msc-profile-bg));
  --msc-profile-hover: color-mix(in oklch, var(--msc-profile-ink) 8%, transparent);
  --msc-profile-ring: color-mix(in oklch, var(--msc-profile-accent) 75%, transparent);
  --msc-profile-on-accent: oklch(0.24 0.04 50);
  --msc-profile-ease: cubic-bezier(.22, 1, .36, 1);
  --msc-profile-spring: linear(0, 0.1 4%, 0.38 9%, 0.77 17%, 1.02 25%, 1.1 32%, 1.07 40%, 1.01 52%, 0.99 64%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  padding: 0 16px 16px;
  border-radius: 20px;
  overflow: clip;
  color: var(--msc-profile-ink);
  background: var(--msc-profile-bg);
  box-shadow: 0 26px 50px -30px oklch(0 0 0 / .65);
  font: 400 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .msc-profile { --msc-profile-spring: cubic-bezier(.34, 1.5, .5, 1); }
}
.msc-profile::after {
  content: ""; position: absolute; inset: 0; z-index: 9; border-radius: inherit; pointer-events: none;
  box-shadow: inset 0 0 0 1px var(--msc-profile-line);
}
:where(.msc-profile) *, :where(.msc-profile) *::before, :where(.msc-profile) *::after { box-sizing: border-box; }
:where(.msc-profile) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.msc-profile) :focus-visible { outline: 2px solid var(--msc-profile-ring); outline-offset: 2px; }
:where(.msc-profile) :is(h3, p, ul, dl, dd) { margin: 0; }
.msc-profile svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.msc-profile__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- cover: contour lines ---------- */
.msc-profile__cover {
  position: relative;
  height: clamp(76px, 26cqi, 112px);
  margin: 0 -16px;
  overflow: hidden;
  background:
    radial-gradient(120% 140% at 85% -20%, color-mix(in oklch, var(--msc-profile-accent) 55%, transparent), transparent 60%),
    linear-gradient(160deg, oklch(0.4 0.07 45), oklch(0.3 0.05 35));
  & i {
    position: absolute; inset: -40%;
    background:
      radial-gradient(30% 40% at 70% 40%, color-mix(in oklch, var(--msc-profile-accent) 22%, transparent), transparent 70%),
      repeating-radial-gradient(ellipse 70% 52% at 30% 78%, transparent 0 15px, color-mix(in oklch, var(--msc-profile-accent) 30%, transparent) 15px 16.2px);
    -webkit-mask: linear-gradient(180deg, #000 30%, transparent 95%);
    mask: linear-gradient(180deg, #000 30%, transparent 95%);
    animation: msc-profile-drift 26s linear infinite alternate;
  }
  &::after {
    content: ""; position: absolute; inset: auto 0 0; height: 50%;
    background: linear-gradient(transparent, var(--msc-profile-bg));
  }
}

/* ---------- avatar row ---------- */
.msc-profile__top {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 10px;
  margin-top: -34px; position: relative; z-index: 2;
}
.msc-profile__av {
  position: relative; display: grid; place-items: center; flex: none;
  width: 72px; height: 72px; border-radius: 50%;
  font-size: 22px; font-weight: 750; letter-spacing: -.02em;
  color: var(--msc-profile-on-accent);
  background: radial-gradient(circle at 32% 28%, oklch(0.93 0.06 75), var(--msc-profile-accent) 70%);
  box-shadow: 0 0 0 4px var(--msc-profile-bg);
}
.msc-profile__dot {
  position: absolute; right: 3px; bottom: 3px; width: 14px; height: 14px; border-radius: 50%;
  background: oklch(0.76 0.16 150); box-shadow: 0 0 0 3px var(--msc-profile-bg);
}
.msc-profile__ctas { display: flex; align-items: center; gap: 6px; padding-bottom: 2px; }
.msc-profile__icon {
  display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%;
  color: var(--msc-profile-ink);
  box-shadow: inset 0 0 0 1px var(--msc-profile-line);
  transition: background-color .2s, scale .3s var(--msc-profile-spring), opacity .25s, translate .35s var(--msc-profile-spring);
  & svg { width: 18px; height: 18px; }
  &:hover { background: var(--msc-profile-hover); }
  &:active { scale: .92; }
}
.msc-profile__bell {
  & .msc-profile__waves { opacity: 0; transition: opacity .2s; }
  &[aria-pressed="true"] { color: var(--msc-profile-on-accent); background: var(--msc-profile-accent); box-shadow: none; }
  &[aria-pressed="true"] svg path:first-child { fill: currentColor; }
  &[aria-pressed="true"] .msc-profile__waves { opacity: 1; }
  &.is-ring svg { animation: msc-profile-ring .8s var(--msc-profile-ease); transform-origin: 50% 4px; }
}
.msc-profile__ctas:has(.msc-profile__follow:not([data-state="following"])) .msc-profile__bell {
  display: none; opacity: 0; scale: .5;
}
.msc-profile__bell { transition: background-color .2s, opacity .25s, scale .4s var(--msc-profile-spring), display .3s allow-discrete; }
@starting-style {
  .msc-profile__bell { opacity: 0; scale: .5; }
}
.msc-profile__tipwrap { position: relative; display: grid; }
.msc-profile__tip {
  position: absolute; right: 50%; bottom: calc(100% + 8px); translate: 50% 4px;
  padding: 4px 8px; border-radius: 7px; white-space: nowrap;
  font-size: 11.5px; font-weight: 600;
  color: var(--msc-profile-bg); background: var(--msc-profile-ink);
  opacity: 0; pointer-events: none;
  transition: opacity .18s, translate .3s var(--msc-profile-ease);
  &:not(:empty).is-on { opacity: 1; translate: 50% 0; }
  &[data-tone="bad"] { background: var(--msc-profile-danger); color: oklch(0.98 0 0); }
}

/* ---------- follow button: three labels in one cell, so it never changes size ---------- */
.msc-profile__follow {
  position: relative; isolation: isolate;
  display: inline-grid; place-items: center; grid-template-areas: "l";
  height: 36px; padding: 0 16px; border-radius: 999px;
  font-size: 13.5px; font-weight: 700; letter-spacing: .005em;
  color: var(--msc-profile-on-accent);
  box-shadow: inset 0 0 0 1px var(--msc-profile-line);
  transition: color .25s, box-shadow .25s, scale .3s var(--msc-profile-spring);
  &::before { /* the fill that drains away */
    content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit;
    background: var(--msc-profile-accent);
    clip-path: inset(0 0 0 0 round 999px);
    transition: clip-path .5s var(--msc-profile-ease), background-color .25s;
  }
  &:active { scale: .96; }
  &:hover:not([data-state="following"])::before { background: color-mix(in oklch, var(--msc-profile-accent) 86%, oklch(1 0 0)); }
}
.msc-profile__lbl {
  --msc-profile-ty: 0px;
  --msc-profile-blur: 0px;
  grid-area: l; display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
  translate: 0 var(--msc-profile-ty);
  filter: blur(var(--msc-profile-blur));
  transition: opacity .2s, translate .35s var(--msc-profile-ease), filter .25s;
  & svg { width: 16px; height: 16px; stroke-width: 2.3; }
}
.msc-profile__follow .msc-profile__lbl:not([data-l="idle"]) { opacity: 0; --msc-profile-ty: 8px; --msc-profile-blur: 2px; }
.msc-profile__follow[data-state="pending"] .msc-profile__lbl { opacity: 0; --msc-profile-ty: -8px; --msc-profile-blur: 2px; }
.msc-profile__follow[data-state="following"] {
  color: var(--msc-profile-ink);
  &::before { clip-path: inset(0 0 0 100% round 999px); }
  & .msc-profile__lbl[data-l="idle"] { opacity: 0; --msc-profile-ty: -8px; --msc-profile-blur: 2px; }
  & .msc-profile__lbl[data-l="following"] { opacity: 1; --msc-profile-ty: 0px; --msc-profile-blur: 0px; }
  & .msc-profile__check { stroke-dasharray: 16; stroke-dashoffset: 16; animation: msc-profile-draw .45s var(--msc-profile-ease) .15s forwards; }
}
/* "Unfollow" only after the pointer has left once since following */
.msc-profile__follow[data-state="following"][data-armed]:is(:hover, :focus-visible) {
  color: var(--msc-profile-danger);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--msc-profile-danger) 55%, transparent);
  background: color-mix(in oklch, var(--msc-profile-danger) 10%, transparent);
  & .msc-profile__lbl[data-l="following"] { opacity: 0; --msc-profile-ty: -8px; --msc-profile-blur: 2px; }
  & .msc-profile__lbl[data-l="unfollow"] { opacity: 1; --msc-profile-ty: 0px; --msc-profile-blur: 0px; }
}
.msc-profile__spin {
  grid-area: l; width: 16px; height: 16px; border-radius: 50%;
  border: 2px solid currentColor; border-right-color: transparent;
  opacity: 0; scale: .5;
  transition: opacity .2s, scale .3s var(--msc-profile-ease);
}
.msc-profile__follow[data-state="pending"] .msc-profile__spin { opacity: 1; scale: 1; animation: msc-profile-spin .7s linear infinite; }

/* ---------- identity ---------- */
.msc-profile__id { margin-top: 10px; }
.msc-profile__name {
  display: flex; align-items: center; gap: 6px;
  font-size: clamp(18px, 6cqi, 22px); font-weight: 750; letter-spacing: -.025em; line-height: 1.15;
  text-wrap: balance;
}
.msc-profile__ok {
  width: 19px; height: 19px;
  & path:first-child { fill: var(--msc-profile-accent); stroke: none; }
  & .msc-profile__okc { stroke: var(--msc-profile-on-accent); stroke-width: 2.3; }
}
.msc-profile__handle {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; margin-top: 3px;
  font-size: 13px; color: var(--msc-profile-faint);
}
.msc-profile__fy {
  padding: 1px 6px; border-radius: 5px;
  font-size: 11px; font-weight: 600; color: var(--msc-profile-muted); background: var(--msc-profile-hover);
}
.msc-profile__bio {
  margin-top: 10px; font-size: clamp(13.5px, 3.9cqi, 14.5px); text-wrap: pretty;
  & b { font-weight: 650; color: var(--msc-profile-accent); }
}
.msc-profile__facts {
  list-style: none; padding: 0; margin-top: 10px;
  display: flex; flex-wrap: wrap; gap: 4px 14px;
  font-size: 12.5px; color: var(--msc-profile-faint);
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & svg { width: 15px; height: 15px; }
}

/* ---------- stats with the odometer ---------- */
.msc-profile__stats {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-top: 14px; padding: 10px 0;
  border-block: 1px solid var(--msc-profile-line);
  & > div { display: flex; flex-direction: column-reverse; gap: 1px; padding: 0 4px; }
  & > div + div { border-left: 1px solid var(--msc-profile-line); padding-left: 12px; }
  & dt { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--msc-profile-faint); }
  & dd { font-size: clamp(16px, 5cqi, 19px); font-weight: 720; letter-spacing: -.02em; font-variant-numeric: tabular-nums; line-height: 1.2; }
}
.msc-profile__odo { display: inline-flex; height: 1.2em; overflow: hidden; }
.msc-profile__col {
  display: inline-block; height: 1.2em; overflow: hidden;
  & span {
    display: flex; flex-direction: column;
    translate: 0 calc(var(--d, 0) * -1.2em);
    transition: translate .9s var(--msc-profile-spring);
    transition-delay: calc(var(--i, 0) * 70ms);
  }
  & b { display: block; height: 1.2em; font-weight: inherit; }
}
.msc-profile__comma { display: inline-block; }
.msc-profile__fol.is-bump dd { animation: msc-profile-glow 1.2s var(--msc-profile-ease); }

/* ---------- mutuals ---------- */
.msc-profile__mutual {
  display: flex; align-items: center; gap: 10px; margin-top: 12px;
  font-size: 12.5px; line-height: 1.4; color: var(--msc-profile-muted); text-wrap: pretty;
  & b { font-weight: 600; color: var(--msc-profile-ink); }
}
.msc-profile__faces {
  display: inline-flex; flex: none;
  & i {
    display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%;
    font-size: 10.5px; font-weight: 700; font-style: normal;
    color: oklch(0.3 0.06 var(--h)); background: oklch(0.85 0.07 var(--h));
    box-shadow: 0 0 0 2px var(--msc-profile-bg);
    transition: margin .4s var(--msc-profile-spring), translate .4s var(--msc-profile-spring);
    transition-delay: calc(var(--i) * 40ms);
  }
  & i + i { margin-left: -8px; }
}
.msc-profile__mutual:hover .msc-profile__faces i + i { margin-left: 2px; }
.msc-profile__mutual:hover .msc-profile__faces i { translate: 0 -2px; }

/* ---------- unfollow confirm ---------- */
.msc-profile__confirm {
  position: absolute; z-index: 6; right: 12px; top: calc(clamp(76px, 26cqi, 112px) + 8px);
  width: min(260px, calc(100% - 24px));
  padding: 14px; border-radius: 14px;
  background: var(--msc-profile-raise);
  box-shadow: inset 0 0 0 1px var(--msc-profile-line), 0 24px 48px -16px oklch(0 0 0 / .75);
  transform-origin: calc(100% - 40px) 0;
  transition: opacity .18s, scale .35s var(--msc-profile-spring), translate .35s var(--msc-profile-spring), display .35s allow-discrete;
  &[hidden] { display: none; opacity: 0; scale: .94; translate: 0 -6px; }
}
@starting-style {
  .msc-profile__confirm { opacity: 0; scale: .94; translate: 0 -6px; }
}
.msc-profile__ct { font-size: 14px; font-weight: 700; letter-spacing: -.01em; text-wrap: balance; }
.msc-profile__cd { margin-top: 4px; font-size: 12.5px; color: var(--msc-profile-muted); text-wrap: pretty; }
.msc-profile__cbtns {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px;
  & button { height: 34px; border-radius: 999px; font-size: 13px; font-weight: 650; transition: background-color .2s; }
  & [data-do="cancel"] { box-shadow: inset 0 0 0 1px var(--msc-profile-line); &:hover { background: var(--msc-profile-hover); } }
  & [data-do="unfollow"] { color: oklch(0.98 0 0); background: var(--msc-profile-danger); &:hover { background: color-mix(in oklch, var(--msc-profile-danger) 85%, oklch(0 0 0)); } }
}

@container (min-width: 440px) {
  .msc-profile { padding: 0 22px 20px; }
  .msc-profile__cover { margin: 0 -22px; }
  .msc-profile__av { width: 84px; height: 84px; font-size: 26px; }
  .msc-profile__top { margin-top: -40px; }
}
@container (max-width: 320px) {
  .msc-profile { padding-inline: 14px; }
  .msc-profile__cover { margin-inline: -14px; }
  .msc-profile__av { width: 62px; height: 62px; font-size: 19px; }
  .msc-profile__follow { padding: 0 13px; }
  .msc-profile__stats > div + div { padding-left: 9px; }
  .msc-profile__ctas { gap: 4px; }
}

@keyframes msc-profile-drift { to { translate: 6% 4%; } }
@keyframes msc-profile-spin { to { rotate: 1turn; } }
@keyframes msc-profile-draw { to { stroke-dashoffset: 0; } }
@keyframes msc-profile-ring { 0% { rotate: 0deg; } 15% { rotate: 16deg; } 30% { rotate: -13deg; } 45% { rotate: 9deg; } 60% { rotate: -5deg; } 100% { rotate: 0deg; } }
