  .msc-profile__cover i { animation: none; }
  .msc-profile__col span { transition: none; }
  .msc-profile .msc-profile__lbl { translate: none; filter: none; transition: opacity .15s linear; }
  .msc-profile__follow::before { transition: clip-path .2s linear; }
  .msc-profile__follow[data-state="following"] .msc-profile__check { animation: none; stroke-dashoffset: 0; }
  .msc-profile__bell.is-ring svg { animation: none; }
  .msc-profile__faces i { transition: none; }
  .msc-profile__confirm { transition: opacity .15s linear, display .15s allow-discrete; scale: 1; translate: 0 0; }
  .msc-profile__spin { animation-duration: 2s; }
