const $ = (s, el = root) => el.querySelector(s);
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const UID = 'msc-profile-' + Math.random().toString(36).slice(2, 7);

const follow = $('.msc-profile__follow');
const bell = $('.msc-profile__bell');
const copy = $('[data-do="copy"]');
const tip = $('.msc-profile__tip');
const confirmBox = $('.msc-profile__confirm');
const odo = $('.msc-profile__odo');
const odoText = $('.msc-profile__fol .msc-profile__sr');
const live = $('.msc-profile__live');
const name = $('.msc-profile__name');
name.id = UID + '-name';
root.setAttribute('aria-labelledby', name.id);

let followers = 18642, state = 'idle', tipTimer = 0;
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };

/* ---------- odometer: one column per digit, only changed digits roll ---------- */
const STRIP = '<span>' + [...'0123456789'].map((d) => '<b>' + d + '</b>').join('') + '</span>';
let shown = '';
const paintOdo = (n, instant) => {
  const s = n.toLocaleString('en-US');
  const shape = s.replace(/\d/g, '0');
  if (shape !== odo.dataset.shape) {
    odo.dataset.shape = shape;
    odo.innerHTML = [...s].map((ch) => /\d/.test(ch) ? '<span class="msc-profile__col">' + STRIP + '</span>' : '<span class="msc-profile__comma">' + ch + '</span>').join('');
    shown = '';
  }
  const digits = s.replace(/\D/g, ''), prev = shown.replace(/\D/g, '');
  const strips = [...odo.querySelectorAll('.msc-profile__col > span')];
  let k = 0;
  for (let i = strips.length - 1; i >= 0; i--) {
    const st = strips[i];
    if (instant) st.style.transition = 'none';
    st.style.setProperty('--i', digits[i] !== prev[i] ? k++ : 0);
    st.style.setProperty('--d', digits[i]);
  }
  if (instant) { void odo.offsetWidth; strips.forEach((st) => { st.style.transition = ''; }); }
  shown = s;
  odoText.textContent = s + ' followers';
};
paintOdo(followers, true);

/* count up from zero the first time the card is actually seen */
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  if (!es.some((e) => e.isIntersecting)) return;
  io.disconnect();
  if (RM.matches) return;
  const strips = [...odo.querySelectorAll('.msc-profile__col > span')];
  strips.forEach((st) => { st.style.transition = 'none'; st.style.setProperty('--d', 0); });
  void odo.offsetWidth;
  strips.forEach((st, i) => { st.style.transition = ''; st.style.setProperty('--i', i); });
  shown = shown.replace(/\d/g, '0');
  paintOdo(followers, false);
  strips.forEach((st, i) => st.style.setProperty('--i', i));
}, { threshold: 0.4 });
io.observe(root);

/* ---------- follow states ---------- */
const setState = (s) => {
  state = s;
  follow.dataset.state = s;
  follow.setAttribute('aria-pressed', String(s === 'following'));
  follow.setAttribute('aria-busy', String(s === 'pending'));
  if (s === 'following') {
    follow.setAttribute('aria-haspopup', 'dialog');
    follow.setAttribute('aria-label', 'Following Rui Marques. Activate to unfollow');
  } else {
    follow.removeAttribute('aria-haspopup');
    follow.removeAttribute('data-armed');
    follow.setAttribute('aria-label', s === 'pending' ? 'Following…' : 'Follow Rui Marques');
  }
};
const bump = (d) => {
  followers += d;
  paintOdo(followers, false);
  const box = $('.msc-profile__fol');
  box.classList.remove('is-bump');
  void box.offsetWidth;
  box.classList.add('is-bump');
};
follow.addEventListener('click', () => {
  if (state === 'idle') {
    setState('pending');
    later(RM.matches ? 250 : 700, () => {
      setState('following');
      bump(1);
      say('You follow Rui Marques. ' + followers.toLocaleString('en-US') + ' followers');
    });
  } else if (state === 'following') openConfirm();
});
const arm = () => { if (state === 'following') follow.dataset.armed = ''; };
follow.addEventListener('pointerleave', arm);
follow.addEventListener('blur', arm);

/* ---------- unfollow confirm ---------- */
const openConfirm = () => {
  confirmBox.hidden = false;
  follow.setAttribute('aria-expanded', 'true');
  $('[data-do="cancel"]', confirmBox).focus();
};
const closeConfirm = (refocus) => {
  if (confirmBox.hidden) return;
  confirmBox.hidden = true;
  follow.setAttribute('aria-expanded', 'false');
  if (refocus) follow.focus();
};
confirmBox.addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  if (b.dataset.do === 'unfollow') {
    setState('idle');
    bump(-1);
    bell.setAttribute('aria-pressed', 'false');
    closeConfirm(true);
    follow.removeAttribute('aria-expanded');
    say('Unfollowed Rui Marques');
  } else closeConfirm(true);
});
confirmBox.addEventListener('keydown', (e) => {
  if (e.key !== 'Tab') return;
  const bs = [...confirmBox.querySelectorAll('button')];
  const k = bs.indexOf(document.activeElement);
  e.preventDefault();
  bs[(k + (e.shiftKey ? -1 : 1) + bs.length) % bs.length].focus();
});

/* ---------- bell + copy ---------- */
bell.addEventListener('click', () => {
  const on = bell.getAttribute('aria-pressed') !== 'true';
  bell.setAttribute('aria-pressed', String(on));
  bell.setAttribute('aria-label', on ? 'Stop notifications about new posts' : 'Notify me about new posts');
  bell.classList.remove('is-ring');
  if (on) { void bell.offsetWidth; bell.classList.add('is-ring'); }
  say(on ? 'You will be notified when Rui posts' : 'Post notifications off');
});
const showTip = (text, bad) => {
  clearTimeout(tipTimer);
  tip.textContent = text;
  tip.dataset.tone = bad ? 'bad' : '';
  tip.classList.add('is-on');
  tipTimer = later(1700, () => tip.classList.remove('is-on'));
};
copy.addEventListener('click', () => {
  const url = 'fieldnote.example/@ruimarques';
  const ok = () => showTip('Link copied');
  const fail = () => showTip('Couldn’t copy. Try again', true);
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(ok, fail);
    else fail();
  } catch (e) { fail(); }
});

root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && !confirmBox.hidden) { e.preventDefault(); closeConfirm(true); }
});
root.addEventListener('pointerdown', (e) => {
  if (!confirmBox.hidden && !confirmBox.contains(e.target) && !follow.contains(e.target)) closeConfirm(false);
});

css:
@property --msc-stories-a {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

/* Re-theme with --msc-stories-bg, -ink and -accent. */
.msc-stories {
  --msc-stories-bg: oklch(0.175 0.006 95);
  --msc-stories-ink: oklch(0.965 0.006 95);
  --msc-stories-accent: oklch(0.88 0.19 124);

  --msc-stories-raise: color-mix(in oklch, var(--msc-stories-ink) 7%, var(--msc-stories-bg));
  --msc-stories-line: color-mix(in oklch, var(--msc-stories-ink) 12%, transparent);
  --msc-stories-muted: color-mix(in oklch, var(--msc-stories-ink) 66%, var(--msc-stories-bg));
  --msc-stories-faint: color-mix(in oklch, var(--msc-stories-ink) 42%, var(--msc-stories-bg));
  --msc-stories-seen: color-mix(in oklch, var(--msc-stories-ink) 26%, var(--msc-stories-bg));
  --msc-stories-ring: color-mix(in oklch, var(--msc-stories-accent) 80%, transparent);
  --msc-stories-ease: cubic-bezier(.22, 1, .36, 1);
  --msc-stories-io: cubic-bezier(.65, 0, .35, 1);
  --msc-stories-spring: linear(0, 0.09 4%, 0.35 9%, 0.73 17%, 1 25%, 1.08 32%, 1.06 40%, 1.01 52%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: 470px;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  border-radius: 20px;
  overflow: clip;
  color: var(--msc-stories-ink);
  background: var(--msc-stories-bg);
  box-shadow: inset 0 0 0 1px var(--msc-stories-line);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .msc-stories { --msc-stories-spring: cubic-bezier(.34, 1.45, .5, 1); }
}
:where(.msc-stories) *, :where(.msc-stories) *::before, :where(.msc-stories) *::after { box-sizing: border-box; }
:where(.msc-stories) :is(button, input) { font: inherit; color: inherit; }
:where(.msc-stories) button { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.msc-stories) :focus-visible { outline: 2px solid var(--msc-stories-ring); outline-offset: 2px; }
:where(.msc-stories) :is(h3, p, ul, form) { margin: 0; }
.msc-stories svg { fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.msc-stories__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.msc-stories__head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 16px 4px;
}
.msc-stories__h { font-size: 17px; font-weight: 750; letter-spacing: -.02em; }
.msc-stories__all {
  display: inline-flex; align-items: center; gap: 5px; padding: 5px 10px 5px 8px; border-radius: 999px;
  font-size: 12.5px; font-weight: 650; color: var(--msc-stories-bg); background: var(--msc-stories-accent);
  transition: scale .3s var(--msc-stories-spring), background-color .2s;
  & svg { width: 14px; height: 14px; fill: currentColor; stroke-width: 1.5; }
  &:hover { background: color-mix(in oklch, var(--msc-stories-accent) 85%, oklch(1 0 0)); }
  &:active { scale: .95; }
}

/* ---------- the row ---------- */
.msc-stories__row {
  list-style: none; padding: 8px 12px 12px;
  display: grid; grid-auto-flow: column; grid-auto-columns: 70px; gap: 6px;
  overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity; scrollbar-width: none;
  scroll-padding-inline: 12px;
  &::-webkit-scrollbar { display: none; }
  & > li { scroll-snap-align: start; }
}
.msc-stories__bub {
  display: grid; justify-items: center; gap: 5px; width: 70px; padding: 2px 0; border-radius: 12px;
  font-size: 11.5px; color: var(--msc-stories-muted);
  &:focus-visible { outline-offset: 0; }
  &[aria-current="true"] .msc-stories__nm { color: var(--msc-stories-ink); }
}
.msc-stories__ring {
  position: relative; width: 64px; height: 64px; display: grid; place-items: center;
  transition: scale .35s var(--msc-stories-spring);
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; rotate: -90deg; transition: rotate .7s var(--msc-stories-ease); }
  & circle { stroke-width: 2.6; stroke-linecap: round; transition: stroke .5s var(--msc-stories-ease); }
  & circle[data-seen="false"] { stroke: var(--msc-stories-accent); }
  & circle[data-seen="true"] { stroke: var(--msc-stories-seen); stroke-width: 1.8; }
}
.msc-stories__bub:hover .msc-stories__ring { scale: 1.05; }
.msc-stories__bub:hover .msc-stories__ring svg { rotate: -60deg; }
.msc-stories__bub:active .msc-stories__ring { scale: .95; }
.msc-stories__av {
  display: grid; place-items: center; width: 54px; height: 54px; border-radius: 50%;
  font-size: 16px; font-weight: 750; letter-spacing: -.01em;
  color: oklch(0.28 0.06 var(--h)); background: radial-gradient(circle at 30% 25%, oklch(0.93 0.06 var(--h)), oklch(0.78 0.1 var(--h)));
}
.msc-stories__nm { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; transition: color .2s; }
.msc-stories__plus {
  position: absolute; right: 1px; bottom: 1px;
  display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%;
  color: var(--msc-stories-bg); background: var(--msc-stories-accent); box-shadow: 0 0 0 3px var(--msc-stories-bg);
  & svg { width: 12px; height: 12px; stroke-width: 3; }
}
.msc-stories__bub[data-me]:not([data-me="posted"]) .msc-stories__av {
  color: var(--msc-stories-faint); background: var(--msc-stories-raise);
  & svg { width: 26px; height: 26px; stroke-width: 1.6; }
}
.msc-stories__bub[data-me="uploading"] .msc-stories__ring::before {
  content: ""; position: absolute; inset: 0; border-radius: 50%;
  background: conic-gradient(from var(--msc-stories-a), transparent 0 55%, var(--msc-stories-accent));
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2.5px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2.5px));
  animation: msc-stories-turn .9s linear infinite;
}
.msc-stories__bub[data-me="uploading"] .msc-stories__plus { scale: 0; transition: scale .25s; }

/* ---------- preview stage ---------- */
.msc-stories__stage { padding: 0 12px 12px; min-height: 0; display: grid; }
.msc-stories__preview {
  position: relative; display: grid; min-height: 0; border-radius: 16px; overflow: hidden; text-align: left;
  box-shadow: 0 0 0 1px var(--msc-stories-line);
  &:focus-visible { outline-offset: 3px; }
  & .msc-stories__card { transition: scale .6s var(--msc-stories-ease), filter .4s; }
  &:hover .msc-stories__card { scale: 1.03; }
  & .msc-stories__card.is-in { animation: msc-stories-swap .5s var(--msc-stories-ease) both; }
}
.msc-stories__pinfo {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 2;
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 26px 12px 12px;
  background: linear-gradient(transparent, oklch(0 0 0 / .62));
  & .msc-stories__mini { width: 32px; height: 32px; font-size: 11px; box-shadow: 0 0 0 2px var(--msc-stories-accent); }
  & b { display: block; font-size: 13.5px; font-weight: 650; }
  & small { display: block; font-size: 11.5px; color: oklch(1 0 0 / .72); font-variant-numeric: tabular-nums; }
}
.msc-stories__mini {
  display: grid; place-items: center; border-radius: 50%; font-weight: 750;
  color: oklch(0.28 0.06 var(--h)); background: oklch(0.85 0.08 var(--h));
}
.msc-stories__watch {
  display: inline-flex; align-items: center; gap: 5px; padding: 6px 11px 6px 9px; border-radius: 999px;
  font-size: 12px; font-weight: 700; color: var(--msc-stories-bg); background: oklch(1 0 0 / .92);
  & svg { width: 13px; height: 13px; fill: currentColor; stroke-width: 1.4; }
}

/* ---------- story cards (shared by preview and viewer) ---------- */
.msc-stories__card {
  --msc-stories-c1: oklch(0.6 0.1 30);
  --msc-stories-c2: oklch(0.3 0.05 30);
  position: relative; container-type: inline-size;
  display: flex; flex-direction: column; justify-content: flex-end; gap: 4px;
  min-height: 0; height: 100%; padding: 16px 16px 64px;
  overflow: hidden; color: oklch(0.99 0 0);
  background: linear-gradient(170deg, var(--msc-stories-c1), var(--msc-stories-c2));
  & > * { position: relative; z-index: 1; }
}
.msc-stories__card > .msc-stories__art { position: absolute; inset: 0; z-index: 0; }
.msc-stories__kick { font-size: clamp(10px, 3.4cqi, 12.5px); font-weight: 650; letter-spacing: .1em; text-transform: uppercase; opacity: .85; }
.msc-stories__title { font-size: clamp(22px, 11cqi, 40px); font-weight: 800; letter-spacing: -.035em; line-height: .98; text-wrap: balance; }
.msc-stories__foot { margin-top: 4px; font-size: clamp(11.5px, 3.8cqi, 14px); opacity: .85; text-wrap: pretty; font-variant-numeric: tabular-nums; }

.msc-stories__card[data-k="awning"] {
  --msc-stories-c1: oklch(0.46 0.07 200); --msc-stories-c2: oklch(0.3 0.05 210);
  & .msc-stories__art {
    background: repeating-linear-gradient(90deg, oklch(0.7 0.16 30) 0 22px, oklch(0.95 0.03 85) 22px 44px);
    -webkit-mask: linear-gradient(#000, #000) 0 0 / 100% 42% no-repeat, radial-gradient(circle at 50% 0, #000 10.5px, transparent 11px) 0 42% / 22px 12px repeat-x;
    mask: linear-gradient(#000, #000) 0 0 / 100% 42% no-repeat, radial-gradient(circle at 50% 0, #000 10.5px, transparent 11px) 0 42% / 22px 12px repeat-x;
    filter: drop-shadow(0 6px 6px oklch(0 0 0 / .25));
  }
}
.msc-stories__card[data-k="tiles"] {
  --msc-stories-c1: oklch(0.42 0.12 255); --msc-stories-c2: oklch(0.3 0.1 260);
  & .msc-stories__art {
    background:
      radial-gradient(circle at 50% 50%, oklch(0.95 0.02 250) 0 5px, transparent 5.5px),
      conic-gradient(from 45deg at 50% 50%, oklch(0.55 0.13 255) 0 25%, oklch(0.93 0.02 240) 0 50%, oklch(0.55 0.13 255) 0 75%, oklch(0.93 0.02 240) 0),
      oklch(0.93 0.02 240);
    background-size: 36px 36px;
    -webkit-mask: linear-gradient(#000 40%, transparent 72%); mask: linear-gradient(#000 40%, transparent 72%);
  }
}
.msc-stories__card[data-k="record"] {
  --msc-stories-c1: oklch(0.26 0.02 60); --msc-stories-c2: oklch(0.16 0.01 60);
  & .msc-stories__art {
    background:
      radial-gradient(circle at 62% 34%, oklch(0.82 0.15 70) 0 11%, oklch(0.2 0 0) 11.5% 12.5%, transparent 13%),
      repeating-radial-gradient(circle at 62% 34%, oklch(0.14 0 0) 0 2px, oklch(0.2 0 0) 2px 3px),
      transparent;
    -webkit-mask: radial-gradient(circle at 62% 34%, #000 0 46%, transparent 46.4%); mask: radial-gradient(circle at 62% 34%, #000 0 46%, transparent 46.4%);
    animation: msc-stories-spin 7s linear infinite; transform-origin: 62% 34%;
  }
}
.msc-stories__card[data-k="topo"] {
  --msc-stories-c1: oklch(0.52 0.09 150); --msc-stories-c2: oklch(0.32 0.06 160);
  & .msc-stories__art {
    background: repeating-radial-gradient(ellipse 80% 60% at 70% 30%, transparent 0 12px, oklch(1 0 0 / .22) 12px 13.5px);
  }
}
.msc-stories__card[data-k="sun"] {
  --msc-stories-c1: oklch(0.78 0.12 60); --msc-stories-c2: oklch(0.45 0.13 20);
  & .msc-stories__art {
    background:
      radial-gradient(circle at 50% 46%, oklch(0.97 0.08 95) 0 16%, transparent 16.5%),
      repeating-linear-gradient(transparent 0 7px, oklch(0.45 0.13 20 / .55) 7px 9px) 0 54% / 100% 46% no-repeat,
      linear-gradient(oklch(0.84 0.1 70), oklch(0.72 0.15 40) 54%, oklch(0.4 0.1 240) 54.2%, oklch(0.28 0.08 250));
  }
}
.msc-stories__card[data-k="grid"] {
  --msc-stories-c1: oklch(0.95 0.02 90); --msc-stories-c2: oklch(0.9 0.03 85);
  color: oklch(0.25 0.03 60);
  & .msc-stories__art {
    background:
      linear-gradient(90deg, oklch(0.6 0.1 240 / .18) 1px, transparent 1px) 0 0 / 18px 18px,
      linear-gradient(oklch(0.6 0.1 240 / .18) 1px, transparent 1px) 0 0 / 18px 18px,
      radial-gradient(circle at 70% 28%, oklch(0.55 0.09 50) 0 18%, oklch(0.42 0.07 45) 18.5% 21%, transparent 21.5%);
  }
  & .msc-stories__title { font-family: ui-monospace, Menlo, monospace; font-weight: 700; letter-spacing: -.04em; }
}
.msc-stories__card[data-k="type"] {
  --msc-stories-c1: oklch(0.88 0.19 124); --msc-stories-c2: oklch(0.8 0.2 130);
  color: oklch(0.18 0.03 130);
  justify-content: center; padding-bottom: 40px;
  & .msc-stories__title { font-size: clamp(30px, 19cqi, 70px); text-transform: uppercase; line-height: .86; letter-spacing: -.05em; }
}
.msc-stories__card[data-k="hex"] {
  --msc-stories-c1: oklch(0.8 0.14 85); --msc-stories-c2: oklch(0.62 0.15 65);
  color: oklch(0.2 0.04 60);
  & .msc-stories__art {
    --msc-stories-hx: oklch(0.86 0.13 90);
    background:
      radial-gradient(circle farthest-side at 0 50%, transparent 92%, oklch(0.55 0.13 60 / .45) 94%, transparent) 0 0 / 28px 48px,
      radial-gradient(circle farthest-side at 100% 50%, transparent 92%, oklch(0.55 0.13 60 / .45) 94%, transparent) 14px 24px / 28px 48px;
    -webkit-mask: linear-gradient(#000 30%, transparent 75%); mask: linear-gradient(#000 30%, transparent 75%);
  }
}
.msc-stories__card[data-k="mono"] {
  --msc-stories-c1: oklch(0.24 0.02 150); --msc-stories-c2: oklch(0.18 0.015 150);
  color: var(--msc-stories-accent);
  & .msc-stories__title { font-family: ui-monospace, Menlo, monospace; font-weight: 700; letter-spacing: -.03em; }
  & .msc-stories__art { background: repeating-linear-gradient(transparent 0 3px, oklch(1 0 0 / .03) 3px 4px); }
}

/* ---------- viewer ---------- */
.msc-stories__viewer {
  position: absolute; inset: 0; z-index: 10;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  background: oklch(0.12 0.005 95);
  clip-path: circle(150% at var(--msc-stories-cx, 50%) var(--msc-stories-cy, 20%));
  transition: clip-path .55s var(--msc-stories-io), opacity .2s, display .55s allow-discrete;
  outline: none;
  &[hidden] { display: none; clip-path: circle(0 at var(--msc-stories-cx, 50%) var(--msc-stories-cy, 20%)); }
}
@starting-style {
  .msc-stories__viewer { clip-path: circle(0 at var(--msc-stories-cx, 50%) var(--msc-stories-cy, 20%)); }
}
.msc-stories__frame {
  grid-row: 1 / -1; grid-column: 1;
  position: relative; display: grid; min-height: 0;
  & .msc-stories__card { grid-area: 1 / 1; padding-top: 72px; padding-bottom: 82px; }
  & .msc-stories__card.is-next { animation: msc-stories-in-next .45s var(--msc-stories-ease) both; }
  & .msc-stories__card.is-prev { animation: msc-stories-in-prev .45s var(--msc-stories-ease) both; }
  & .msc-stories__card.is-person { animation: msc-stories-in-person .6s var(--msc-stories-ease) both; }
  & .msc-stories__card.is-out { animation: msc-stories-out .35s var(--msc-stories-ease) both; }
}
.msc-stories__frame::after { /* legibility under the chrome */
  content: ""; position: absolute; inset: 0; z-index: 2; pointer-events: none;
  background: linear-gradient(oklch(0 0 0 / .5), transparent 22%, transparent 76%, oklch(0 0 0 / .55));
}
.msc-stories__bars {
  grid-row: 1; grid-column: 1; position: relative; z-index: 4;
  display: flex; gap: 4px; padding: 10px 12px 0;
  & i { flex: 1; height: 3px; border-radius: 2px; overflow: hidden; background: oklch(1 0 0 / .32); }
  & b { display: block; height: 100%; background: oklch(1 0 0); transform-origin: 0 50%; scale: var(--p, 0) 1; }
}
.msc-stories__vhead {
  grid-row: 1; grid-column: 1; position: relative; z-index: 4; align-self: start;
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center; gap: 8px;
  padding: 22px 8px 0 12px;
}
.msc-stories__vav { width: 32px; height: 32px; font-size: 11px; display: grid; place-items: center; border-radius: 50%; font-weight: 750; color: oklch(0.28 0.06 var(--h)); background: oklch(0.85 0.08 var(--h)); }
.msc-stories__vname {
  display: flex; align-items: baseline; gap: 6px; min-width: 0;
  font-size: 13px; text-shadow: 0 1px 2px oklch(0 0 0 / .4);
  & b { font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & time { font-size: 12px; color: oklch(1 0 0 / .72); font-variant-numeric: tabular-nums; flex: none; }
}
.msc-stories__vbtn {
  display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; color: oklch(1 0 0);
  transition: background-color .2s, scale .3s var(--msc-stories-spring), color .2s;
  & svg { width: 20px; height: 20px; }
  &:hover { background: oklch(1 0 0 / .14); }
  &:active { scale: .9; }
  &:disabled { opacity: .4; cursor: default; }
}
.msc-stories__vbtn[data-do="pause"] .msc-stories__pl { display: none; }
.msc-stories__vbtn[data-do="pause"][aria-pressed="true"] { & .msc-stories__pl { display: block; fill: currentColor; } & .msc-stories__pz { display: none; } }
.msc-stories__vbtn[data-do="like"][aria-pressed="true"] { color: oklch(0.68 0.21 15); & svg { fill: currentColor; animation: msc-stories-pop .45s var(--msc-stories-spring); } }
.msc-stories__tap {
  grid-row: 2; grid-column: 1; z-index: 3; align-self: stretch; margin: 8px 0 64px;
  &[data-do="prev"] { justify-self: start; width: 32%; }
  &[data-do="next"] { justify-self: end; width: 68%; }
  &:focus-visible { outline-offset: -4px; border-radius: 12px; }
}
.msc-stories__reply {
  grid-row: 2; grid-column: 1; z-index: 4; align-self: end;
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 4px;
  padding: 0 8px 12px 12px;
  & input {
    height: 40px; min-width: 0; padding: 0 16px; border-radius: 999px; border: 0;
    color: oklch(1 0 0); background: oklch(0 0 0 / .25);
    box-shadow: inset 0 0 0 1px oklch(1 0 0 / .45);
    -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
    &::placeholder { color: oklch(1 0 0 / .75); }
    &:focus { outline: none; box-shadow: inset 0 0 0 1.5px oklch(1 0 0 / .9); }
  }
}
.msc-stories__send:not(:disabled) { color: var(--msc-stories-accent); }
.msc-stories__toast {
  position: absolute; left: 50%; bottom: 66px; z-index: 6;
  padding: 7px 12px; border-radius: 999px;
  font-size: 12.5px; font-weight: 650; white-space: nowrap;
  color: var(--msc-stories-bg); background: oklch(1 0 0);
  translate: -50% 8px; opacity: 0; pointer-events: none;
  transition: opacity .2s, translate .35s var(--msc-stories-spring);
  &.is-on { opacity: 1; translate: -50% 0; }
}
.msc-stories__viewer[data-held] :is(.msc-stories__bars, .msc-stories__vhead, .msc-stories__reply) { opacity: 0; transition: opacity .25s; }
.msc-stories__viewer :is(.msc-stories__bars, .msc-stories__vhead, .msc-stories__reply) { transition: opacity .25s; }

@container (min-width: 460px) {
  .msc-stories__row { grid-auto-columns: 78px; gap: 8px; padding-inline: 16px; }
  .msc-stories__head { padding-inline: 20px; }
  .msc-stories__stage { padding: 0 16px 16px; }
}

@keyframes msc-stories-turn { to { --msc-stories-a: 360deg; } }
@keyframes msc-stories-spin { to { rotate: 1turn; } }
@keyframes msc-stories-swap { from { opacity: 0; filter: blur(6px); scale: 1.06; } }
@keyframes msc-stories-in-next { from { opacity: 0; translate: 6% 0; } }
@keyframes msc-stories-in-prev { from { opacity: 0; translate: -6% 0; } }
@keyframes msc-stories-in-person { from { opacity: 0; scale: .9; filter: blur(4px); border-radius: 24px; } }
@keyframes msc-stories-out { to { opacity: 0; scale: .96; } }
@keyframes msc-stories-pop { from { scale: .4; } }

@media (prefers-reduced-motion: reduce) {
  .msc-stories__viewer, .msc-stories__viewer[hidden] { clip-path: none; transition: opacity .2s linear, display .2s allow-discrete; }
  .msc-stories__viewer[hidden] { opacity: 0; }
  .msc-stories__frame .msc-stories__card:is(.is-next, .is-prev, .is-person) { animation: msc-stories-fade .25s linear both; }
  .msc-stories__frame .msc-stories__card.is-out { animation: none; opacity: 0; }
  .msc-stories__card[data-k="record"] .msc-stories__art { animation: none; }
  .msc-stories__bub[data-me="uploading"] .msc-stories__ring::before { animation-duration: 3s; }
  .msc-stories__ring, .msc-stories__ring svg, .msc-stories__preview .msc-stories__card { transition: none; }
  .msc-stories__bub:hover .msc-stories__ring { scale: 1; }
  .msc-stories__preview .msc-stories__card.is-in { animation: msc-stories-fade .2s linear both; }
  .msc-stories__vbtn[data-do="like"][aria-pressed="true"] svg { animation: none; }
}
@keyframes msc-stories-fade { from { opacity: 0; } }

js:
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const DUR = 5200;

/* 11 stories from six people, plus yours once you post one */
const P = [
  { id: 'me', name: 'Your story', full: 'You', hue: 125, me: 'empty', stories: [] },
  { id: 'ana', name: 'ana.duarte', full: 'Ana Duarte', hue: 25, stories: [
    { k: 'awning', kick: 'Feira da Ladra · 7:40', title: 'Saturday haul', foot: 'Got there before the crates opened.', ago: 120 },
    { k: 'tiles', kick: 'Stall 41', title: 'Found a 1962 Olivetti', foot: '€40, ribbon included, one sticky “e”.', ago: 112 },
    { k: 'sun', kick: 'Cais do Sodré', title: 'Last swim of the season', foot: 'Water 19°, air 24°.', ago: 64 }] },
  { id: 'kwame', name: 'kwame.fm', full: 'Kwame Asante', hue: 150, stories: [
    { k: 'record', kick: 'Studio 2', title: 'Side B, all afternoon', foot: 'Sampling the brass section from track 4.', ago: 300, seen: true },
    { k: 'type', kick: 'Friday · 21:00', title: 'New mix drops', foot: '74 minutes, no skips.', ago: 45 }] },
  { id: 'mira', name: 'mira.holt', full: 'Mira Holt', hue: 200, stories: [
    { k: 'topo', kick: 'Ridge loop', title: '14.2 km, 812 m up', foot: 'Moving time 3:41. Fog lifted at the saddle.', ago: 95 }] },
  { id: 'jun', name: 'junpark', full: 'Jun Park', hue: 60, stories: [
    { k: 'grid', kick: 'Pour-over #3', title: '15 g · 250 ml · 3:10', foot: 'Washed Ethiopian, a little bright.', ago: 400, seen: true },
    { k: 'mono', kick: 'Tuesday standup', title: 'Deploy freeze lifted', foot: 'Merge queue reopens at 14:00.', ago: 38 }] },
  { id: 'selin', name: 'selin.k', full: 'Selin Kaya', hue: 330, stories: [
    { k: 'sun', kick: 'Kadıköy · 06:12', title: 'Ferry light', foot: 'Third morning in a row.', ago: 210 },
    { k: 'type', kick: 'Portfolio reviews', title: 'Six slots open', foot: 'Thursday, 30 minutes each.', ago: 150 }] },
  { id: 'odile', name: 'odile.m', full: 'Odile Marchetti', hue: 85, stories: [
    { k: 'hex', kick: 'Rooftop hive 3', title: '41 kg this summer', foot: 'Lime blossom, mostly.', ago: 520, seen: true }] }
];
const MINE = { k: 'mono', kick: 'Just now', title: 'Shipping notes are up', foot: 'Changelog 4.12 is in the team wiki.', ago: 0 };

const row = $('.msc-stories__row');
const preview = $('.msc-stories__preview');
const viewer = $('.msc-stories__viewer');
const frame = $('.msc-stories__frame');
const bars = $('.msc-stories__bars');
const input = $('.msc-stories__reply input');
const sendBtn = $('.msc-stories__send');
const pauseBtn = $('[data-do="pause"]');
const likeBtn = $('[data-do="like"]');
const toast = $('.msc-stories__toast');
const live = $('.msc-stories__sr');
const backdrop = [$('.msc-stories__head'), $('.msc-stories__row'), $('.msc-stories__stage')];
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const esc = (t) => t.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const ago = (m) => (m < 1 ? 'now' : m < 60 ? m + 'm' : Math.round(m / 60) + 'h');
const ini = (p) => p.id === 'me' ? 'You' : p.full.split(' ').map((w) => w[0]).join('');
const unseen = (p) => p.stories.filter((s) => !s.seen).length;

/* ---------- ring: one dash per story, gaps between ---------- */
const ringSVG = (p) => {
  const n = p.stories.length;
  if (!n) return '<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="30" pathLength="100" data-seen="true" stroke-dasharray="2 3"></circle></svg>';
  const gap = n > 1 ? 4 : 0, seg = (100 - gap * n) / n;
  return '<svg viewBox="0 0 64 64" aria-hidden="true">' + p.stories.map((s, i) =>
    '<circle cx="32" cy="32" r="30" pathLength="100" data-seen="' + !!s.seen + '" stroke-dasharray="' + (n > 1 ? seg.toFixed(2) + ' ' + (100 - seg).toFixed(2) : '100 0') +
    '" stroke-dashoffset="' + (-(i * (seg + gap) + gap / 2)).toFixed(2) + '"></circle>').join('') + '</svg>';
};
const bubbleLabel = (p) => p.id === 'me'
  ? (p.me === 'empty' ? 'Add to your story' : p.me === 'uploading' ? 'Posting your story' : 'Your story, 1 story')
  : p.full + ', ' + p.stories.length + (p.stories.length === 1 ? ' story' : ' stories') + (unseen(p) ? ', ' + unseen(p) + ' new' : ', all seen');
const paintRow = () => {
  row.innerHTML = P.map((p, i) =>
    '<li><button type="button" class="msc-stories__bub" data-i="' + i + '" tabindex="' + (i === focusI ? 0 : -1) + '"' + (p.id === 'me' ? ' data-me="' + p.me + '"' : '') +
    ' aria-label="' + esc(bubbleLabel(p)) + '"' + (i === peek ? ' aria-current="true"' : '') + '>' +
    '<span class="msc-stories__ring">' + ringSVG(p) + '<span class="msc-stories__av" style="--h:' + p.hue + '">' + (p.id === 'me' && p.me !== 'posted' ? '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="9" r="3.5"/><path d="M5.5 19.5a6.5 6.5 0 0 1 13 0"/></svg>' : ini(p)) + '</span>' +
    (p.id === 'me' && p.me !== 'posted' ? '<span class="msc-stories__plus"><svg viewBox="0 0 24 24"><path d="M12 6.5v11M6.5 12h11"/></svg></span>' : '') + '</span>' +
    '<span class="msc-stories__nm">' + esc(p.name) + '</span></button></li>').join('');
};
const paintRing = (i) => {
  const b = $('.msc-stories__bub[data-i="' + i + '"]', row);
  if (!b) return;
  const p = P[i];
  $$('circle', b).forEach((c, k) => { if (p.stories[k]) c.dataset.seen = String(!!p.stories[k].seen); });
  b.setAttribute('aria-label', bubbleLabel(p));
};

/* ---------- cards ---------- */
const card = (s) => '<div class="msc-stories__card" data-k="' + s.k + '"><span class="msc-stories__art" aria-hidden="true"></span>' +
  '<p class="msc-stories__kick">' + esc(s.kick) + '</p><p class="msc-stories__title">' + esc(s.title) + '</p><p class="msc-stories__foot">' + esc(s.foot) + '</p></div>';

let focusI = 1, peek = 1;
const paintPreview = (i) => {
  const p = P[i];
  if (!p.stories.length) return;
  peek = i;
  $$('.msc-stories__bub', row).forEach((b) => b.toggleAttribute('aria-current', +b.dataset.i === i));
  const s = p.stories.find((x) => !x.seen) || p.stories[0];
  const n = unseen(p);
  preview.innerHTML = card(s) +
    '<span class="msc-stories__pinfo"><span class="msc-stories__mini" style="--h:' + p.hue + '" aria-hidden="true">' + ini(p) + '</span>' +
    '<span><b>' + esc(p.full) + '</b><small>' + (n ? n + ' new · ' : 'Seen · ') + ago(s.ago) + ' ago</small></span>' +
    '<span class="msc-stories__watch" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 5.5v13l10-6.5Z"/></svg>Watch</span></span>';
  preview.setAttribute('aria-label', 'Watch ' + p.full + '’s stories');
  const c = $('.msc-stories__card', preview);
  c.classList.add('is-in');
};

/* ---------- viewer state + one rAF clock ---------- */
let open = false, pi = 0, si = 0, t = 0, paused = false, held = false, typing = false, onscreen = true, raf = 0, last = 0, holdTimer = 0, didHold = false;
const running = () => open && !paused && !held && !typing && onscreen && !document.hidden;
const tick = (now) => {
  if (!root.isConnected) return;
  if (!running()) { raf = 0; last = 0; return; }
  const dt = last ? Math.min(64, now - last) : 0;
  last = now;
  t += dt;
  const b = bars.children[si];
  if (b) b.firstElementChild.style.setProperty('--p', Math.min(1, t / DUR).toFixed(4));
  if (t >= DUR) { step(1); }
  raf = requestAnimationFrame(tick);
};
const kick = () => { if (!raf && running()) raf = requestAnimationFrame(tick); };

const paintBars = () => {
  const p = P[pi];
  bars.innerHTML = p.stories.map((_, i) => '<i><b style="--p:' + (i < si ? 1 : 0) + '"></b></i>').join('');
};
const show = (how) => {
  const p = P[pi], s = p.stories[si];
  t = 0;
  s.seen = true;
  paintRing(pi);
  const old = $('.msc-stories__card', frame);
  frame.insertAdjacentHTML('beforeend', card(s));
  const fresh = frame.lastElementChild;
  if (how) fresh.classList.add(how);
  if (old) {
    old.classList.add('is-out');
    later(RM.matches ? 0 : 340, () => old.remove());
  }
  [...bars.children].forEach((b, i) => b.firstElementChild.style.setProperty('--p', i < si ? 1 : 0));
  const av = $('.msc-stories__vav');
  av.textContent = ini(p);
  av.style.setProperty('--h', p.hue);
  $('.msc-stories__vname b').textContent = p.full;
  $('.msc-stories__vname time').textContent = ago(s.ago);
  viewer.setAttribute('aria-label', 'Stories by ' + p.full);
  input.placeholder = p.id === 'me' ? 'Replies are off for your story' : 'Reply to ' + p.full.split(' ')[0] + '…';
  input.disabled = p.id === 'me';
  likeBtn.setAttribute('aria-pressed', String(!!s.liked));
  likeBtn.disabled = p.id === 'me';
  say('Story ' + (si + 1) + ' of ' + p.stories.length + ' by ' + p.full + ': ' + s.title + '. ' + s.foot);
  last = 0;
  kick();
};
const nextPerson = (from, dir) => {
  for (let i = from + dir; i >= 0 && i < P.length; i += dir) if (P[i].stories.length) return i;
  return -1;
};
const step = (dir) => {
  const p = P[pi];
  if (dir > 0 && si < p.stories.length - 1) { si++; show('is-next'); return; }
  if (dir < 0 && si > 0) { si--; show('is-prev'); return; }
  if (dir < 0 && t > 900) { show(null); return; }
  const np = nextPerson(pi, dir);
  if (np < 0) { if (dir > 0) close(); else show(null); return; }
  pi = np;
  si = dir > 0 ? Math.max(0, P[pi].stories.findIndex((s) => !s.seen)) : P[pi].stories.length - 1;
  if (si < 0) si = 0;
  paintBars();
  show('is-person');
};

let opener = null;
const openAt = (i, from) => {
  const p = P[i];
  if (!p.stories.length) return;
  opener = from || $('.msc-stories__bub[data-i="' + i + '"]', row);
  const rr = root.getBoundingClientRect(), br = (opener || preview).getBoundingClientRect();
  viewer.style.setProperty('--msc-stories-cx', (br.left + br.width / 2 - rr.left).toFixed(0) + 'px');
  viewer.style.setProperty('--msc-stories-cy', (br.top + Math.min(br.height, 64) / 2 - rr.top).toFixed(0) + 'px');
  pi = i;
  si = Math.max(0, p.stories.findIndex((s) => !s.seen));
  frame.innerHTML = '';
  paused = false; held = false; typing = false;
  pauseBtn.setAttribute('aria-pressed', 'false');
  pauseBtn.setAttribute('aria-label', 'Pause');
  viewer.hidden = false;
  open = true;
  backdrop.forEach((el) => { el.inert = true; });
  paintBars();
  show(null);
  viewer.focus({ preventScroll: true });
};
const close = () => {
  if (!open) return;
  open = false;
  const b = $('.msc-stories__bub[data-i="' + pi + '"]', row);
  if (b) {
    const rr = root.getBoundingClientRect(), br = b.getBoundingClientRect();
    viewer.style.setProperty('--msc-stories-cx', (br.left + br.width / 2 - rr.left).toFixed(0) + 'px');
    viewer.style.setProperty('--msc-stories-cy', (br.top + 32 - rr.top).toFixed(0) + 'px');
  }
  viewer.hidden = true;
  backdrop.forEach((el) => { el.inert = false; });
  input.value = '';
  sendBtn.disabled = true;
  paintRow();
  paintPreview(P[pi].stories.length ? pi : peek);
  const back = $('.msc-stories__bub[data-i="' + pi + '"]', row);
  if (back) { focusI = pi; $$('.msc-stories__bub', row).forEach((x) => { x.tabIndex = x === back ? 0 : -1; }); back.focus({ preventScroll: true }); }
  say('Stories closed');
};
const setPaused = (v) => {
  paused = v;
  pauseBtn.setAttribute('aria-pressed', String(v));
  pauseBtn.setAttribute('aria-label', v ? 'Play' : 'Pause');
  if (!v) { last = 0; kick(); }
};

/* ---------- your story: empty → uploading → posted ---------- */
const postMine = () => {
  const me = P[0];
  if (me.me !== 'empty') return;
  me.me = 'uploading';
  paintRow();
  $('.msc-stories__bub[data-i="0"]', row).focus({ preventScroll: true });
  say('Posting your story');
  later(RM.matches ? 600 : 1500, () => {
    me.me = 'posted';
    me.stories = [{ ...MINE }];
    paintRow();
    $('.msc-stories__bub[data-i="0"]', row).focus({ preventScroll: true });
    say('Your story is live');
  });
};

/* ---------- events ---------- */
row.addEventListener('click', (e) => {
  const b = e.target.closest('.msc-stories__bub');
  if (!b) return;
  const i = +b.dataset.i;
  if (P[i].id === 'me' && P[i].me === 'uploading') { say('Still posting your story'); return; }
  if (P[i].id === 'me' && P[i].me !== 'posted') { postMine(); return; }
  openAt(i, b);
});
row.addEventListener('keydown', (e) => {
  const b = e.target.closest('.msc-stories__bub');
  if (!b) return;
  const bs = $$('.msc-stories__bub', row), k = bs.indexOf(b);
  const to = { ArrowRight: k + 1, ArrowLeft: k - 1, Home: 0, End: bs.length - 1 }[e.key];
  if (to === undefined || !bs[to]) return;
  e.preventDefault();
  bs.forEach((x) => { x.tabIndex = -1; });
  bs[to].tabIndex = 0;
  focusI = to;
  bs[to].focus();
  bs[to].scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
});
const peekFrom = (e) => {
  const b = e.target.closest && e.target.closest('.msc-stories__bub');
  if (b && P[+b.dataset.i].stories.length && +b.dataset.i !== peek) paintPreview(+b.dataset.i);
};
row.addEventListener('pointerover', peekFrom);
row.addEventListener('focusin', peekFrom);
preview.addEventListener('click', () => openAt(peek, preview));
$('.msc-stories__all').addEventListener('click', (e) => {
  const i = P.findIndex((p) => p.id !== 'me' && unseen(p)) > -1 ? P.findIndex((p) => p.id !== 'me' && unseen(p)) : 1;
  openAt(i, e.currentTarget);
});

viewer.addEventListener('click', (e) => {
  const b = e.target.closest('[data-do]');
  if (!b) return;
  const d = b.dataset.do;
  if (d === 'close') close();
  else if (d === 'pause') setPaused(!paused);
  else if (d === 'next' || d === 'prev') { if (didHold) { didHold = false; return; } step(d === 'next' ? 1 : -1); }
  else if (d === 'like') {
    const s = P[pi].stories[si];
    s.liked = !s.liked;
    likeBtn.setAttribute('aria-pressed', String(s.liked));
    say(s.liked ? 'Liked' : 'Like removed');
  }
});
/* press and hold anywhere on the story to pause; release resumes */
viewer.addEventListener('pointerdown', (e) => {
  if (!e.target.closest('.msc-stories__tap')) return;
  didHold = false;
  holdTimer = later(220, () => { held = true; didHold = true; viewer.dataset.held = ''; });
});
const release = () => {
  clearTimeout(holdTimer);
  if (held) { held = false; viewer.removeAttribute('data-held'); last = 0; kick(); }
};
viewer.addEventListener('pointerup', release);
viewer.addEventListener('pointercancel', release);
viewer.addEventListener('pointerleave', release);
viewer.addEventListener('keydown', (e) => {
  if (e.target === input) {
    if (e.key === 'Escape') { e.preventDefault(); input.blur(); viewer.focus(); }
    return;
  }
  if (e.key === 'Escape') { e.preventDefault(); close(); }
  else if (e.key === 'ArrowRight') { e.preventDefault(); step(1); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); step(-1); }
  else if (e.key === ' ' && (e.target === viewer || e.target.classList.contains('msc-stories__tap'))) { e.preventDefault(); setPaused(!paused); }
  else if (e.key === 'Tab') {
    const f = $$('button:not(:disabled), input:not(:disabled)', viewer).filter((x) => x.offsetParent !== null);
    const k = f.indexOf(document.activeElement);
    e.preventDefault();
    f[(k + (e.shiftKey ? -1 : 1) + f.length) % f.length].focus();
  }
});
input.addEventListener('focus', () => { typing = true; });
input.addEventListener('blur', () => { typing = !!input.value.trim(); last = 0; kick(); });
input.addEventListener('input', () => { sendBtn.disabled = !input.value.trim(); typing = true; });
$('.msc-stories__reply').addEventListener('submit', (e) => {
  e.preventDefault();
  const v = input.value.trim();
  if (!v) return;
  input.value = '';
  sendBtn.disabled = true;
  toast.textContent = 'Sent to ' + P[pi].full.split(' ')[0];
  toast.classList.add('is-on');
  later(1500, () => toast.classList.remove('is-on'));
  say('Reply sent to ' + P[pi].full);
  input.blur();
  viewer.focus({ preventScroll: true });
  typing = false;
  kick();
});

/* pause the clock off screen and in background tabs */
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  kick();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  last = 0;
  kick();
};
document.addEventListener('visibilitychange', onVis);

paintRow();
paintPreview(1);

