/* Re-theme with --msc-live-bg, -ink, -live and the four reaction hues. */
.msc-live {
  --msc-live-bg: oklch(0.17 0.012 40);
  --msc-live-ink: oklch(0.96 0.008 80);
  --msc-live-live: oklch(0.62 0.22 25);
  --msc-live-r0: oklch(0.66 0.21 12);
  --msc-live-r1: oklch(0.72 0.18 50);
  --msc-live-r2: oklch(0.85 0.15 92);
  --msc-live-r3: oklch(0.74 0.12 175);

  --msc-live-line: color-mix(in oklch, var(--msc-live-ink) 12%, transparent);
  --msc-live-muted: color-mix(in oklch, var(--msc-live-ink) 66%, var(--msc-live-bg));
  --msc-live-faint: color-mix(in oklch, var(--msc-live-ink) 44%, var(--msc-live-bg));
  --msc-live-ring: oklch(1 0 0 / .8);
  --msc-live-ease: cubic-bezier(.22, 1, .36, 1);
  --msc-live-spring: linear(0, 0.1 4%, 0.38 9%, 0.78 17%, 1.04 25%, 1.12 32%, 1.08 40%, 1.01 52%, 0.99 64%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-rows: auto auto;
  border-radius: 18px;
  overflow: clip;
  color: var(--msc-live-ink);
  background: var(--msc-live-bg);
  box-shadow: inset 0 0 0 1px var(--msc-live-line), 0 26px 50px -30px oklch(0 0 0 / .7);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  user-select: none; -webkit-user-select: none;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .msc-live { --msc-live-spring: cubic-bezier(.34, 1.5, .5, 1); }
}
:where(.msc-live) *, :where(.msc-live) *::before, :where(.msc-live) *::after { box-sizing: border-box; }
:where(.msc-live) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.msc-live) :focus-visible { outline: 2px solid var(--msc-live-ring); outline-offset: 2px; }
:where(.msc-live) p { margin: 0; }
.msc-live svg { fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.msc-live__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- stage ---------- */
.msc-live__stage {
  position: relative;
  height: clamp(290px, 88cqi, 400px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  grid-template-areas: "top top" ". tray" "host tray";
  padding: 12px;
  overflow: hidden;
}
.msc-live__scene {
  position: absolute; inset: 0; z-index: 0;
  background:
    radial-gradient(70% 55% at 30% 18%, oklch(0.5 0.14 25 / .55), transparent 70%),
    radial-gradient(55% 45% at 82% 26%, oklch(0.62 0.13 70 / .4), transparent 70%),
    linear-gradient(oklch(0.24 0.04 35), oklch(0.13 0.015 40) 78%);
}
.msc-live__glow {
  position: absolute; left: 50%; top: -30%; width: 70%; aspect-ratio: 1; translate: -50% 0;
  background: conic-gradient(from 180deg at 50% 0, transparent 160deg, oklch(0.9 0.08 80 / .16) 175deg, oklch(0.9 0.08 80 / .22) 180deg, oklch(0.9 0.08 80 / .16) 185deg, transparent 200deg);
  filter: blur(6px);
  transform-origin: 50% 0;
  animation: msc-live-sweep 9s var(--msc-live-ease) infinite alternate;
}
.msc-live__bokeh {
  position: absolute; left: var(--x); top: var(--y); width: var(--s); aspect-ratio: 1; border-radius: 50%;
  background: radial-gradient(circle, oklch(0.88 0.1 70 / .5), oklch(0.8 0.12 40 / .15) 60%, transparent 70%);
