}
.msc-live__eq {
  position: absolute; left: 0; right: 0; bottom: 0; height: 38%;
  display: flex; align-items: flex-end; gap: 4px; padding: 0 14px;
  -webkit-mask: linear-gradient(transparent, #000 75%); mask: linear-gradient(transparent, #000 75%);
  opacity: .32;
  & i {
    flex: 1; height: 100%; border-radius: 2px 2px 0 0;
    background: linear-gradient(oklch(0.85 0.12 70), oklch(0.5 0.16 30) 70%);
    transform-origin: 50% 100%;
    scale: 1 var(--h, .3);
    animation: msc-live-eq var(--d, .8s) ease-in-out infinite alternate;
    animation-delay: calc(var(--i) * -97ms);
  }
}
.msc-live[data-idle] :is(.msc-live__glow, .msc-live__bokeh, .msc-live__eq i) { animation-play-state: paused; }
.msc-live__fx { position: absolute; inset: 0; z-index: 2; width: 100%; height: 100%; pointer-events: none; }

.msc-live__top { grid-area: top; position: relative; z-index: 3; display: flex; align-items: center; gap: 6px; }
.msc-live__badge {
  display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px 3px 7px; border-radius: 6px;
  font-size: 11px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  color: oklch(0.99 0 0); background: var(--msc-live-live);
