  display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px; border-radius: 6px;
  font-size: 11.5px; font-weight: 650; font-variant-numeric: tabular-nums;
  background: oklch(0 0 0 / .42); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
  & svg { width: 14px; height: 14px; }
  & b { font-weight: 650; }
}
.msc-live__clock { margin-left: auto; font-family: ui-monospace, Menlo, monospace; font-size: 11px; }

.msc-live__host {
  grid-area: host; position: relative; z-index: 3; align-self: end;
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 9px;
  & p { min-width: 0; text-shadow: 0 1px 3px oklch(0 0 0 / .6); }
  & b { display: block; font-size: 13.5px; font-weight: 700; letter-spacing: -.01em; }
  & p span { display: block; font-size: 11.5px; color: oklch(1 0 0 / .78); text-wrap: pretty; }
}
.msc-live__av {
  display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%;
  font-size: 11.5px; font-weight: 800; color: oklch(0.25 0.05 40); background: linear-gradient(140deg, oklch(0.9 0.08 70), oklch(0.75 0.14 40));
  box-shadow: 0 0 0 2px var(--msc-live-live);
}

/* ---------- tray ---------- */
.msc-live__tray {
  grid-area: tray; position: relative; z-index: 3; align-self: end;
  display: grid; gap: 8px; margin-left: 10px;
  & button {
    --msc-live-c: var(--msc-live-r0);
    position: relative; display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%;
    color: oklch(1 0 0);
    background: color-mix(in oklch, var(--msc-live-c) 26%, oklch(0 0 0 / .45));
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--msc-live-c) 60%, transparent);
    -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
