  }
  & [data-r="0"] { --msc-live-c: var(--msc-live-r0); & svg { fill: currentColor; } }
  & [data-r="1"] { --msc-live-c: var(--msc-live-r1); & svg { fill: currentColor; } }
  & [data-r="2"] { --msc-live-c: var(--msc-live-r2); }
