}
.msc-live__combo {
  position: absolute; right: calc(100% + 8px); bottom: 0;
  padding: 3px 8px; border-radius: 999px;
  font: 800 13px/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; white-space: nowrap;
  color: oklch(0.15 0.02 40); background: var(--msc-live-c, var(--msc-live-r0));
  translate: 0 var(--y, 0px);
  opacity: 0; scale: .6;
  transition: opacity .25s, scale .3s var(--msc-live-spring), translate .3s var(--msc-live-ease);
  &.is-on { opacity: 1; scale: 1; }
  &.is-bump { animation: msc-live-bump .3s var(--msc-live-spring); }
}

/* ---------- stats ---------- */
.msc-live__stats {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); grid-template-areas: "hype mix" "hide hide";
  gap: 10px 14px; padding: 12px 14px 12px;
  border-top: 1px solid var(--msc-live-line);
}
.msc-live__lbl {
  display: flex; align-items: baseline; gap: 6px;
  font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--msc-live-faint);
  & b { font-size: 12.5px; letter-spacing: 0; text-transform: none; color: var(--msc-live-ink); font-variant-numeric: tabular-nums; }
}
.msc-live__hype { grid-area: hype; min-width: 0; }
.msc-live__spark {
  display: block; width: 100%; height: 30px; margin-top: 4px; overflow: visible;
  & .msc-live__area { fill: color-mix(in oklch, var(--msc-live-r1) 22%, transparent); stroke: none; }
  & .msc-live__line { stroke: var(--msc-live-r1); stroke-width: 1.6; vector-effect: non-scaling-stroke; }
}
.msc-live__mix { grid-area: mix; min-width: 0; }
.msc-live__bar {
  display: flex; gap: 2px; height: 8px; margin-top: 8px; border-radius: 4px; overflow: hidden;
  & i { flex: var(--w, 1) 1 0; min-width: 2px; transition: flex-grow .6s var(--msc-live-ease); }
  & [data-r="0"] { background: var(--msc-live-r0); }
  & [data-r="1"] { background: var(--msc-live-r1); }
  & [data-r="2"] { background: var(--msc-live-r2); }
  & [data-r="3"] { background: var(--msc-live-r3); }
}
.msc-live__legend {
  display: flex; flex-wrap: wrap; gap: 2px 10px; margin-top: 6px;
  font-size: 11px; color: var(--msc-live-muted); font-variant-numeric: tabular-nums;
  & span { display: inline-flex; align-items: center; gap: 4px; }
  & span::before { content: ""; width: 6px; height: 6px; border-radius: 2px; background: var(--msc-live-c); }
}
.msc-live__hide {
  grid-area: hide; justify-self: start;
  display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px 5px 8px; border-radius: 8px;
  font-size: 12px; font-weight: 600; color: var(--msc-live-muted);
  box-shadow: inset 0 0 0 1px var(--msc-live-line);
  transition: background-color .2s, color .2s;
  & svg { width: 16px; height: 16px; }
  & .msc-live__off { display: none; }
  &:hover { color: var(--msc-live-ink); background: color-mix(in oklch, var(--msc-live-ink) 7%, transparent); }
  &[aria-pressed="true"] { color: var(--msc-live-ink); background: color-mix(in oklch, var(--msc-live-ink) 10%, transparent); }
  &[aria-pressed="true"] .msc-live__on { display: none; }
  &[aria-pressed="true"] .msc-live__off { display: block; }
}

@container (min-width: 460px) {
  .msc-live__stage { padding: 14px 16px; }
  .msc-live__tray button { width: 46px; height: 46px; }
  .msc-live__stats { grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr) auto; grid-template-areas: "hype mix hide"; align-items: end; padding-inline: 16px; }
}

@keyframes msc-live-sweep { from { rotate: -14deg; } to { rotate: 14deg; } }
@keyframes msc-live-float { to { translate: 10px -14px; scale: 1.15; } }
@keyframes msc-live-eq { from { scale: 1 var(--lo, .12); } to { scale: 1 var(--hi, .7); } }
@keyframes msc-live-blink { 50% { opacity: .3; } }
@keyframes msc-live-hit { 0% { scale: 1; } 30% { scale: .86; } 100% { scale: 1; } }
@keyframes msc-live-ripple { 0% { opacity: .9; scale: 1; } 100% { opacity: 0; scale: 1.6; } }
@keyframes msc-live-bump { 0% { scale: 1.35; } 100% { scale: 1; } }

@media (prefers-reduced-motion: reduce) {
  .msc-live__glow, .msc-live__bokeh, .msc-live__badge i { animation: none; }
  .msc-live__eq i { animation: none; scale: 1 var(--h, .3); }
  .msc-live__tray button.is-hit, .msc-live__tray button.is-hit::after, .msc-live__combo.is-bump { animation: none; }
  .msc-live__tray button { transition: background-color .2s linear; }
  .msc-live__tray button.is-hold { scale: 1; }
  .msc-live__bar i { transition: none; }
}

