const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const fmt = (n) => Math.round(n).toLocaleString('en-US');

const stage = $('.msc-live__stage');
const cv = $('.msc-live__fx');
const ctx = cv.getContext('2d');
const tray = $('.msc-live__tray');
const btns = $$('.msc-live__tray button');
const combo = $('.msc-live__combo');
const hideBtn = $('.msc-live__hide');
const live = $('.msc-live__sr');
const NAMES = ['love', 'fire', 'sparkle', 'music note'];
/* 18,398 so far = 9,412 + 4,876 + 2,903 + 1,207 */
const COUNTS = [9412, 4876, 2903, 1207];

/* ---------- deterministic equaliser so the still frame is stable ---------- */
let seed = 7;
const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
$('.msc-live__eq').innerHTML = Array.from({ length: 22 }, (_, i) =>
  '<i style="--i:' + i + ';--d:' + (0.45 + rnd() * 0.6).toFixed(2) + 's;--lo:' + (0.08 + rnd() * 0.15).toFixed(2) + ';--hi:' + (0.45 + rnd() * 0.5).toFixed(2) + ';--h:' + (0.2 + rnd() * 0.5).toFixed(2) + '"></i>').join('');

/* ---------- sprites: each reaction pre-rendered once at 2x ---------- */
const PATHS = [
  ['M12 20s-7.5-4.6-7.5-10A4.2 4.2 0 0 1 12 7.6 4.2 4.2 0 0 1 19.5 10c0 5.4-7.5 10-7.5 10Z', true],
  ['M12 21c-3.6 0-6-2.5-6-5.8 0-3.8 3.2-5.6 3.6-10.2 2.6 1.7 4.2 4 4.4 6.6.9-.7 1.5-1.8 1.7-3 1.6 1.7 2.3 3.8 2.3 6.3 0 3.6-2.4 6.1-6 6.1Z', true],
  ['M12 3.5c.7 4.6 2.6 6.5 7.2 7.2-4.6.7-6.5 2.6-7.2 7.2-.7-4.6-2.6-6.5-7.2-7.2 4.6-.7 6.5-2.6 7.2-7.2Z', true],
  ['M9.5 17.5V6.2l9-2.2v11.5M9.5 17.5a2.5 2.5 0 1 1-5 0 2.5 2.5 0 0 1 5 0ZM18.5 15.5a2.5 2.5 0 1 1-5 0 2.5 2.5 0 0 1 5 0Z', false]
];
const FALLBACK = ['#e2456a', '#f08a3c', '#f2cf5b', '#4cc3ad'];
const cs = getComputedStyle(root);
const colorOf = (i) => {
  const v = cs.getPropertyValue('--msc-live-r' + i).trim();
  ctx.fillStyle = '#000';
  ctx.fillStyle = v || FALLBACK[i];
  return ctx.fillStyle === '#000000' ? FALLBACK[i] : v;
};
const SP = 72;
const sprites = PATHS.map(([d, fill], i) => {
  const c = document.createElement('canvas');
  c.width = c.height = SP;
  const g = c.getContext('2d');
  const col = colorOf(i);
  g.fillStyle = col;
  g.beginPath(); g.arc(SP / 2, SP / 2, SP / 2 - 2, 0, Math.PI * 2); g.fill();
  const hl = g.createRadialGradient(SP * 0.35, SP * 0.3, 1, SP * 0.35, SP * 0.3, SP * 0.6);
  hl.addColorStop(0, 'rgba(255,255,255,.35)'); hl.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = hl; g.fill();
  g.save();
  const k = (SP * 0.56) / 24;
  g.translate(SP / 2 - 12 * k, SP / 2 - 12 * k + (i === 0 ? 1 : 0));
  g.scale(k, k);
  const p = new Path2D(d);
  g.strokeStyle = '#fff'; g.fillStyle = '#fff'; g.lineWidth = 2.2; g.lineCap = 'round'; g.lineJoin = 'round';
  if (fill) g.fill(p);
  g.stroke(p);
  g.restore();
  return c;
});

/* ---------- canvas sizing ---------- */
let W = 0, H = 0, dpr = 1;
const size = () => {
  const r = stage.getBoundingClientRect();
  dpr = Math.min(2, window.devicePixelRatio || 1);
  W = r.width; H = r.height;
  cv.width = Math.max(1, Math.round(W * dpr));
  cv.height = Math.max(1, Math.round(H * dpr));
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
};
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  size(); draw();
});
ro.observe(stage);
size();

/* ---------- particles ---------- */
const parts = [];
const MAX = 160;
let hidden = false;
const origin = (i) => {
  const b = btns[i];
  return { x: b.offsetLeft + tray.offsetLeft + b.offsetWidth / 2, y: b.offsetTop + tray.offsetTop + b.offsetHeight / 2 };
};
const spawn = (type, mine, age) => {
  if (hidden || parts.length >= MAX) return;
  const calm = RM.matches;
  let x, y;
  /* everything rises in a lane just left of the tray, so the buttons stay clear */
  const lane = tray.offsetLeft - 22;
  if (mine) { const o = origin(type); x = lane - 4 + (rnd() - 0.5) * 10; y = o.y; }
  else { const o = origin(1); x = lane + (rnd() - 0.5) * 26; y = o.y + rnd() * 40; }
  parts.push({
    type, mine, x0: x, y0: y,
    t: age || 0,
    life: calm ? 900 : (mine ? 2600 : 2900) + rnd() * 900,
    vy: calm ? 0 : (mine ? 95 : 70) + rnd() * 40,
    amp: calm ? 0 : 8 + rnd() * 18,
    freq: 0.8 + rnd() * 0.9,
    ph: rnd() * 6.28,
    size: mine ? 34 + rnd() * 4 : 20 + rnd() * 8,
    rot: (rnd() - 0.5) * 0.5
  });
};
const backOut = (x) => { const c = 1.9; return 1 + (c + 1) * Math.pow(x - 1, 3) + c * Math.pow(x - 1, 2); };
function draw() {
  ctx.clearRect(0, 0, W, H);
  if (hidden) return;
  for (const p of parts) {
    const s = p.t / 1000, k = p.t / p.life;
    const x = p.x0 + Math.sin(p.ph + s * p.freq * 6.283) * p.amp * Math.min(1, s * 1.6);
    const y = p.y0 - p.vy * s - (p.mine ? 0 : 6 * s * s);
    const pop = p.t < 320 ? backOut(p.t / 320) : 1;
    const sz = p.size * pop * (1 - Math.max(0, k - 0.75) * 0.6);
    const a = Math.min(1, p.t / 120) * (k > 0.62 ? Math.max(0, 1 - (k - 0.62) / 0.38) : 1);
    if (a <= 0 || sz <= 0) continue;
    ctx.globalAlpha = a;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(p.rot * Math.sin(p.ph + s * 2));
    ctx.drawImage(sprites[p.type], -sz / 2, -sz / 2, sz, sz);
    ctx.restore();
  }
  ctx.globalAlpha = 1;
}

/* ---------- stats ---------- */
const samples = Array(40).fill(0);
let windowHits = 0;
const paintSpark = () => {
  const max = Math.max(8, ...samples);
  const pts = samples.map((v, i) => [(i / (samples.length - 1)) * 120, 30 - (v / max) * 27]);
  const line = 'M' + pts.map((p) => p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('L');
  $('.msc-live__line').setAttribute('d', line);
  $('.msc-live__area').setAttribute('d', line + 'L120 32L0 32Z');
  const now = (samples[samples.length - 1] + samples[samples.length - 2]) / 2;
  $('.msc-live__rate').textContent = now.toFixed(1) + '/s';
};
const paintCounts = () => {
  const total = COUNTS.reduce((a, b) => a + b, 0);
  $('.msc-live__total').textContent = fmt(total);
  $$('.msc-live__bar i').forEach((el, i) => el.style.setProperty('--w', (COUNTS[i] / total * 100).toFixed(2)));
  $('.msc-live__legend').innerHTML = COUNTS.map((n, i) => '<span style="--msc-live-c:var(--msc-live-r' + i + ')">' + fmt(n) + '</span>').join('');
  $('.msc-live__bar').setAttribute('aria-label', NAMES.map((n, i) => fmt(COUNTS[i]) + ' ' + n).join(', ') + '. ' + fmt(total) + ' in total');
};
const hit = (type, mine) => {
  COUNTS[type]++;
  windowHits++;
  spawn(type, mine);
};
paintCounts();

/* ---------- your reactions: tap, hold to stream, combo ---------- */
let comboN = 0, comboType = -1, comboAt = 0, holdType = -1, holdAcc = 0, holdTimer = 0, fromPointer = false, lastKey = 0, lastSaid = 0;
const mine = (type) => {
  hit(type, true);
  const now = performance.now();
  comboN = type === comboType && now - comboAt < 1300 ? comboN + 1 : 1;
  comboType = type; comboAt = now;
  const b = btns[type];
  b.classList.remove('is-hit'); void b.offsetWidth; b.classList.add('is-hit');
  if (comboN >= 2) {
    combo.textContent = '×' + comboN;
    combo.style.setProperty('--msc-live-c', 'var(--msc-live-r' + type + ')');
    combo.style.setProperty('--y', (b.offsetTop + b.offsetHeight / 2 - tray.offsetHeight + 12) + 'px');
    combo.classList.add('is-on');
    combo.classList.remove('is-bump'); void combo.offsetWidth; combo.classList.add('is-bump');
  }
  if (now - lastSaid > 1500) { lastSaid = now; live.textContent = 'Sent ' + NAMES[type]; }
  kick();
};
tray.addEventListener('pointerdown', (e) => {
  const b = e.target.closest('button');
  if (!b || e.button > 0) return;
  fromPointer = true;
  const t = +b.dataset.r;
  mine(t);
  holdTimer = later(300, () => { holdType = t; holdAcc = 0; b.classList.add('is-hold'); kick(); });
});
const endHold = () => {
  clearTimeout(holdTimer);
  if (holdType > -1) btns[holdType].classList.remove('is-hold');
  holdType = -1;
};
['pointerup', 'pointercancel', 'pointerleave'].forEach((ev) => tray.addEventListener(ev, endHold));
tray.addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  if (fromPointer) { fromPointer = false; return; }
  if (performance.now() - lastKey < 400) return;
  mine(+b.dataset.r);
});
tray.addEventListener('keydown', (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  const k = btns.indexOf(b);
  const to = { ArrowDown: k + 1, ArrowUp: k - 1, ArrowRight: k + 1, ArrowLeft: k - 1, Home: 0, End: btns.length - 1 }[e.key];
  if (to !== undefined) {
    e.preventDefault();
    const j = (to + btns.length) % btns.length;
    btns.forEach((x, i) => { x.tabIndex = i === j ? 0 : -1; });
    btns[j].focus();
  } else if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    const now = performance.now();
    if (now - lastKey > 90) { lastKey = now; mine(k); }
  }
});
root.addEventListener('keydown', (e) => {
  if (!/^[1-4]$/.test(e.key) || e.target.closest('input, textarea')) return;
  lastKey = performance.now();
  mine(+e.key - 1);
});

hideBtn.addEventListener('click', () => {
  hidden = !hidden;
  hideBtn.setAttribute('aria-pressed', String(hidden));
  $('span', hideBtn).textContent = hidden ? 'Show reactions' : 'Hide reactions';
  if (hidden) parts.length = 0;
  draw();
  live.textContent = hidden ? 'Floating reactions hidden' : 'Floating reactions shown';
});

/* ---------- one loop: crowd, clock, stats, particles ---------- */
let raf = 0, last = 0, onscreen = true, crowdAcc = 0, sampleAcc = 0, secAcc = 0, uiAcc = 0, surgeLeft = 0, nextSurge = 6000;
let clock = 1 * 3600 + 12 * 60 + 8, watching = 2431;
const running = () => onscreen && !document.hidden;
const pickType = () => {
  const total = COUNTS.reduce((a, b) => a + b, 0);
  let r = rnd() * total;
  for (let i = 0; i < 4; i++) { r -= COUNTS[i]; if (r <= 0) return i; }
  return 0;
};
const frame = (now) => {
  if (!root.isConnected) return;
  if (!running()) { raf = 0; last = 0; root.toggleAttribute('data-idle', true); return; }
  const dt = last ? Math.min(50, now - last) : 16;
  last = now;

  /* the crowd: a calm base rate with a surge every 8–14 s */
  nextSurge -= dt;
  if (nextSurge <= 0) { surgeLeft = 2600; nextSurge = 8000 + rnd() * 6000; }
  if (surgeLeft > 0) surgeLeft -= dt;
  const rate = RM.matches ? 0.6 : 1.6 + (surgeLeft > 0 ? 8 * Math.sin(Math.PI * (1 - surgeLeft / 2600)) : 0);
  crowdAcc += rate * dt / 1000;
  while (crowdAcc >= 1) { crowdAcc -= 1; hit(pickType(), false); }

  if (holdType > -1) { holdAcc += dt; while (holdAcc >= 110) { holdAcc -= 110; mine(holdType); } }
  if (comboN && now - comboAt > 1300) { comboN = 0; combo.classList.remove('is-on'); }

  for (let i = parts.length - 1; i >= 0; i--) { parts[i].t += dt; if (parts[i].t >= parts[i].life) parts.splice(i, 1); }
  draw();

  sampleAcc += dt;
  if (sampleAcc >= 500) { sampleAcc -= 500; samples.shift(); samples.push(windowHits * 2); windowHits = 0; paintSpark(); }
  uiAcc += dt;
  if (uiAcc >= 320) { uiAcc = 0; paintCounts(); }
  secAcc += dt;
  if (secAcc >= 1000) {
    secAcc -= 1000;
    clock++;
    const h = Math.floor(clock / 3600), m = Math.floor(clock / 60) % 60, s = clock % 60;
    const ck = $('.msc-live__clock');
    ck.textContent = h + ':' + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
    ck.setAttribute('aria-label', 'Live for ' + h + ' hour ' + m + ' minutes');
    if (rnd() < 0.5) {
      watching = Math.max(2300, watching + Math.round((rnd() - 0.42) * 9));
      $('.msc-live__watching').textContent = fmt(watching);
      $('.msc-live__watching').parentElement.setAttribute('aria-label', fmt(watching) + ' watching');
    }
  }
  raf = requestAnimationFrame(frame);
};
function kick() {
  if (!raf && running()) { root.removeAttribute('data-idle'); last = 0; raf = requestAnimationFrame(frame); }
}

const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  onscreen = es[es.length - 1].isIntersecting;
  kick();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  kick();
};
document.addEventListener('visibilitychange', onVis);

/* a few reactions already in flight, so the first frame is alive */
for (let i = 0; i < 9; i++) spawn(pickType(), false, 300 + rnd() * 2200);
for (let i = 0; i < 40; i++) samples[i] = 1.5 + Math.abs(Math.sin(i * 0.45)) * 3 + (i > 26 && i < 33 ? 6 : 0);
paintSpark();
draw();
kick();

