@property --msc-poll-p {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}
@property --msc-poll-n {
  syntax: "<integer>";
  inherits: true;
  initial-value: 0;
}

/* Re-theme with --msc-poll-paper, -ink and -accent. */
.msc-poll {
  --msc-poll-paper: oklch(0.968 0.045 96);
  --msc-poll-ink: oklch(0.22 0.022 75);
  --msc-poll-accent: oklch(0.6 0.19 34);

  --msc-poll-card: color-mix(in oklch, var(--msc-poll-paper) 60%, oklch(1 0 0));
  --msc-poll-line: color-mix(in oklch, var(--msc-poll-ink) 14%, transparent);
  --msc-poll-muted: color-mix(in oklch, var(--msc-poll-ink) 68%, var(--msc-poll-paper));
  --msc-poll-faint: color-mix(in oklch, var(--msc-poll-ink) 48%, var(--msc-poll-paper));
  --msc-poll-hover: color-mix(in oklch, var(--msc-poll-ink) 5%, transparent);
  --msc-poll-ring: color-mix(in oklch, var(--msc-poll-accent) 70%, transparent);
  --msc-poll-ease: cubic-bezier(.22, 1, .36, 1);
  --msc-poll-flood: cubic-bezier(.3, .75, .15, 1);
  --msc-poll-spring: linear(0, 0.09 4%, 0.35 9%, 0.73 17%, 1 25%, 1.08 32%, 1.06 40%, 1.01 52%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 16px 16px 14px;
  border-radius: 18px;
  overflow: clip;
  color: var(--msc-poll-ink);
  background:
    radial-gradient(circle at 1px 1px, color-mix(in oklch, var(--msc-poll-ink) 9%, transparent) 1px, transparent 1.5px) 0 0 / 14px 14px,
    var(--msc-poll-paper);
  box-shadow: 0 0 0 1px var(--msc-poll-line), 0 24px 44px -32px color-mix(in oklch, var(--msc-poll-ink) 60%, transparent);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .msc-poll { --msc-poll-spring: cubic-bezier(.34, 1.45, .5, 1); }
}
:where(.msc-poll) *, :where(.msc-poll) *::before, :where(.msc-poll) *::after { box-sizing: border-box; }
:where(.msc-poll) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.msc-poll) :focus-visible { outline: 2px solid var(--msc-poll-ring); outline-offset: 2px; }
:where(.msc-poll) :is(h3, p, form, fieldset) { margin: 0; }
.msc-poll svg { fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.msc-poll__sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.msc-poll__head { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px; }
.msc-poll__av {
  display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px;
  font-size: 12px; font-weight: 800; letter-spacing: .02em;
  color: var(--msc-poll-paper); background: var(--msc-poll-ink);
}
.msc-poll__by {
  font-size: 12.5px; line-height: 1.3; color: var(--msc-poll-faint);
  & b { display: block; font-size: 13.5px; font-weight: 700; color: var(--msc-poll-ink); }
}
.msc-poll__tag {
  display: inline-flex; align-items: center; gap: 4px; padding: 3px 8px 3px 6px; border-radius: 999px;
  font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  box-shadow: inset 0 0 0 1.5px var(--msc-poll-ink);
  & svg { width: 13px; height: 13px; stroke-width: 2.4; }
}
.msc-poll__q {
  margin-top: 14px;
  font-size: clamp(19px, 6.4cqi, 25px); font-weight: 800; letter-spacing: -.035em; line-height: 1.08;
  text-wrap: balance;
}
.msc-poll__hint { margin-top: 6px; font-size: 12.5px; color: var(--msc-poll-muted); text-wrap: pretty; }

.msc-poll__set { border: 0; padding: 0; min-width: 0; margin-top: 14px; }
.msc-poll__opts { display: grid; gap: 8px; }

/* ---------- an option is its own result bar ---------- */
.msc-poll__opt {
  --msc-poll-p: 0;
  --msc-poll-n: 0;
  position: relative; display: grid; grid-template-areas: "s";
  border-radius: 12px;
  cursor: pointer;
  transition: --msc-poll-p 1.15s var(--msc-poll-flood), --msc-poll-n 1.15s var(--msc-poll-flood), scale .3s var(--msc-poll-spring), box-shadow .2s;
  transition-delay: calc(var(--i) * 90ms);
  box-shadow: inset 0 0 0 1.5px var(--msc-poll-line);
  background: var(--msc-poll-card);
  & input { position: absolute; opacity: 0; width: 1px; height: 1px; margin: 0; pointer-events: none; }
  &:hover { box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--msc-poll-ink) 34%, transparent); }
  &:active { scale: .985; }
  &:has(input:focus-visible) { outline: 2px solid var(--msc-poll-ring); outline-offset: 2px; }
  &:has(input:checked) { box-shadow: inset 0 0 0 2px var(--msc-poll-ink); }
}
.msc-poll__layer {
  grid-area: s;
  display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; align-items: center; gap: 10px;
  min-height: 52px; padding: 8px 14px 8px 12px; border-radius: inherit;
}
.msc-poll__inv {
  color: var(--msc-poll-paper);
  background: var(--msc-poll-ink);
  clip-path: inset(0 calc(100% - var(--msc-poll-p) * 1%) 0 0 round 12px);
  pointer-events: none;
}
.msc-poll__opt.is-mine .msc-poll__inv { background: var(--msc-poll-accent); color: oklch(0.99 0.01 90); }
.msc-poll__mark {
  display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%;
  box-shadow: inset 0 0 0 1.5px currentColor;
  opacity: .55;
  transition: opacity .2s, box-shadow .25s var(--msc-poll-ease), scale .3s var(--msc-poll-spring);
  & svg { width: 12px; height: 12px; stroke-width: 3; opacity: 0; scale: .4; transition: opacity .2s, scale .35s var(--msc-poll-spring); }
}
.msc-poll__opt:has(input:checked) .msc-poll__mark { opacity: 1; box-shadow: inset 0 0 0 6px currentColor; }
.msc-poll__name { min-width: 0; }
.msc-poll__name b { display: block; font-size: 14.5px; font-weight: 650; letter-spacing: -.01em; line-height: 1.25; }
.msc-poll__name small { display: block; font-size: 12px; opacity: .7; font-variant-numeric: tabular-nums; }
.msc-poll__pct {
  font: 750 15px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; letter-spacing: -.02em;
  counter-reset: msc-poll-n var(--msc-poll-n);
  opacity: 0; translate: 6px 0;
  transition: opacity .3s, translate .45s var(--msc-poll-ease);
  &::after { content: counter(msc-poll-n) "%"; }
}

/* results mode */
.msc-poll[data-mode="results"] {
  & .msc-poll__opt { cursor: default; }
  & .msc-poll__opt:hover { box-shadow: inset 0 0 0 1.5px var(--msc-poll-line); }
  & .msc-poll__opt:active { scale: 1; }
  & .msc-poll__pct { opacity: 1; translate: 0 0; transition-delay: calc(var(--i) * 90ms); }
  & .msc-poll__mark { opacity: 0; scale: .5; }
  & .msc-poll__opt.is-mine .msc-poll__mark { opacity: 1; scale: 1; box-shadow: inset 0 0 0 10px currentColor; }
  & .msc-poll__opt.is-mine .msc-poll__mark svg { opacity: 1; scale: 1; }
  & .msc-poll__opt.is-lead .msc-poll__name b::after {
    content: "Leading"; margin-left: 6px; padding: 1px 5px; border-radius: 4px; vertical-align: 2px;
    font-size: 9.5px; font-weight: 750; letter-spacing: .06em; text-transform: uppercase;
    box-shadow: inset 0 0 0 1px currentColor;
  }
}
.msc-poll__opt.is-mine .msc-poll__layer:not(.msc-poll__inv) .msc-poll__mark { color: var(--msc-poll-accent); }
.msc-poll__opt.is-mine .msc-poll__inv .msc-poll__mark { color: oklch(0.99 0.01 90); & svg { color: var(--msc-poll-accent); } }
.msc-poll__layer:not(.msc-poll__inv) .msc-poll__mark svg { color: var(--msc-poll-paper); }

/* ---------- footer ---------- */
.msc-poll__foot {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px;
  margin-top: 14px;
}
.msc-poll__meta {
  display: flex; flex-wrap: wrap; column-gap: 8px;
  font-size: 12.5px; color: var(--msc-poll-muted); font-variant-numeric: tabular-nums;
  & > span + span::before { content: "·"; margin-right: 8px; }
  & b { color: var(--msc-poll-ink); font-weight: 650; }
}
.msc-poll__acts { display: flex; align-items: center; gap: 6px; margin-left: auto; }
.msc-poll__ghost {
  height: 34px; padding: 0 12px; border-radius: 999px; font-size: 12.5px; font-weight: 650; color: var(--msc-poll-muted);
  transition: background-color .2s, color .2s;
  &:hover { color: var(--msc-poll-ink); background: var(--msc-poll-hover); }
}
.msc-poll__vote {
  display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 18px; border-radius: 999px;
  font-size: 13px; font-weight: 750;
  color: var(--msc-poll-paper); background: var(--msc-poll-ink);
  transition: opacity .2s, scale .3s var(--msc-poll-spring), background-color .2s;
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--msc-poll-ink) 82%, var(--msc-poll-accent)); }
  &:active:not(:disabled) { scale: .96; }
  &:disabled { opacity: .3; cursor: not-allowed; }
  &[aria-busy="true"] { opacity: .85; cursor: progress; }
}
.msc-poll__spin {
  display: none; width: 13px; height: 13px; border-radius: 50%;
  border: 2px solid currentColor; border-right-color: transparent;
  animation: msc-poll-spin .7s linear infinite;
}
.msc-poll__vote[aria-busy="true"] .msc-poll__spin { display: block; }
.msc-poll[data-mode="results"] .msc-poll__vote { display: none; }

@container (min-width: 440px) {
  .msc-poll { padding: 20px 20px 16px; }
  .msc-poll__layer { min-height: 56px; padding-inline: 14px 18px; }
  .msc-poll__name b { font-size: 15px; }
}
@container (max-width: 320px) {
  .msc-poll { padding-inline: 14px; }
  .msc-poll__layer { gap: 8px; padding-inline: 10px 12px; }
  .msc-poll__hint { display: none; }
}

@keyframes msc-poll-spin { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .msc-poll__opt { transition: box-shadow .2s linear; transition-delay: 0s; }
  .msc-poll__pct, .msc-poll[data-mode="results"] .msc-poll__pct { transition: opacity .2s linear; transition-delay: 0s; translate: 0 0; }
  .msc-poll__mark, .msc-poll__mark svg { transition: opacity .2s linear; }
  .msc-poll__spin { animation-duration: 2s; }
}

js:
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const UID = 'msc-poll-' + Math.random().toString(36).slice(2, 7);
const fmt = (n) => n.toLocaleString('en-US');

/* 862 + 574 + 701 + 281 = 2,418 votes before yours */
const OPTS = [
  { id: 'porto', name: 'Porto', sub: 'Riverside studio, Ribeira', votes: 862 },
  { id: 'ljubljana', name: 'Ljubljana', sub: 'Old-town loft by the river', votes: 574 },
  { id: 'valencia', name: 'Valencia', sub: 'Beach campus, El Cabanyal', votes: 701 },
  { id: 'tallinn', name: 'Tallinn', sub: 'Harbour warehouse, Kalamaja', votes: 281 }
];
let mine = null, mode = 'vote', choice = null;
const form = $('.msc-poll__form');
const list = $('.msc-poll__opts');
const vote = $('.msc-poll__vote');
const ghost = $('[data-do="peek"]');
const live = $('.msc-poll__sr');
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const CHECK = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6.5 12.5 3.6 3.6 7.4-8"/></svg>';

const count = (o) => o.votes + (mine === o.id ? 1 : 0);
const total = () => OPTS.reduce((a, o) => a + count(o), 0);
/* largest remainder: floor everything, hand the leftover points to the biggest remainders */
const percents = () => {
  const t = total(), raw = OPTS.map((o) => count(o) * 100 / t), fl = raw.map(Math.floor);
  let left = 100 - fl.reduce((a, b) => a + b, 0);
  raw.map((r, i) => [r - fl[i], i]).sort((a, b) => b[0] - a[0]).forEach(([, i]) => { if (left > 0) { fl[i]++; left--; } });
  return fl;
};

const layer = (o, inv) => '<span class="msc-poll__layer' + (inv ? ' msc-poll__inv" aria-hidden="true' : '') + '">' +
  '<span class="msc-poll__mark" aria-hidden="true">' + CHECK + '</span>' +
  '<span class="msc-poll__name"><b>' + o.name + '</b><small>' + o.sub + '</small></span>' +
  '<span class="msc-poll__pct" aria-hidden="true"></span></span>';
list.innerHTML = OPTS.map((o, i) =>
  '<label class="msc-poll__opt" style="--i:' + i + '" data-id="' + o.id + '">' +
  '<input type="radio" name="' + UID + '" value="' + o.id + '">' + layer(o, false) + layer(o, true) + '</label>').join('');
const labels = $$('.msc-poll__opt', list);
const radios = $$('input', list);

const paint = () => {
  const pc = percents(), lead = Math.max(...OPTS.map(count));
  const showing = mode === 'results';
  root.dataset.mode = mode;
  labels.forEach((l, i) => {
    const o = OPTS[i];
    l.style.setProperty('--msc-poll-p', showing ? pc[i] : 0);
    l.style.setProperty('--msc-poll-n', showing ? pc[i] : 0);
    l.classList.toggle('is-mine', mine === o.id);
    l.classList.toggle('is-lead', showing && count(o) === lead);
    $$('small', l).forEach((s) => { s.textContent = showing ? fmt(count(o)) + ' votes' : o.sub; });
    const r = radios[i];
    r.disabled = showing;
    r.setAttribute('aria-label', showing ? o.name + ', ' + pc[i] + ' percent, ' + fmt(count(o)) + ' votes' + (mine === o.id ? ', your vote' : '') : o.name + ', ' + o.sub);
  });
  $('.msc-poll__votes').innerHTML = '<b>' + fmt(total()) + '</b> votes';
  if (mine) {
    $('.msc-poll__left').textContent = 'You voted ' + OPTS.find((o) => o.id === mine).name;
    ghost.textContent = 'Change vote';
    ghost.dataset.do = 'change';
  } else if (showing) {
    $('.msc-poll__left').textContent = 'Closes in 2 days';
    ghost.textContent = 'Back to vote';
    ghost.dataset.do = 'back';
  } else {
    $('.msc-poll__left').textContent = 'Closes in 2 days';
    ghost.textContent = 'See results';
    ghost.dataset.do = 'peek';
  }
  vote.disabled = !choice || showing;
};

list.addEventListener('change', (e) => {
  choice = e.target.value;
  paint();
});
form.addEventListener('submit', (e) => {
  e.preventDefault();
  if (!choice || mode !== 'vote' || vote.getAttribute('aria-busy') === 'true') return;
  vote.setAttribute('aria-busy', 'true');
  $('.msc-poll__vl').textContent = 'Voting';
  radios.forEach((r) => { r.disabled = true; });
  later(RM.matches ? 200 : 650, () => {
    vote.removeAttribute('aria-busy');
    $('.msc-poll__vl').textContent = 'Vote';
    mine = choice;
    mode = 'results';
    paint();
    const pc = percents(), k = OPTS.findIndex((o) => o.id === mine);
    say('Vote counted for ' + OPTS[k].name + '. ' + OPTS.map((o, i) => o.name + ' ' + pc[i] + ' percent').join(', ') + '. ' + fmt(total()) + ' votes.');
    ghost.focus({ preventScroll: true });
  });
});
ghost.addEventListener('click', () => {
  const d = ghost.dataset.do;
  if (d === 'peek') { mode = 'results'; paint(); say('Showing results. ' + fmt(total()) + ' votes.'); }
  else if (d === 'back') { mode = 'vote'; paint(); say('Back to voting'); }
  else if (d === 'change') {
    const was = mine;
    mine = null;
    mode = 'vote';
    choice = was;
    radios.forEach((r) => { r.checked = r.value === was; });
    paint();
    say('Your vote was removed. Pick again.');
    const r = radios.find((x) => x.checked);
    if (r) r.focus({ preventScroll: true });
  }
});

paint();

css:
/* Re-theme with --msc-share-bg, -sheet, -ink and -accent. */
.msc-share {
  --msc-share-bg: oklch(0.93 0.018 150);
  --msc-share-sheet: oklch(0.995 0.003 150);
  --msc-share-ink: oklch(0.24 0.025 165);
  --msc-share-accent: oklch(0.55 0.11 165);

  --msc-share-line: color-mix(in oklch, var(--msc-share-ink) 11%, transparent);
  --msc-share-muted: color-mix(in oklch, var(--msc-share-ink) 66%, var(--msc-share-sheet));
  --msc-share-faint: color-mix(in oklch, var(--msc-share-ink) 46%, var(--msc-share-sheet));
  --msc-share-well: color-mix(in oklch, var(--msc-share-ink) 5%, var(--msc-share-sheet));
  --msc-share-hover: color-mix(in oklch, var(--msc-share-ink) 6%, transparent);
  --msc-share-tint: color-mix(in oklch, var(--msc-share-accent) 12%, var(--msc-share-sheet));
  --msc-share-ring: color-mix(in oklch, var(--msc-share-accent) 70%, transparent);
  --msc-share-ease: cubic-bezier(.22, 1, .36, 1);
  --msc-share-spring: linear(0, 0.09 4%, 0.35 9%, 0.74 17%, 1.01 25%, 1.08 32%, 1.06 40%, 1.01 52%, 0.99 64%, 1);

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: 500px;
  border-radius: 22px;
  overflow: clip;
  color: var(--msc-share-ink);
  background: var(--msc-share-bg);
  box-shadow: 0 0 0 1px var(--msc-share-line), 0 24px 46px -32px color-mix(in oklch, var(--msc-share-ink) 60%, transparent);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
@supports not (transition-timing-function: linear(0, 1)) {
  .msc-share { --msc-share-spring: cubic-bezier(.34, 1.45, .5, 1); }
}
:where(.msc-share) *, :where(.msc-share) *::before, :where(.msc-share) *::after { box-sizing: border-box; }
:where(.msc-share) :is(button, input) { font: inherit; color: inherit; }
:where(.msc-share) button { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
:where(.msc-share) :focus-visible { outline: 2px solid var(--msc-share-ring); outline-offset: 2px; }
:where(.msc-share) :is(h3, h4, p, ul, form) { margin: 0; }
.msc-share svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }

/* ---------- the post underneath ---------- */
.msc-share__post {
  height: 100%;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: minmax(104px, 1fr) auto auto auto auto;
  grid-template-areas: "thumb thumb" "kick kick" "title title" "by by" ". open";
  padding: 14px 16px 16px; row-gap: 4px;
}
.msc-share__thumb {
  grid-area: thumb; position: relative; min-height: 0; margin-bottom: 10px; border-radius: 16px; overflow: hidden;
  background:
    radial-gradient(90% 80% at 80% 15%, oklch(0.9 0.11 92), transparent 70%),
    linear-gradient(160deg, oklch(0.82 0.14 82), oklch(0.64 0.15 58));
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; }
  & .msc-share__comb { fill: none; stroke: oklch(0.45 0.11 55 / .38); stroke-width: 1.4; }
  & .msc-share__cap { fill: oklch(0.93 0.09 92 / .55); stroke: none; }
  & .msc-share__honey { fill: oklch(0.6 0.16 55 / .55); stroke: none; }
}
.msc-share__kick { grid-area: kick; font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--msc-share-accent); }
.msc-share__title { grid-area: title; font-size: clamp(16px, 5cqi, 19px); font-weight: 750; letter-spacing: -.025em; line-height: 1.18; text-wrap: balance; }
.msc-share__by { grid-area: by; font-size: 12.5px; color: color-mix(in oklch, var(--msc-share-ink) 62%, var(--msc-share-bg)); text-wrap: pretty; }
.msc-share__open {
  grid-area: open; margin-top: 8px;
  display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 16px 0 12px; border-radius: 999px;
  font-size: 13px; font-weight: 700; color: var(--msc-share-sheet); background: var(--msc-share-ink);
  transition: scale .3s var(--msc-share-spring), background-color .2s;
  & svg { width: 17px; height: 17px; }
  &:hover { background: color-mix(in oklch, var(--msc-share-ink) 85%, var(--msc-share-accent)); }
  &:active { scale: .95; }
}

.msc-share__scrim {
  position: absolute; inset: 0; z-index: 1;
  background: color-mix(in oklch, var(--msc-share-ink) 38%, transparent);
  -webkit-backdrop-filter: blur(2px); backdrop-filter: blur(2px);
  opacity: 0; pointer-events: none;
  transition: opacity .35s var(--msc-share-ease);
}
.msc-share[data-open="true"] .msc-share__scrim { opacity: 1; pointer-events: auto; }

/* ---------- the sheet ---------- */
.msc-share__sheet {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 2;
  max-height: calc(100% - 28px);
  display: grid; grid-template-columns: minmax(0, 1fr);
  padding: 0 0 14px;
  border-radius: 22px 22px 0 0;
  background: var(--msc-share-sheet);
  box-shadow: 0 -1px 0 var(--msc-share-line), 0 -18px 40px -20px color-mix(in oklch, var(--msc-share-ink) 40%, transparent);
  translate: 0 calc(100% + 24px);
  transition: translate .5s var(--msc-share-ease), visibility 0s .5s;
  visibility: hidden;
  outline: none;
  touch-action: none;
}
.msc-share[data-open="true"] .msc-share__sheet {
  translate: 0 var(--msc-share-dy, 0px);
  visibility: visible;
  transition: translate .6s var(--msc-share-spring), visibility 0s;
}
.msc-share[data-drag] .msc-share__sheet { transition: none; }
.msc-share__grab {
  display: grid; place-items: center; height: 22px; cursor: grab;
  & i { width: 38px; height: 5px; border-radius: 3px; background: color-mix(in oklch, var(--msc-share-ink) 18%, transparent); transition: width .25s var(--msc-share-ease), background-color .2s; }
}
.msc-share[data-drag] .msc-share__grab { cursor: grabbing; & i { width: 48px; background: color-mix(in oklch, var(--msc-share-ink) 32%, transparent); } }
.msc-share__head {
  display: flex; align-items: center; justify-content: space-between; padding: 0 10px 6px 18px;
}
.msc-share__h { font-size: 16px; font-weight: 750; letter-spacing: -.02em; }
.msc-share__x {
  display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; color: var(--msc-share-muted);
  background: var(--msc-share-well);
  & svg { width: 16px; height: 16px; }
  &:hover { color: var(--msc-share-ink); background: color-mix(in oklch, var(--msc-share-ink) 9%, var(--msc-share-sheet)); }
}

.msc-share__link, .msc-share__find {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px;
  margin: 4px 14px 0; padding: 0 5px 0 12px; height: 42px; border-radius: 12px;
  background: var(--msc-share-well);
  transition: box-shadow .2s;
  & > svg { width: 17px; height: 17px; color: var(--msc-share-faint); }
  & input {
    min-width: 0; height: 100%; border: 0; padding: 0; background: none; outline: none;
    font-size: 13.5px;
    &::placeholder { color: var(--msc-share-faint); }
  }
  &:has(input:focus-visible) { box-shadow: 0 0 0 2px var(--msc-share-ring); }
}
.msc-share__link .msc-share__url { font-family: ui-monospace, Menlo, monospace; font-size: 12.5px; color: var(--msc-share-muted); text-overflow: ellipsis; }
.msc-share__find { grid-template-columns: auto minmax(0, 1fr); margin-top: 8px; }
.msc-share__copy {
  display: inline-grid; grid-template-areas: "l"; place-items: center;
  height: 32px; padding: 0 12px; border-radius: 9px;
  font-size: 12.5px; font-weight: 700; color: var(--msc-share-sheet); background: var(--msc-share-ink);
  transition: background-color .25s, scale .3s var(--msc-share-spring);
  &:active { scale: .95; }
  & span { grid-area: l; display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; transition: opacity .2s, translate .35s var(--msc-share-ease); }
  & svg { width: 14px; height: 14px; stroke-width: 2.6; }
  & [data-l]:not([data-l="idle"]) { opacity: 0; translate: 0 6px; }
  &[data-state="done"] { background: var(--msc-share-accent); }
  &[data-state="fail"] { background: oklch(0.55 0.16 30); }
  &[data-state="done"] [data-l="done"], &[data-state="fail"] [data-l="fail"] { opacity: 1; translate: 0 0; }
  &:not([data-state="idle"]) [data-l="idle"] { opacity: 0; translate: 0 -6px; }
}

/* ---------- people ---------- */
.msc-share__people {
  list-style: none; padding: 10px 16px 4px; scroll-padding-inline: 16px;
  display: grid; grid-auto-flow: column; grid-auto-columns: 64px; gap: 4px;
  overflow-x: auto; scrollbar-width: none; overscroll-behavior-x: contain; scroll-snap-type: x proximity;
  &::-webkit-scrollbar { display: none; }
  & li { scroll-snap-align: start; }
}
.msc-share__who {
  display: grid; justify-items: center; gap: 5px; width: 64px; padding: 2px 0 4px; border-radius: 12px;
  font-size: 11.5px; line-height: 1.2; color: var(--msc-share-muted); text-align: center;
  &:focus-visible { outline-offset: 0; }
  & .msc-share__nm { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
}
.msc-share__face {
  position: relative; display: grid; place-items: center; width: 52px; height: 52px; border-radius: 50%;
  font-size: 15px; font-weight: 750;
  color: oklch(0.3 0.06 var(--h)); background: oklch(0.88 0.07 var(--h));
  transition: scale .35s var(--msc-share-spring), box-shadow .25s var(--msc-share-ease);
  &[data-group] { border-radius: 16px; }
}
.msc-share__tick {
  position: absolute; right: -2px; bottom: -2px;
  display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%;
  color: var(--msc-share-sheet); background: var(--msc-share-accent);
  box-shadow: 0 0 0 2.5px var(--msc-share-sheet);
  scale: 0; transition: scale .35s var(--msc-share-spring);
  & svg { width: 12px; height: 12px; stroke-width: 3; }
}
.msc-share__who:hover .msc-share__face { scale: 1.05; }
.msc-share__who[aria-pressed="true"] {
  color: var(--msc-share-ink);
  & .msc-share__face { scale: .9; box-shadow: 0 0 0 2.5px var(--msc-share-sheet), 0 0 0 4.5px var(--msc-share-accent); }
  & .msc-share__tick { scale: 1; }
}
.msc-share__none {
  margin: 10px 18px 6px; padding: 14px; border-radius: 12px; text-align: center;
  font-size: 12.5px; color: var(--msc-share-muted); background: var(--msc-share-well); text-wrap: balance;
  & b { color: var(--msc-share-ink); font-weight: 650; }
}

/* the message row appears as soon as anyone is picked */
.msc-share__compose {
  display: grid; grid-template-rows: 0fr;
  transition: grid-template-rows .45s var(--msc-share-ease), opacity .3s;
  opacity: 0;
  & > form { min-height: 0; overflow: hidden; }
}
.msc-share:has(.msc-share__who[aria-pressed="true"]) .msc-share__compose,
.msc-share__compose:has(.msc-share__send:not([data-state="idle"])) { grid-template-rows: 1fr; opacity: 1; }
.msc-share__form {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; align-items: center;
  padding: 8px 14px 2px;
  & input {
    min-width: 0; height: 40px; padding: 0 14px; border-radius: 999px; border: 0;
    background: var(--msc-share-well); font-size: 13.5px;
    &::placeholder { color: var(--msc-share-faint); }
    &:focus { outline: none; box-shadow: 0 0 0 2px var(--msc-share-ring); }
  }
}
.msc-share__send {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 40px; min-width: 96px; padding: 0 16px; border-radius: 999px;
  font-size: 13px; font-weight: 750; font-variant-numeric: tabular-nums;
  color: var(--msc-share-sheet); background: var(--msc-share-accent);
  transition: background-color .25s, scale .35s var(--msc-share-spring), min-width .35s var(--msc-share-ease);
  &:hover { background: color-mix(in oklch, var(--msc-share-accent) 85%, var(--msc-share-ink)); }
  &:active { scale: .95; }
  &[data-state="sending"] { cursor: progress; opacity: .85; }
  &[data-state="sent"] { background: var(--msc-share-ink); }
  & svg { width: 15px; height: 15px; stroke-width: 2.6; }
}
.msc-share__spin {
  display: none; width: 14px; height: 14px; border-radius: 50%;
  border: 2px solid currentColor; border-right-color: transparent;
  animation: msc-share-spin .7s linear infinite;
}
.msc-share__send[data-state="sending"] .msc-share__spin { display: block; }

/* ---------- targets ---------- */
.msc-share__targets {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px;
  margin: 10px 14px 0; padding-top: 10px;
  border-top: 1px solid var(--msc-share-line);
  & button {
    display: grid; justify-items: center; gap: 5px; padding: 6px 2px; border-radius: 12px;
    font-size: 12px; font-weight: 600; color: var(--msc-share-muted);
    transition: background-color .2s, color .2s;
    &:hover { background: var(--msc-share-hover); color: var(--msc-share-ink); }
    &[aria-pressed="true"] { color: var(--msc-share-accent); }
    &[aria-pressed="true"] .msc-share__ti { color: var(--msc-share-sheet); background: var(--msc-share-accent); box-shadow: none; }
    &[data-do="save"][aria-pressed="true"] path { fill: currentColor; }
  }
}
.msc-share__ti {
  display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%;
  box-shadow: inset 0 0 0 1px var(--msc-share-line); background: var(--msc-share-sheet);
  transition: background-color .25s, color .25s, scale .35s var(--msc-share-spring);
  & svg { width: 19px; height: 19px; }
}
.msc-share__targets button:active .msc-share__ti { scale: .9; }

.msc-share__toast {
  position: absolute; left: 50%; top: 14px; z-index: 5;
  display: inline-flex; align-items: center; gap: 6px; padding: 7px 13px; border-radius: 999px;
  font-size: 12.5px; font-weight: 650; white-space: nowrap; max-width: calc(100% - 24px); overflow: hidden; text-overflow: ellipsis;
  color: var(--msc-share-sheet); background: var(--msc-share-ink);
  translate: -50% -10px; opacity: 0; pointer-events: none;
  transition: opacity .2s, translate .4s var(--msc-share-spring);
  &.is-on { opacity: 1; translate: -50% 0; }
}

@container (min-width: 440px) {
  .msc-share__people { grid-auto-columns: 70px; padding-inline: 18px; }
  .msc-share__who { width: 70px; }
  .msc-share__link, .msc-share__find, .msc-share__targets { margin-inline: 18px; }
  .msc-share__form { padding-inline: 18px; }
  .msc-share__post { padding: 18px 20px; }
  .msc-share__thumb { height: 120px; }
}

@keyframes msc-share-spin { to { rotate: 1turn; } }

@media (prefers-reduced-motion: reduce) {
  .msc-share__sheet { transition: opacity .2s linear, visibility 0s .2s; translate: 0 0; opacity: 0; }
  .msc-share[data-open="true"] .msc-share__sheet { opacity: 1; translate: 0 var(--msc-share-dy, 0px); transition: opacity .2s linear, visibility 0s; }
  .msc-share__compose { transition: opacity .2s linear; }
  .msc-share__face, .msc-share__tick, .msc-share__ti, .msc-share__copy span { transition: none; }
  .msc-share__who:hover .msc-share__face, .msc-share__who[aria-pressed="true"] .msc-share__face { scale: 1; }
  .msc-share__toast { transition: opacity .2s linear; translate: -50% 0; }
  .msc-share__spin { animation-duration: 2s; }
}

js:
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const URL_TEXT = 'fieldnote.example/n/rooftop-bees';
const TITLE = 'Twelve weeks of rooftop beekeeping in Lyon';

const PEOPLE = [
  { id: 'studio', name: 'Studio crew', short: 'Studio crew', hue: 165, group: 5 },
  { id: 'ines', name: 'Inês Carvalho', hue: 30 },
  { id: 'kofi', name: 'Kofi Mensah', hue: 110 },
  { id: 'tove', name: 'Tove Lindqvist', hue: 200 },
  { id: 'amara', name: 'Amara Osei', hue: 60 },
  { id: 'jun', name: 'Jun Park', hue: 250 },
  { id: 'priya', name: 'Priya Raman', hue: 330 },
  { id: 'lucia', name: 'Lucía Paredes', hue: 15 },
  { id: 'sven', name: 'Sven Aaltonen', hue: 140 }
];
const picked = new Set();

const post = $('.msc-share__post');
const opener = $('.msc-share__open');
const sheet = $('.msc-share__sheet');
const scrim = $('.msc-share__scrim');
const people = $('.msc-share__people');
const none = $('.msc-share__none');
const q = $('.msc-share__q');
const copy = $('.msc-share__copy');
const url = $('.msc-share__url');
const form = $('.msc-share__form');
const msg = $('.msc-share__msg');
const send = $('.msc-share__send');
const toast = $('.msc-share__toast');
let toastTimer = 0, copyTimer = 0, busy = false;

const esc = (t) => t.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const ini = (p) => p.group ? '<svg viewBox="0 0 24 24" aria-hidden="true" width="22" height="22"><circle cx="9" cy="8.5" r="3"/><path d="M3.5 19a5.5 5.5 0 0 1 11 0M15.5 5.8a3 3 0 0 1 0 5.4M17.5 14.2a5.5 5.5 0 0 1 3 4.8"/></svg>' : p.name.split(' ').map((w) => w[0]).join('');
const first = (p) => p.group ? p.name : p.name.split(' ')[0];
const showToast = (t) => {
  clearTimeout(toastTimer);
  toast.textContent = t;
  toast.classList.add('is-on');
  toastTimer = later(1900, () => toast.classList.remove('is-on'));
};

/* ---------- people ---------- */
const TICK = '<span class="msc-share__tick" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m6.5 12.5 3.6 3.6 7.4-8"/></svg></span>';
const paintPeople = () => {
  const term = q.value.trim().toLowerCase();
  const list = PEOPLE.filter((p) => !term || p.name.toLowerCase().split(' ').some((w) => w.startsWith(term)) || p.name.toLowerCase().includes(term));
  people.innerHTML = list.map((p, i) =>
    '<li><button type="button" class="msc-share__who" data-id="' + p.id + '" aria-pressed="' + picked.has(p.id) + '" tabindex="' + (i === 0 ? 0 : -1) + '"' +
    ' aria-label="' + esc(p.name) + (p.group ? ', group of ' + p.group : '') + '">' +
    '<span class="msc-share__face" style="--h:' + p.hue + '"' + (p.group ? ' data-group' : '') + ' aria-hidden="true">' + ini(p) + TICK + '</span>' +
    '<span class="msc-share__nm" aria-hidden="true">' + esc(first(p)) + '</span></button></li>').join('');
  none.hidden = list.length > 0;
  people.hidden = list.length === 0;
  if (!list.length) none.innerHTML = 'No one called <b>“' + esc(q.value.trim()) + '”</b> in your contacts. Try a first name.';
};
const paintSend = () => {
  if (busy) return;
  const n = [...picked].reduce((a, id) => a + (PEOPLE.find((p) => p.id === id).group || 1), 0);
  $('.msc-share__sl').textContent = n ? 'Send to ' + n : 'Send';
  send.setAttribute('aria-label', n ? 'Send to ' + n + (n === 1 ? ' person' : ' people') : 'Send');
};
people.addEventListener('click', (e) => {
  const b = e.target.closest('.msc-share__who');
  if (!b || busy) return;
  const id = b.dataset.id;
  if (picked.has(id)) picked.delete(id); else picked.add(id);
  b.setAttribute('aria-pressed', String(picked.has(id)));
  paintSend();
});
people.addEventListener('keydown', (e) => {
  const b = e.target.closest('.msc-share__who');
  if (!b) return;
  const bs = $$('.msc-share__who', people), k = bs.indexOf(b);
  const to = { ArrowRight: k + 1, ArrowLeft: k - 1, Home: 0, End: bs.length - 1 }[e.key];
  if (to === undefined || !bs[to]) return;
  e.preventDefault();
  bs.forEach((x) => { x.tabIndex = -1; });
  bs[to].tabIndex = 0;
  bs[to].focus();
});
q.addEventListener('input', paintPeople);

/* ---------- send: idle → sending → sent → idle ---------- */
form.addEventListener('submit', (e) => {
  e.preventDefault();
  if (busy || !picked.size) return;
  busy = true;
  const names = [...picked].map((id) => first(PEOPLE.find((p) => p.id === id)));
  send.dataset.state = 'sending';
  $('.msc-share__sl').textContent = 'Sending';
  msg.readOnly = true;
  later(RM.matches ? 300 : 900, () => {
    send.dataset.state = 'sent';
    $('.msc-share__sl').innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6.5 12.5 3.6 3.6 7.4-8"/></svg>Sent';
    showToast('Sent to ' + (names.length > 2 ? names.slice(0, 2).join(', ') + ' and ' + (names.length - 2) + ' more' : names.join(' and ')));
    later(1300, () => {
      picked.clear();
      msg.value = '';
      msg.readOnly = false;
      busy = false;
      send.dataset.state = 'idle';
      paintPeople();
      paintSend();
      const b = $('.msc-share__who', people);
      if (b && sheet.contains(document.activeElement)) b.focus({ preventScroll: true });
    });
  });
});

/* ---------- copy link + targets ---------- */
const copyText = (text) => new Promise((ok, ko) => {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(ok, ko);
    else ko();
  } catch (err) { ko(err); }
});
copy.addEventListener('click', () => {
  clearTimeout(copyTimer);
  copyText(URL_TEXT).then(() => {
    copy.dataset.state = 'done';
    showToast('Link copied');
  }, () => {
    copy.dataset.state = 'fail';
    url.focus();
    url.select();
  });
  copyTimer = later(1800, () => { copy.dataset.state = 'idle'; });
});
$('.msc-share__targets').addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  const d = b.dataset.do;
  if (d === 'repost' || d === 'save') {
    const on = b.getAttribute('aria-pressed') !== 'true';
    b.setAttribute('aria-pressed', String(on));
    $('.msc-share__tl', b).textContent = d === 'repost' ? (on ? 'Reposted' : 'Repost') : (on ? 'Saved' : 'Save');
    showToast(d === 'repost' ? (on ? 'Reposted to 1,906 followers' : 'Repost removed') : (on ? 'Saved to Reading list' : 'Removed from Reading list'));
  } else if (d === 'text') {
    copyText(TITLE + ' ' + URL_TEXT).then(() => showToast('Title and link copied'), () => showToast('Copy blocked by the browser'));
  }
});

/* ---------- open / close / drag ---------- */
let open = true;
const setOpen = (v, focus) => {
  open = v;
  root.dataset.open = String(v);
  opener.setAttribute('aria-expanded', String(v));
  sheet.style.setProperty('--msc-share-dy', '0px');
  if (v) { post.inert = true; sheet.inert = false; if (focus) sheet.focus({ preventScroll: true }); }
  else { post.inert = false; sheet.inert = true; if (focus) opener.focus({ preventScroll: true }); }
};
opener.addEventListener('click', () => setOpen(true, true));
$('.msc-share__x').addEventListener('click', () => setOpen(false, true));
scrim.addEventListener('click', () => setOpen(false, true));
root.addEventListener('keydown', (e) => {
  if (!open) return;
  if (e.key === 'Escape') { e.preventDefault(); setOpen(false, true); }
  else if (e.key === 'Tab' && sheet.contains(document.activeElement)) {
    const f = $$('button, input', sheet).filter((x) => x.offsetParent !== null && x.tabIndex >= 0 && !x.disabled);
    const k = f.indexOf(document.activeElement);
    if (e.shiftKey && (k <= 0)) { e.preventDefault(); f[f.length - 1].focus(); }
    else if (!e.shiftKey && k === f.length - 1) { e.preventDefault(); f[0].focus(); }
  }
});

let drag = null;
sheet.addEventListener('pointerdown', (e) => {
  if (!e.target.closest('.msc-share__grab, .msc-share__head') || e.target.closest('button')) return;
  drag = { y: e.clientY, t: performance.now(), dy: 0, v: 0 };
  sheet.setPointerCapture(e.pointerId);
  root.dataset.drag = '';
});
sheet.addEventListener('pointermove', (e) => {
  if (!drag) return;
  const now = performance.now();
  const dy = Math.max(-18, e.clientY - drag.y);
  const rubber = dy < 0 ? dy / 3 : dy;
  drag.v = (dy - drag.dy) / Math.max(1, now - drag.t);
  drag.dy = dy; drag.t = now;
  sheet.style.setProperty('--msc-share-dy', rubber.toFixed(1) + 'px');
});
const endDrag = () => {
  if (!drag) return;
  const d = drag;
  drag = null;
  root.removeAttribute('data-drag');
  if (d.dy > 110 || (d.dy > 24 && d.v > 0.55)) setOpen(false, true);
  else sheet.style.setProperty('--msc-share-dy', '0px');
};
sheet.addEventListener('pointerup', endDrag);
sheet.addEventListener('pointercancel', endDrag);

/* ---------- comb thumbnail: pointy-top hexagons, a few capped and a few full of honey ---------- */
(() => {
  const R = 13, w = Math.sqrt(3) * R, rows = 14, cols = 14;
  let comb = '', cap = '', honey = '';
  const hex = (cx, cy, r) => 'M' + [0, 1, 2, 3, 4, 5].map((k) => {
    const a = Math.PI / 180 * (60 * k - 30);
    return (cx + r * Math.cos(a)).toFixed(1) + ' ' + (cy + r * Math.sin(a)).toFixed(1);
  }).join('L') + 'Z';
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const cx = c * w + (r % 2 ? w / 2 : 0), cy = r * R * 1.5;
    comb += hex(cx, cy, R - 1.2);
    const d = Math.hypot(cx - 250, cy - 40), n = Math.sin(c * 12.9898 + r * 78.233) * 43758.5453 % 1;
    if (d < 95 && Math.abs(n) > 0.3) cap += hex(cx, cy, R - 3.4);
    else if (d < 150 && Math.abs(n) > 0.62) honey += hex(cx, cy, R - 3.4);
  }
  $('.msc-share__thumb').innerHTML = '<svg viewBox="0 0 320 180" preserveAspectRatio="xMidYMid slice"><path class="msc-share__honey" d="' + honey +
    '"/><path class="msc-share__cap" d="' + cap + '"/><path class="msc-share__comb" d="' + comb + '"/></svg>';
})();

paintPeople();
paintSend();
setOpen(true, false);
